/* 平成18年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h18.committeeSessions.push(...[{"id":"h18-20060828-5","meetingId":"h18-cm08","date":"2006年8月28日","dateIso":"2006-08-28","committee":"総務委員会","time":"午後１時０２分～午後２時４３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、報告事項","agenda":"の１、報告事項","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"それともう１点、あとはこれは都区間の協議というところで、５２％という割合の問題なんですけれども、亡くなられた区長がいろいろ奔走しまして、一定程度平成１９年度からの割合のところでいろいろ協議がされたようですけれども、実際にこの点での協議というのはどういう状況下にあるのかというのを教えていただきたい。","respondent":"日下部企画財政課長","answer":"ご答弁申し上げます。いずれも５課題にかかわる内容ではありますけれども、ご質問にご答弁申し上げる上では、どうしても避けて通ることはできませんので、その辺をちょっと簡単にご説明します。先に都区間の協議の問題ですが、これは先ほどご説明の中で申し上げました５２％です。","voiceIndex":6,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"先ほどの割合について、来年度に向けた協議でやると。この問題というのは、いつも財調の場合なんかは１２月ごろとかに協議が始まるみたいですけれども、この問題での特別な協議ということではなくて、通常の財調の協議の中で行われるのだということでいいんですかね。","respondent":"石田委員長、日下部企画財政課長","answer":"さっきも言っているように、これは当初算定で、普通の平成１９年度の財調協議とは違って、１９年度の財調協議は非常に主要５課題に絡む問題で、今説明があったように、学校のこと、三位一体のこというのは。この配分率の問題につきましては、基本的に５課題のお互いの都区間の合意の中で、平成１９年度の通常協議の中できちんと解決を図りましょうと、そのような形で合意をみたです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"新しい区長の任期が平成２２年１０月７日までということでしたけれども、これまで品川の場合、区長選挙、区議会議員選挙を同期日でやられてきましたけれども、４年を過ぎた時点での区長選挙というのは、やはりこの期日というか、１０月からの４年間の任期で行われていくのかとか、ちょっとそこら辺だけ教えてください。","respondent":"野田口選挙管理委員会事務局長","answer":"今の公職選挙法の定めによると、ずれてということになります。","voiceIndex":15,"id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"もう１点、実際、区民にとって区議会選挙が、また補選をやって、また約６カ月後に再度また本選ということでいくわけですけれども、その費用もそうなんですけど、またすぐやるんじゃないのかなと。やらなきゃいけないのかなというところで、非常に疑問に思う方もおられると思うんですけど、その辺について、いろいろ条例等があると思うんですけれども、お聞かせください。","respondent":"野田口選挙管理委員会事務局長","answer":"今回、補正予算ということで、専決処分だと思いますけれども、１億３,４６７万円ということで予定しています。まだ正式決定はいただいてございませんけれども、そのぐらいです。","voiceIndex":17,"id":"exchange-004"}]},{"id":"topic-02","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"山村委員","kind":"質問","question":"こういう中でとりあえず何点か、ちょっとわからなかったというか、先に聞きたいのが、１ページ目の国の取り組みの採用試験制度の見直しなんですけど、Ｉ種・II種・III種の区分は維持するが、採用試験区分にとらわれない能力重視の人事管理を推進するということは、例えばIII種で受かった人が、能力によってはその後、II種、Ｉ種の区分に配置換えというか、出世するというか、そういうこともあるし。","respondent":"榎本人事課長","answer":"１点目の区の取り組みの関係につきましては今、検討しておりまして、しかるべき時期にまたご報告をしたいと考えています。ほかの市区町村の検討もあわせてやっておりますので、そのときにご報告いたしたいと思います。","voiceIndex":23,"id":"exchange-005"},{"speaker":"山村委員","kind":"質問・要望","question":"どうもありがとうございました。それともう１つ聞こうと思ったのが、３ページの東京都の取り組みの人材の確保の採用チャネルの多様化なんですけれども、まず新規学卒者の採用は人物重視とあるんですが、基本的に普通は人物重視だと思うんですけど、今までは何だったかと。人物重視というのはどういう基準になっているのかよくわからないので、そこをちょっとこんな感じだろうというのを教えていただきたい。","respondent":"榎本人事課長","answer":"ですから、大学卒の中でこういった部分もあったです。今後、今、検討中か、発表されたと思いますけれども、来年度の東京都の選考から、大学院卒の枠を別枠で設けまして、そこで大学院卒の資格のもとに採用をしていくというものです。","voiceIndex":25,"id":"exchange-006"},{"speaker":"山村委員","kind":"質問・要望","question":"そこまでよく僕も理解できていないのでそれを説明していただきたいのと、これからは例えば区が独自に採るということはどうしてもできないのかという、試験等ですね、採用するやり方自体を。今までどおり共通にやった後の面接だけなのか、そこら辺、今後何か変わることがあるのかどうか。","respondent":"榎本人事課長","answer":"それから今ちょっと検討されているのが経験者採用ということで、事務系、技術系につきましては、経験者採用の部分が今、２３区全体で検討されておりますので、やはりその団塊世代の退職後に向けた人材の構成というものに関して検討を進めているという状況です。","voiceIndex":27,"id":"exchange-007"},{"speaker":"山村委員","kind":"意見","question":"これはこれにかかわるのかどうかわからないんですけれども、教職員はこれにあてはまらないのかというのは、東京都だと思うんですけれども、教職員の採用の仕方というのは、こういう流れの中でまたちょっと変わってくるものがあるのか。いわば区分別に考えたほうがいいのか。","respondent":"榎本人事課長","answer":"教員の選考につきましては東京都が任命権を持つということで、東京都が一括して採用試験をやっておりますので、普通の事務・技術系の試験とは別のものと考えています。","voiceIndex":29,"id":"exchange-008"},{"speaker":"山路委員","kind":"意見","question":"先ほどちょっと出ましたけど、団塊の世代の大量退職の穴埋めとして新規採用と両方、職務の充実ということを考えますとかなりアンバランス、その辺の穴埋めといいますか、それはどういうふうに検討されているのか。新規の方がすぐには仕事ができるわけじゃないですよね。ということは、専門とか民間とか、いろいろなところまで手を伸ばして、職務充実に向けてのいろいろなことを検討されているのかどうか。","respondent":"榎本人事課長","answer":"４割というとかなりの人数になりますので、その間の人材の補充というものは、もちろん新規採用も考えておりますけれども、それだけではなく経験者採用ですとか、民間企業からの経験者等も十分検討しておりますし、逆にやめるほうの方の再任用制度の中でどれぐらい今までの経験。","voiceIndex":31,"id":"exchange-009"},{"speaker":"山路委員","kind":"意見","question":"そういうものを含めてのお話かなと思うんですけど、地方なんかに行きますと、地方出身の人が都会からＵターンで帰ってくるときに、簡単な調査で県の職員として１年間採用しますよ、そういうのをあらゆるところに送っているということなんですけど、そういう民間を雇用することだけで穴埋めができていくかどうか。５年先、１０年先のことも考慮して検討に入っているかどうか、ちょっと聞かせていただけますか。","respondent":"榎本人事課長","answer":"配置転換、自己啓発、研修等も含めまして、どのように図っていくかというところで能力アップを図って、採用者のノウハウをどうつけたらいいかというものの検討、それからあと実際上、管理職等を含めましても。","voiceIndex":33,"id":"exchange-010"},{"speaker":"山路委員","kind":"意見","question":"品川区の職務がずっと安定をしていきますと、地域と行政との関係というのが出てきますけれども、地域で、ほかの行政とかほかのところ、いろいろノウハウを持った人、そういう形の採用も今言われた中に考えているのかどうか。その辺のことまで検討に入っているのかどうか。","respondent":"榎本人事課長","answer":"今現在、品川区でも区と区民の間の協働をどういうふうに進めていくかということで検討しておりますけれども、その中で、職員を採用して協働するというのも１つの手段という形でありますけれども、その場合につきましては、非常勤職員ですとか、アルバイトの職員ですとか。","voiceIndex":35,"id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"１点だけ。今のご答弁の中であった、成果主義を取り入れて職員のやる気を高めていくんだという話がありましたよね。評価をどういうふうにするのかというのがよくわからないんですよ。試験を受ければ昇任できるんだけど、その前段での成果というのは一体何なのだというのを、もう少し明確に教えていただければと思います。","respondent":"榎本人事課長","answer":"昇任試験も当然人材として能力アップを図る上での１つの手段ですけれども、それ以外にふだんの仕事をしている中でも、きちんと仕事をしたについてはきちんと評価をして昇級をするような形に持っていくということで、普通昇級、勤勉手当等に反映させていくという形で今。","voiceIndex":37,"id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"これは東京都の取り組みですけれども、３ページにある第３の組織が求める人材像の明確化というところで、先ほどの説明で、長期的な視点でこういう人材を確保していくんだという話がありましたけれども、当然品川区の職員であるにしても、東京都の職員であるにしても、試験を受けられて、それなりの能力を持った方たちが認証されるわけですけれども、それでもその中で仕事のできる能力というのは。","respondent":"榎本人事課長","answer":"この昇任試験制度の部分と長期的な視点という部分で、まず昇任試験につきましては、一定の年限が来ないと昇任試験を受ける資格がございません。例えば主任主事ですと２級歴７年という形で、それまでは仕事ができる人もできない人も昇任試験の資格が得られないという形です。","voiceIndex":39,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"この品川区はこれだけ立派なことをやられてきているんですから、そういう経験者はできるだけ次の世代の方に能力なり技術なりを、きちっとつなげるような仕組みをとっておかなきゃいけないんじゃないかなと。ですから念には念を入れて、ペーパーテストだけでなく、ぜひ人物重視ということで、面接によってできるだけいい人材を品川区のほうに残せるように工夫していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"昇進の制度についてお伺いしたいんですが、今、品川区でもいわゆる管理職になるときには、あの難しい管理職試験を１回で受かった方もいれば、何回か受けて受かって、課長職になられていると思うんですけれども、管理職試験に受かるという、いわゆる頭がいい方たちというのは、実際に課長職という職についたときに、試験が受かったからイコール仕事ができるというふうな判断をしているんでしょうか。","respondent":"榎本人事課長","answer":"従来２３区の統一で管理職試験という形でございましたけれども、それは各区の独立性が生かせるような形に改正していこうということで、実際に試験で面接するにつきましては、区の管理職が面接にタッチできるような形になっておりますし、実際上。","voiceIndex":43,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"私は難しい筆記試験だと思っていたんですね。最初に公務員になるときのような試験をまたやるのかなと思ったら、そうではなくて、適性を調べるのだということであるならば、またシステムを変えないで、このまま管理職試験をやっていけばそのままでいいと思うんですけれども、そことふだんの仕事を見て昇進も考えるというところの差というのは何なんでしょうか。","respondent":"榎本人事課長","answer":"２３区におきましても、やはりそういう試験制度の若干受験離れというのがありますので、その部分につきましてもきちんと見直していこうということで、管理職制度につきましても、管理職になりたい年齢というのはそれぞれのライフプランの中で。","voiceIndex":45,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"民間だったら、例えば売上とか財務能力とかいろいろあると思うんですけれども、いわゆる公務員が仕事ができるというふうに評価されるというのは、いろいろあるとは思うんですけれども、人事が考える仕事ができる公務員というのは、評価という意味で、どういうところなんでしょうか。","respondent":"榎本人事課長","answer":"さらにいろいろな改革をする上で、やることによって波風もなるべく少なくして、きちんと改革も長期的な視点で見て進められるという場合が、仕事ができるという形ではないかと考えております。","voiceIndex":47,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"今、仕事ができる人は伺ったんですけれども、逆に見ていてできない方というのもあると思うんですね。だけれども、どう見て人事を考査して、たしか課長の人事権は区長でしたっけ。ですよね。そういう場合は、今、課長が仕事ができるのはこういう面だと言ったんですが、逆にできない面、しかし管理職試験には受かっているかなという場合には、どのような人事を区としてはしていくんでしょうか。","respondent":"榎本人事課長","answer":"だんだん答えづらい問題になってきたんですけれども、仕事ができない管理職というのは管理職として失格かなと考えておりますので、病気ですとか身体的な状況でできないということであれば別ですけれども、仕事が通常できて、試験に受かっているというからには。","voiceIndex":49,"id":"exchange-018"},{"speaker":"山村委員","kind":"質問","question":"質問でいろいろ聞きたいんですが、現行の公務員制度というのは、ある意味ものすごく社会主義的な制度だと思うんですけれども、民間の会社とくらべると平等主義というか。いわゆる民間の企業。ただ民間の企業と同じようには絶対にできないとおっしゃるんだと思うんですけど、そのすれすれでできないところというのは、幾ら近づけていってもできない部分というのは何かというのを教えていただけますか。","respondent":"榎本人事課長","answer":"ただその枠内の中で動いていても、先ほどの団塊世代等の退職等を考えますと、民間の優秀な人材を途中からでも採らなければいけないだろうとか、そういう経験・ノウハウをつける人は、公務員で育てるのも１つですし、民間から採るのも１つですし。","voiceIndex":51,"id":"exchange-019"},{"speaker":"山村委員","kind":"意見","question":"今後そういう努力もされるのかどうか。４割いなくなるから大変だといったって、逆にまだむだなところは絶対あるわけですし、逆に公務員として正式に採用している人じゃなくてもやれる業務はいっぱいあるんじゃないかと思うんです。品川区ではどうなのか。いなくなればいなくなっただけ削れちゃう部分みたいなところは、今後どういうふうに考えないといけないのか。","respondent":"榎本人事課長","answer":"２つ目の４割いなくなるということですけれども、やはり４割をそのまま補充するのではなく、補充はその一部分にとどめて、実際上は職員の能力アップで生産性を向上させる部分で補充するのが１つ、それから民間委託等の中でどのような形であれば、今。","voiceIndex":53,"id":"exchange-020"},{"speaker":"山村委員","kind":"質問","question":"実際アメリカは自分で自分のことをマネジメントしていかないと、もともとその会社にずっといる気もないわけですから、ほとんどのアメリカ人は。民間というのはヘッドハンティングしてくるわけですから、そこまではいけないわけだということだと思うんですけれども、そうすると、今までのように育てていくということなんだとは思うんですが、やっぱり育てていくといったって、結局自己努力だと思うんですよ。","respondent":"榎本人事課長","answer":"そういった意味でいくと、やはり人材というものを継続的、持続的に育ててきちんとつないでいかないと、そういう政策自体が継続性がなくなってしまうということになっちゃいますので、短期的に考えれば民間の優秀な人を持ってきて。","voiceIndex":56,"id":"exchange-021"},{"speaker":"山村委員","kind":"意見","question":"実際のところこれは所管事務調査ということで、日本の公務員制度だけを見ていてもわからないので、資料で、先進６カ国ぐらいの公務員制度がどのようになっているのかというのを、公務員制度というのは見本がないんですね、日本国内を見たって。だから、海外の資料なんかがちょっとでもあったほうがいいんじゃないかなと思って、そういうのがあればということを言いたかったです。","respondent":"石田委員長","answer":"それは委員会として検討させてもらいます。","voiceIndex":58,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問・要望","question":"自治体から現場の声が、我々の悩みは今の制度の中でこれだよということが、法改正を伴うわけですから、そのやりとりがあるのか、吸い上げる経過があったのかということが全然見えてこないので、そういうことに関する今の時点でのお話があればお願いします。それと同時に政治の場で、我々は自治体の政治家ですから、そこを指摘し、それがまとまって国に持ち上がってくる。両方必要なわけです。","respondent":"榎本人事課長","answer":"ただ、今現在、区における人材育成方針というのを検討中でございまして、その中にこういうふうに盛り込んで、こういう方針で今後１０年、２０年の中で、どういう人材を育てていけばいいのかというものを含めて検討を進めていくです。","voiceIndex":60,"id":"exchange-023"},{"speaker":"塚本委員","kind":"意見","question":"それはいろいろなこと、２３区レベルで言えば働きかけが弱いから、自分たちの中の問題意識をしっかりつかまえて、それを自分たちだけじゃないな、共通の仕事をしようよという認識があればそこは動いてくるはずなんですが、あまり動いているようには現時点では見えないんですけれども、特区協のありようについては何かお話がいただけますか。","respondent":"濱野助役","answer":"そういう方々との乖離というか、生活実感だとか生活対応だとかというものが、公務員だけ違うというのはおかしいじゃないかというのが１つの考え方でありましょうし、あるいは組織運営上、意識の問題として民間組織の社員の意識と。","voiceIndex":62,"id":"exchange-024"},{"speaker":"塚本委員","kind":"質問・要望","question":"民間流の経営がすべてだとは私は思いません。歴史、風土、それから時代に合ったものを求めていくべきだと思います。所与の条件だけで考えるだけではなくて、あるべき姿、ひょっとして物を変えられるんじゃないか、そういう発想をしなければ仕事はできない、そういう人材を求めているんだよというお答え、いたく我が意を得たという思いがしますので、どうぞその方向で頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1728#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":31467,"voices":69}},{"id":"h18-20060829-11","meetingId":"h18-cm08","date":"2006年8月29日","dateIso":"2006-08-29","committee":"自治制度特別委員会","time":"午後１時０３分～午後３時１９分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"林（宏）委員","kind":"確認","question":"確認しますけれども、３ページのほうで言うと、平成１８年度に限りということは、今年度に限ってということで、来年度以降はないということですか。それから、２ページの数字については、ややこしい算定基準があるのだけれども、品川区として納得をしている数字なのかどうか、その辺をまず聞かせてください。","respondent":"日下部企画財政課長","answer":"ただ、先ほどもご説明申し上げました財調のルールに準じた算定方法という形で、２３区として一致できる基本的な算定式ということで考えていきたいという説明がございまして、最終的にはこれについて同意をしたというものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"意見","question":"平成１９年度以降ですけれども、何回も同じことを言うけれども、向こう１０年近く小中学校については学校改築を続けていくのだけれども、それについて財調の考え方というのはどのように示されているのか、それを聞かせてください。それから、なぜ１５０億円と５０億円に分けたかという、その説明をしていただけますか。","respondent":"日下部企画財政課長","answer":"３点のご質問のうち、２点目の区長会の了承ということについて、事前の説明ですけれども、まさしくご指摘いただきましたとおりでございまして、私の説明の中で、冒頭に区長会に説明があったということだけではなくて、了承されたという経過について。","voiceIndex":7,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"意見","question":"精算されて平成１９年以降、これから協議を進めていくだろうと思うけれども、一説によると学校規模を保ちながら改築をするというのが一つの条件になって、それを満たさない場合は出さないという、国もそのようなことを言っているやに聞くけれども、公式ではないでしょうけれども。","respondent":"日下部企画財政課長","answer":"２点目ですけれども、本日の第３回目の検討会は、都区の役割分担に応じた財源配分のあり方をはじめとして、都区間の基本的な根っこにある課題についての協議ということですので、そういう意味では、この先を見越した議論という形になってくると思います。","voiceIndex":9,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"２００億円というのは決まっていたようなところの話で、東京都が正式に返事をしたと考えるのが妥当というか、そのようなものだろうと思います。その後、まずは基本的に高橋区長の考え方を踏襲していくということでいいのかどうかというのが一つ答えていただきたい。それから交付金の使途が３種類ありますけれども、品川区はどのような意向を持っているのか、現段階でわかっていれば答えてください。","respondent":"日下部企画財政課長","answer":"しかも、それをさらに詰められて、今後の都区のあり方はいかにあるべきかということも含めて、大きな流れがつくられてきた経緯もありますので、私どもとしましてはやはり引き続きの課題について一生懸命取り組んでいく必要があると考えているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"意見","question":"充当するというのは、そのようなことでしょう。来たお金を充当させるというと、予算の中の７０億円ぐらいの中に入れるということになると、一般財源のほかのところで７億円浮くという話になるのだけれども、そのように理解するのか、あるいは７億円はやっと話がついたので、新たに積み立てに置くということなのか、充当というのが少し引っかかるのだけれども、その辺をもう１回説明してください。","respondent":"日下部企画財政課長","answer":"そういう意味では、基金の取り崩し分を７億円ほど圧縮することによって、基金の総額として７億円が逆に基金の中にそのまま残るという形で整理してまいりたいと考えているところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"考え方が少し違うのではないですか。それが逼迫していて、今年度の基金の積み立てだとか改築費にようやく回ったということであれば、正確な数字はよくわからないけれども、改築費が５０億円、基金が幾らかわからないけれども、例えば基金として積み立てるのが３億円、４億円、それから取り崩しというのは、取り崩してなおかつ維持できるという考えの中で予算を組んでいるわけではないですか。","respondent":"日下部企画財政課長","answer":"ですから、歳出のほうは、新たに学校改築費として起こすということは今年度は無理ですので、逆にその分は、先ほど申し上げましたように基金からの繰入金を逆に減らすことができますから、それを来年度以降に有効に活用するという形で。","voiceIndex":15,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"意見","question":"考え方が違うと言っているのです。基金を幾ら崩すか正確ではないけれども、例えば、基金から２０億円取り崩して、今年の改築費に充てると基金が２０億円減ると、それはそれなのです。さらにこれから２０年近くの間、学校改築が連続して進むのだから、そのために基金が要る。だけど、今年の基金の積み立は１億５,０００万円か２億円か予定しているわけで、それに上乗せをするのだと。形はわかる。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-007"},{"speaker":"土井委員","kind":"質問","question":"要するに、清掃関連経費を見て分けましょう、このようなところを見て分けましょうとか、何でも構わないわけだけれども、財調全般の分け方と類似したことでもあってほしい。そして、平成１８年度に限り小中学校改築の補正として２００億円を準備するとなるべきだったのが、そうなっていない関係はいかがでしょうかということです。","respondent":"日下部企画財政課長","answer":"合意事項の点ですけれども、確かに土井委員ご指摘のように、清掃関連経費及び小中学校改築についての課題の整理ということで、具体的な３課題のうち二つについて、このような形で整理すると表現されているのですが、実は基本的な合意はこの点なのです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"土井委員","kind":"質問","question":"そうすると、はっきり交付金の使途以外は使ってはいけないとしめしをつけられました。したがって、品川区は改築事業基金へ積み立てることにいたしますとか、元利償還金にいたしますとか、何％が元利償還金で何％が改築事業に要する経費ですと言うかどうかしなければいけないわけです。それをきちんと言わないから、そのようなことになるのではないですか。","respondent":"日下部企画財政課長","answer":"それが将来の備えにもつながるわけですから、そういう意味ではご質問に対しまして説明不十分ということで申し訳なく思ってあります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"今の答弁ですけれども、一般財源は一般財源です。区の方針として、学校改築に積み立てるという区の考え方ではないのですか。特別交付金でおりてくるけれども、あくまでも財調の交付金の一環だから、例えば今までは災害などの５％分があるではないですか。あれは結局、一般財源としておりてきて、実際にどのようにやるかは各区の判断というレベルではないですか。","respondent":"日下部企画財政課長","answer":"もう少し、踏み込んだ説明をさせていただければよかったのかなと思います。","voiceIndex":22,"id":"exchange-010"},{"speaker":"沢田委員","kind":"意見","question":"学校独自の積立金があるのか、その辺がはっきりしないのですが、今までの説明で、学校改築に対しては都がいろいろな財調参入をして、そこに積み立ててきたことがあるのではないかと思うのだけれども、それはなかったのかどうかということ。先ほどの説明で、学校の単価だとか何だとかは今後の問題だと言われた中身ですけれども、そこがもう一つわからないので、説明を願えるとありがたいです。","respondent":"日下部企画財政課長","answer":"これは２３区全体のいろいろな実態調査の結果ですが、それに対して今の財調の単価は２３万円ということで、実態と財調の算定の基準になっている金額の間で差があるということも含めて、改善が必要だという内容です。","voiceIndex":24,"id":"exchange-011"},{"speaker":"沢田委員","kind":"意見","question":"今度のものは平成１２年から過去の精算ということと、平成１８年度以降については、今言った単価の問題、規模の問題を含めて、精算とは別に問題があるので、それは今後の協議がそこに集中していくという判断でよろしいですね。","respondent":"日下部企画財政課長","answer":"そのとおりです。こちらの図表にありますが、平成１８年度の精算解決と残された課題について、平成１９年度以降についても具体的な課題としてまだ残されておりますので、この辺はしっかりと今後とも取り組みをしていくです。","voiceIndex":26,"id":"exchange-012"},{"speaker":"本田委員","kind":"質問","question":"つまり、このような形で今回２００億円の特別交付金を精算するわけですが、ものの考え方として東京都は平成１９年度以降は別立てで考えて対応していくという話ですが、考え方の差はぶつかり合いになっていくのではないかと、その辺はどうなのでしょうか。","respondent":"日下部企画財政課長","answer":"例えば、具体的な数字で申し上げますと、以前主要５課題のご審議をいただいたときに、具体的な数字として挙げさせていただきましたが、ピーク時への対応ということで、２０年間、２３区の学校改築が集中するとなると、大ざっぱな試算ですが。","voiceIndex":28,"id":"exchange-013"},{"speaker":"石田委員","kind":"質問・要望","question":"確認だけさせてください。精算は精算で結構です。だけど、ここで１回ゼロになるのかならないのか、そこも教えていただきたい。そこの考え方は、すべてゼロになるのか。となってくると、品川区は数が多すぎるのではないですかと言われているのは事実なわけだから、そうなってくると数をこれぐらいで算定したほうがいいでしょうと、必然的に統廃合は必要なのかなと。その辺の考え方を教えていただきたい。","respondent":"日下部企画財政課長","answer":"区側としては、このような主張をしまして、まだ残された具体的な課題についての見通しを早くつけないことには、例えばこれから改築に着手しようとしているところも、なかなか改築の決断ができないとか、そのような問題につながっていきますので、やはりこの際。","voiceIndex":32,"id":"exchange-014"},{"speaker":"石田委員","kind":"確認","question":"１点だけ、その中で確認をしたいのは、例えば基金を積んでこなくて、きちんと積んだけれども学校改築に使ったところはいいけれども、基金を使わないで、基金も積み立ていないし、学校改築が未着手で、なおかつそのお金はほかに使っていた区があると思います。そのようなところは、ここの協議のときに、いよいよ始まるわけです。そうすると、丸抱えである程度くださいという話になってしまいます。","respondent":"日下部企画財政課長","answer":"この間の話というのは、２３区はどうなのだというより、やはり都との関係の中で、単価の問題とか規模の問題であるとか、当面する課題をどうやって２３区が一致団結して解決したらいいかと、どちらかというと、そちらのほうに力点がずっとかかってきておりますので、今。","voiceIndex":34,"id":"exchange-015"},{"speaker":"石田委員","kind":"意見","question":"１,０００億円ずつだけれども、都は増やしてあげたいけれども４００億円だというと、そのところに踏み込まないと、なかなか実際のお金の取り合いになったときに、やはり水平調整がしっかりできていないと、一致団結も崩れてしまう話が必ず出てくるわけだから、出ていないからいいというだけではないけれども、見通しの考え方はどう思われているのか。","respondent":"日下部企画財政課長","answer":"つまり、２３区側がお互いの意思統一ができるような形になっているのかどうかというご懸念かと思いますけれども、なかなか難しい点はあろうかと思いますけれども、その辺の実務レベルでどの程度まで議論ができるかわかりませんけれども。","voiceIndex":36,"id":"exchange-016"},{"speaker":"沢田委員","kind":"質問・要望","question":"これから本格的に３校ぐらいずつやって、中には一貫校でまとめてやることがあるから、いろいろ複雑に展開すると思うんですが、学校改築にあたっての財源構成はどのようなシステムになっているのか、わかる範囲で教えていただきたい。精算だと言うけれども、今はどこまでなっているのか、考え方がわかったら教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"財源構成でまいりますと、大ざっぱに申しますと国庫補助が大体総額の１割ぐらい、実績ベースでまいりますと１割ぐらいです。起債が大体２割ぐらい、残り７割は一般財源で手当てをしているという形で財源構成はなされているです。","voiceIndex":38,"id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"一般財源の７割という答弁が先ほどあったのですが、一般財源のうちに財調分と区の持ち出し分、財調協議内容に係わる問題だと思うんですが、それはどういう見方をしているのでしょうか。","respondent":"日下部企画財政課長","answer":"具体的に申し上げますと、平成１７年ですと、学校改築経費として需要算定が、品川区だけで大体６億８,０００万円とされております。今持ち合わせていないのですが、平成１７年度の学校改築に必要な財源は、平成１７年度は一貫校とかいろいろありまして多かったのです。","voiceIndex":40,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"何度も申し訳ないけれども、６億円というのは、確か平成１７年度は３校だったと思うんですけれども、３校で６億円ですか。","respondent":"日下部企画財政課長","answer":"１校あたりではなくて、総額ですが、その辺は数字を確認した上でご報告します。","voiceIndex":42,"id":"exchange-019"},{"speaker":"林（宏）委員","kind":"確認","question":"確認しておきたいのだけれども、今の話から離れるけれどもいいですか。先ほど来出ている財調を基準にしてとか、財調絡みでとかと言って数字が出てきたのだけれども、なぜ渋谷区とか千代田区は財調不交付のところにいくのかという説明が書いていないのです。なぜいくのですか。けんかしないのですか。","respondent":"日下部企画財政課長","answer":"２３区側としても、これは２３区としての受け入れを区長会で承諾ということでご説明申し上げましたけれども、これについては、ある程度そのような形での判断もせざるを得ないという形で、２３区で交付するようになった。それから、不交付は港区と渋谷区です。","voiceIndex":44,"id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問","question":"本当にそうなのですか。そうすると、今まで高橋区長がさんざん言ってきた自立とか都と今までの財調ではないところから脱皮するのだ、２３区は自立するのだというところから、一歩後退ですね。都側の言いなりで、不交付のところももらっていいよと。それから、もしこれを起点にするのだったら、これからの純粋な財調の中にこのような数字か入ってくるとしたら、渋谷区も港区もいくのですね。","respondent":"日下部企画財政課長","answer":"今回は純然たる財調算定上の問題だけでいけば、先ほどもご説明申し上げましたが１５０億円だけです。都側として、最終的には主要５課題をめぐるいろいろ経過の中で、最終的には５０億円を加算する形で合計２００億円という形で整理をされた経過があります。","voiceIndex":46,"id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"だから、先ほど言った財調の考え方が、これから学校改築というところをどうとらえていくかということが、非常にあいまいのまま、東京都が適当ではないけれども、東京都の考えで、「ああ、そうですか、ありがとうあります」と受け取ったように受けとめるのだけれども、これは企画財政課長が受け取ったわけではなくて区長会が受け取ったから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-022"}]},{"id":"topic-02","title":"続きまして、(2)の清掃制度に関すること","agenda":"続きまして、(2)の清掃制度に関すること","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"売電をしてエネルギーをリサイクルしていくという考え方の背景にあるのは、廃プラスチックを燃やすことにより安定して供給してということが前提になっていくのではないかと思うんですが、その辺はいかがでしょうか。","respondent":"中山資源循環推進課長","answer":"結果的に、焼却売電量が上がってくると、試算のバランスがより売却益が上がっていく方向にいくということもありますけれども、ご質問にあったような、それを根っことして新会社を設立していくという考え方ではございません。","voiceIndex":53,"id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"そのことを折り込まないで、現行でやってこれだけの発電量を売電することができるということなのでしょうか。私が聞いたところによると、どれだけ可燃ごみが出てくるか、ごみだからコンスタントにいかない。８円幾らかで売ろうとすれは、安定供給というのは当然前提になると思うんです。例えば、廃プラスチックを燃やさなくても、新会社ですとその料金でやっていけるという結論になっているのでしょうか。","respondent":"中山資源循環推進課長","answer":"この段階で明確にお答えできる資料がございませんけれども、少なくとも現在の想定試算をする段階で、廃プラスチックのサーマルリサイクルを前提としているという説明はございません。","voiceIndex":55,"id":"exchange-024"},{"speaker":"沢田委員","kind":"質問・要望","question":"それはそれとして了としますけれども、売電で単価を上げるということが、新会社設立のかなりの動機になっています。私は、どうもそこに今回の廃プラスチックを燃やして燃料を確保するということがあるのではないかと、これは否定されていますから、それはそれで結構ですけれども、新たな状況があったら言っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-025"},{"speaker":"三村委員","kind":"質問","question":"２ページのところで説明をいただいたのですけれども、先ほど小売会社は２３社ぐらいあるという中で、公益企業というところでこの２社が出てきたと思うんですけれども、合併先がなぜこの２社だけなのか、ほかのところはなぜ対象外になったのか。公益企業以外のところにも、何か理由があるのか教えていただけますか。","respondent":"中山資源循環推進課長","answer":"これ以上、詳しい情報は私どもも存じあげておりませんけれども、そのようなメーカーとの関係あるいは焼却のノウハウから、基本的にはこの２社を相手側としたということになります。","voiceIndex":58,"id":"exchange-026"},{"speaker":"三村委員","kind":"質問","question":"発電プラントを持っていて、メーカーでないところは小売事業者としてないということでいいのですか。","respondent":"中山資源循環推進課長","answer":"全国に２３社ぐらい出ておりますけれども、首都圏の中で選ばれたということですけれども、その他のプラントを持っていないかどうかというのは、今日は明確にわかりませんが、関東圏にある特定規模電気事業者の中で。","voiceIndex":60,"id":"exchange-027"},{"speaker":"三村委員","kind":"質問","question":"特別措置法は平成２２年までという時限立法になっていますけれども、時限立法の今後の見通しだとか、特別措置法によって電気事業は安く買い叩かれている状況にあるかと思うんですけれども、資源エネルギーというところで、高く買い取ってもらえるような見通しはないのですか。","respondent":"中山資源循環推進課長","answer":"ＰＰＳというのは、直接実施する行為になるわけですから、電気事業者の取り分がなくなってくることによるメリットがあるというのが下の部分です。","voiceIndex":62,"id":"exchange-028"},{"speaker":"三村委員","kind":"質問・要望","question":"今回、清掃工場の運営委託と電気の小売事業ということで二つの柱があるかと思うんですけれども、清掃事業は詳しく出ているのですけれども、電気を販売することによって、どのぐらいコストがかかって、電気事業にどのぐらいの経費がかかって、どのぐらいの利益を見込んで、どのような体制になっているのか、新会社と２３区の関係はどのようになってくるのか。","respondent":"中山資源循環推進課長","answer":"売電の効果については、別紙の３ページの６に書いております。それが事業概要の積算の根拠になっている部分です。先ほど、補足説明で申し上げたように、今、大量に出しているところは８円で特定規模電気事業者に売っています。そのほか、東京電力に３.５円が現況です。","voiceIndex":64,"id":"exchange-029"},{"speaker":"三村委員","kind":"意見","question":"新会社のことをいろいろヒアリングをしてやっているのですけれども、どうしても東京ガスの利益が目立ってというか、東京ガスに引っ張られるような形で進んでいるように思えてならないのです。今回、廃プラスチックが入っていない形でこれだけの収益が見込まれるということですと、廃プラスチックを燃やした場合は、どの程度、収益の増加が想定されるのか、その辺のことはわかりますか。","respondent":"中山資源循環推進課長","answer":"先ほど、東京ガスの利益の割合云々というのは、私の手元にございませんけれども、当然企業ですからメリットがある出資をしていくですけれども、あくまでも主が東京ガスであるという説明は受けておりませんし、そのような認識をありません。","voiceIndex":66,"id":"exchange-030"},{"speaker":"三村委員","kind":"質問","question":"今回は廃プラスチックの焼却を盛り込んで新会社で売電をしてしていくということですけれども、廃プラスチックを焼却することによって清掃工場のリスクが高まってくると思うんです。少し新会社の話とずれてしまうかもしれないけれども、燃やすことによって安全性は確保できるのか、その辺はどうですか。","respondent":"中山資源循環推進課長","answer":"廃プラスチックのサーマルリサイクルについては、区民委員会のほうでモデル事業の実態であるとか、説明申し上げていますので、廃プラスチックの焼却についてのご説明は割愛しますけれども、１点だけ、清掃一部組合で示しているのは。","voiceIndex":68,"id":"exchange-031"},{"speaker":"三村委員","kind":"意見","question":"廃プラスチック焼却は切り分けてということですけれども、新会社の運営というところでは、やはり廃プラスチックの焼却は切り離せない部分があるかと思いますので、その辺の安全性についてもきちんと区民に対して説明されているかと思いますけれども、その際にも安全性についてきちんと誤解を招くような説明をせずに、ＮＨＫの放送で問題があるような放送をしていますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-032"},{"speaker":"原委員","kind":"質問・要望","question":"１点だけ、確認をさせていただきたいのですが、新会社設立によりまして、２３区への財政効果を試算されています。あくまでも試算の中での段階の話だと思うんですが、これをもとにして話しをされていると思いますが、試算の中でマイナスの部分の試算もあるのではないかと思うんですけれども、その話しというのは全然ないのですか。","respondent":"中山資源循環推進課長","answer":"当初は、一定期間、営業利益がマイナスになる部分は想定しつつも、早く黒字化してやっていくように努力していくというのが前提ですので、さまざまなところで歳出の工夫も含めて、企業として努力していくものであると考えております。","voiceIndex":73,"id":"exchange-033"},{"speaker":"原委員","kind":"質問","question":"企業として努力される部分はよくわかります。それまではマイナスの部分も出てくるということですが、試算の内容がそぐわない部分とかいろいろ出てくるのではないか。ただ、こうやっていいところから出てきて、効果的には削減される、それはわかりますけれども、試算そのものが正確なものなのか、あるいは推測があたっているものなのかどうかという部分があると思うんですが、その辺はどうですか。","respondent":"中山資源循環推進課長","answer":"これは現段階での想定ということになりますけれども、それは実際に企業として設立以降、速やかに一部事務組合を通じて各区に報告されるものですから、当然予定より下回るような状況があれば、何らかの指摘なり、出資する区側としても発言できるようになっておりますので。","voiceIndex":75,"id":"exchange-034"},{"speaker":"原委員","kind":"質問","question":"今の段階では、まず試算ですから、内容についてどうのこうのというと、なかなかわからないかもしれませんけれども、あまりにもいいことの積み重ねになっていますが、多少危惧しているところがあるので、その辺のところについては、今後の中でしっかり検討してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-035"},{"speaker":"石田委員","kind":"質問・要望","question":"すごく変な質問をしますが、教えていただきたいのです。","respondent":"中山資源循環推進課長","answer":"一義的には、清掃一部組合と出資する会社という形になりますから、そこの中で出資としての報告をこの会社を清掃一部事務組合に対して行われて、それが同時に２３区が設立した清掃一部組合という係わりの中で各区へ報告してまいりますから。","voiceIndex":78,"id":"exchange-036"},{"speaker":"石田委員","kind":"質問・要望","question":"もし競争原理を入れるのなら、「うちは２億５,０００万円でできます」というのが競争原理であって、あまり３億８００万円という試算が出ていくことによって、下げ止まりになる可能性があると思うのだけれども、このような考え方をしっかり抑えていかないと、相手が民間企業ですから、その辺の考えを民間同士が競争原理を働かせられるようなものを、下げ止まりを最初からつくるような試算というのは。","respondent":"中山資源循環推進課長","answer":"とりわけどのように考えているのだというところは、かなり考え方で問われていて、そこで具体的にどうしてこれが必要であるとか、本社経費であるとか、そういうものも本来企業であればきちんと示していくべきであるというご指摘。","voiceIndex":80,"id":"exchange-037"},{"speaker":"石田委員","kind":"質問・要望","question":"今、お話を伺っていて気になったのは、社員のプレゼンテーションを聞いているみたいな形があって、それは説明をいただいたから、それはそれで一つとして、今後は分担金を負担して出資する品川区としての立場での報告を、こういう問題点がある、こういうところをもっと伸ばせばよくなるとか、そういう視点のほうがいいと思うので、資料も出し過ぎみたいなところがあると感じているけれども。","respondent":"中山資源循環推進課長","answer":"この資料をできるだけ丁寧にという意味でご説明していましたけれども、そういう意味では、当然この会社に対してある種の厳しい目を持って見ていくというのは、区の立場からしてもきちんと見ていくですので、経費の削減等の努力についても、きちんと資料を見たり。","voiceIndex":82,"id":"exchange-038"},{"speaker":"山村副委員長","kind":"質問","question":"この会社は設立することは決まったのですか、まだ最終判断はしていないということですか。２３区が出資するわけで、どこも反対したところはなかったと考えてよろしいのでしょうか。","respondent":"中山資源循環推進課長","answer":"出資のスケジュールのところですけれども、清掃一部事務組合において、９月を目途に正式に清掃一部事務組合の中で出資の判断をしますから、基本的に議会に諮られるところですので、先ほど申し上げたように、何回も清掃一部事務組合の議会の中では。","voiceIndex":84,"id":"exchange-039"},{"speaker":"山村副委員長","kind":"質問・要望","question":"あまりにも絶対にできるみたいな気がしていたので、そこに違和感を覚えただけです。できるのはできるのでしょうけれども、２３区全部が出資に賛成したというか、それも区が決めるわけですね。反対する区はどこもなかったということなのか、そこだけ教えていただきたい。","respondent":"中山資源循環推進課長","answer":"繰り返しになりますけれども、出資そのものは清掃一部組合として行うということになりますから、清掃一部事務組合の議会での判断を受けるという形になりますから、２３区で報告をした際の部分というのは、区によってスピード感の差もあるわけですけれども。","voiceIndex":86,"id":"exchange-040"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"今の話と関連するけれども、前回の説明では各区が５２０万円ずつ負担をして、清掃一部組合が取りまとめて６１億２,０００万円を出資する。今日の説明ですと、各区の負担はなくして、清掃一部事務組合が１億２,０００万円を負担するように変わった経緯はどういうところにあるのですか。改めて、区の負担を求めないということですか。","respondent":"中山資源循環推進課長","answer":"そのときに、基本的な考え方として２億円程度の資本金に対して、清掃一部組合が６０％出資、残りは東京ガスが出資という形で、ここで言う負担というのは、直接出資は求めないということを言っております。","voiceIndex":88,"id":"exchange-041"},{"speaker":"林（宏）委員","kind":"質問","question":"招きやすいではなくて、全く違う表現ではないですか。","respondent":"中山資源循環推進課長","answer":"そういう意味では、６月の経営委員会、評議会の方向性からすると、ここの部分はこのまま残しておくと誤解を招くので、清掃一部組合の出資と残りは東京ガスの出資で、分担金にあり方については、各区が分担金の中で出資については充当するということで整理されております。","voiceIndex":92,"id":"exchange-042"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"改めて区の負担は求めないということは、５２０万円を出す必要はないという意味でしょう。その後に出てきた資料に、改めて区の負担を求めないということは、これをしないという意味ではないですか。今の副委員長の質問と関連すると聞いたのは、改めて区の負担を求めないと明確に書いてあるから、今度の議会にこのような議案が出てきたらおかしいではないかと言いますよ。明確にきちんと答えてください。","respondent":"中山資源循環推進課長","answer":"概要の資料につきましては、８月２９日付という形ですと、決定を変えたやに見える資料にありますけれども、これは新会社を設立するにあたって、かなり早い段階で清掃一部事務組合が作成した新会社の概要を、前回は概要のスキームを含めてお示ししてございませんでしたので。","voiceIndex":94,"id":"exchange-043"},{"speaker":"林（宏）委員","kind":"質問","question":"企画財政課長に聞きます。今度の第３定例会に分担金５２０万円は持ってくるのですか。","respondent":"日下部企画財政課長","answer":"そのような形で、区としては補正予算に計上するということで、今準備を進めてあります。","voiceIndex":96,"id":"exchange-044"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それは、きちんと資料をつくるときに言わなければおかしいです。「区の負担を求めない」と書かれていて、品川区だけボランティアで５２０万円出すのかという話にもなってくる。資料の前後にしたのはわかりました。最初に戻って、有限会社とか株式会社はわかるけれども、合弁会社というのは、どのような組織になるのですか。合弁会社というのは、どのような組織になるのかわかったら教えてください。","respondent":"中山資源循環推進課長","answer":"合弁というのは、要は主体である清掃一部事務組合という組織と東京都ガスという一つの主体が共同して設立する組織ということで合弁事業という事業名を言ってもので、合弁会社という形になっていますけれども、事業に着目した合弁という表現ということで。","voiceIndex":98,"id":"exchange-045"},{"speaker":"林（宏）委員","kind":"質問","question":"株式会社の組織で運営するということですね。株式会社だとすると、会社組織がつくられていくときに、清掃一部事務組合が６０％の出資だとすると、社長がだれかＣＥＯとして入っていくわけです。その辺は、どのような形態になっていくのですか。そのための筆頭株主なのでしょう。全く経営の素人が入ってくるという形が生まれるのだけれども、それはどのように聞いていらっしゃいますか。","respondent":"中山資源循環推進課長","answer":"先ほど、事業主体がどうかという話があって、あくまでも清掃一部事務組合が主体になっていくという形ですので、企業ですから社長を設けることになると、清掃一部事務組合の管理者が社長に就任するものと考えられます。","voiceIndex":100,"id":"exchange-046"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"株式会社になったら、社長は無給というわけにいかない、そんな会社はないのだから。そうすると、非常におかしな話になってくる。だから、会社組織がどうなっているのかというのは、まるっきり見えない。その辺が見えないで、議決を得るということは不可能だから、その辺の資料はきちんとそろえて出していただきたい。これはお願いしておきます。これは品川区の教育委員会にあたりは来ているのですか。","respondent":"中山資源循環推進課長","answer":"あくまでも、これは清掃一部事務組合の準備の段階での想定ですので、具体的に各区にあたっているということはないと思います。","voiceIndex":102,"id":"exchange-047"},{"speaker":"林（宏）委員","kind":"意見","question":"片方は公共自治体です。そこで、このような取り引きが行われるとすれば、もちろん「場合」と書いてあるのだから、想定でしょうけれど、きちんと話があってしかるべきだと思います。だって、９月でしょう。社長にだれがなるというのは、１カ月前だからほとんど名前か出てきていいはずだし、２億円の会社をつくろうとすれば、その人の経営能力はどうなのだという話も出てくる。それだけ言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-048"},{"speaker":"山村副委員長","kind":"確認","question":"先ほどの林（宏）委員の質問の確認ですけれども、資料の２ページ目、電気小売経費の収入などの営業利益が４年目からいきなり一けた変わるのは、小中学校に売るという見込みを数に入れているということでいいですか。","respondent":"中山資源循環推進課長","answer":"売却先はともかくといたしまして、卸売から小売を行うことによる収入増を折り込んでいるものです。","voiceIndex":107,"id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5602#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":36631,"voices":113}},{"id":"h18-20060829-16","meetingId":"h18-cm08","date":"2006年8月29日","dateIso":"2006-08-29","committee":"街づくり特別委員会","time":"午後１時０３分～午後 ３時１３分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"今の説明のところで一つだけ質問させていただいてよろしいでしょうか。地域課のほうは交番業務を中心にした活動で、今回集まってくださるところとはちょっと別な話なんだというところがありましたね。区民から見ると、交番というのが犯罪防止の中心のようになっちゃうんですけれども、今回伺って、交番のそれぞれの所轄での数だとか、そういうのってお聞きできるんですかね。その辺ぐらいまでは大丈夫ですか。","respondent":"金子生活安全担当課長","answer":"実は、この辺に関しまして、事前に打ち合わせ等をやっておるんですけれども、正直申し上げまして、交番の数等々については、ある程度のことは承知しておるんですけれども、詳しいことは回答できかねるかと思うんですけれども。","voiceIndex":6,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、あくまでもここで言う管内の犯罪情勢と防犯活動ということのみの報告というか、質疑だけの範囲になっちゃうんですか。","respondent":"金子生活安全担当課長","answer":"大変恐縮ですけれども、地域のいわゆる交番に関することまでについては、本日の課長はあまり詳しいところまで承知しておりませんので、防犯活動と、ここにある関連の業務については正確なところをお話しできるかと思います。","voiceIndex":8,"id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6332#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":1988,"voices":12}},{"id":"h18-20060830-14","meetingId":"h18-cm08","date":"2006年8月30日","dateIso":"2006-08-30","committee":"行財政改革特別委員会","time":"午後１時０６分～午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"公有地等の活用に関すること","agenda":"公有地等の活用に関すること","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"というのは、特に前回では原小学校跡に高齢者施設と、それから幼保一元化の施設というものが隣の保育園等々と連合してというようなことを私どもは言わせていただいたんだけれども、そういった意見なんかはどういうふうにそしゃくしていかれるのかなということと、それから、やはりこれから小中一貫校がいろいろつくられてきますので。","respondent":"日下部企画財政課長","answer":"今回の施設計画については、少子高齢化を中心にしまして施設計画の立案をさせていただいたわけでありますけれども、これからも６校構想に見られますように、６校構想の計画実現にあたっては、それに伴っての跡地の活用の問題というのもこれからずっと継続して出てまいりますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"須藤委員","kind":"質問・要望","question":"区民の皆さんからいろいろご要望等が出たり、町会からもご意見が出されたということをどういうふうにそしゃくしていくのかなというのが１つと、それから、今日、学校跡地の活用事例というのを幾つか見せてもらって、全国的にはもっといろいろな活用の仕方があったと思うんですが、それぞれ活用内容として、港区の氷川小学校は特別養護老人ホームと児童館の複合施設という形になっていますけれども。","respondent":"日下部企画財政課長","answer":"私どもは、まずはこの原小学校の跡地の活用について基本的な骨格を固めていきたい、それから、それを踏まえまして、シルバーセンターの跡についてもどのような形で活用するのか、これは議会のまたご意見等を改めてお伺いしながら。","voiceIndex":7,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"確認","question":"原小学校そのものの耐震強度とか、それから、これが改築と改修では随分と対応が違ってくるわけでありますので、最も大切なことは、これが耐震強度に十分耐えられる施設であるかということの確認はとれているのでしょうかということの答弁と、それから、それがもし、例えばこの施設は厳しいとか、その後で当然改修をしなければいけないわけであって、そういう大きなところでの方向性なり。","respondent":"日下部企画財政課長","answer":"それからもう１つ、改修の考え方ですけれども、これは基本的な考え方のところでも前回申し上げましたけれども、現在の校舎につきましては耐用年数が残っておりますし、あと、コンクリートの強度もしっかりしているということで、あと少なくとも２０年程度は。","voiceIndex":9,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"中身の議論は当然していいと思うんですが、最も大切な建物の強度とか、そういうものがちょっと気になったもので、確認をさせていただきました。それとあわせてハードの整備も当然しなきゃいけないというのは確認できたわけでありますので、確認したいのは、両方のスケジュールをどういうふうに進めていって、いつごろまでにハード、ソフト両面の整備を図っていきたいかということをお答えください。","respondent":"日下部企画財政課長","answer":"これが平成１８年度の秋ごろということで申し上げましたけれども、なぜこの辺を固めなければいけないかというと、今、ご質問にもございましたが、きちんとしたハード整備のための設計ですよね、設計の作業については当然お金がかかりますので、ですから、秋ごろには骨格を固めて。","voiceIndex":11,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"確認","question":"確認だけ最後にしますけれども、設計の予算は来年度上げていきますよと、それはわかりました。じゃあ、ここでまさに議論されているこういう内容が、具体的にそれにあわせて具体化していく時期をもう一度答弁いただければと思うんですが、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"もう１つは実はソフトの面が、実際の運営、地域の自主的な管理も含めまして、ソフト面での運営、これについてはやはり多少時間をかけていかないと、なかなか内容というのはいい形にはなりませんので、この辺については平成２０年度に工事ということになっておりますので。","voiceIndex":13,"id":"exchange-005"},{"speaker":"川西委員","kind":"質問・要望","question":"出ております区案と、それから２番、町会長会議、３番、メール、ファクス等の意見を総合して、大体これで練っていけるんじゃないかと感じます。どうしてもこれだけはというのがあったら聞かせていただきたいんですが、努力してほしいという前向きのご答弁でお願いします。ですから、やはり平成２０年度工事が終わらないとだめなのかどうかだけご答弁いただければと思います。","respondent":"日下部企画財政課長","answer":"地域とのちょっと意見の交換の中でも、工事完了までの扱いはどうなるのかというような、そういうご質問もいただいておりますので、その辺は今申し上げましたように具体的な工事の内容、手順等を踏まえた上で、また調整をしていきたいと、このように考えているところです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"川西委員","kind":"質問・要望","question":"１つだけ漏れているのは、町会長会議、それから区に寄せられた要望５点の中で、ほとんど何とか工夫すれば入れられるということでよろしいですか。","respondent":"日下部企画財政課長","answer":"私どもはできる限り、こういうご意見をいただきましたので、最大限これを反映させていきたいと考えておりますけれども、ただ、例えば３番目の区に提出された主な意見・要望の中で、例えばこれからもう少しちょっといろいろ検討が必要な中身としましては。","voiceIndex":17,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほどの何点かお願いしますが、７月７日の関係町会長への説明ということで、ここの出席者が何人であったかということと、それから、あらかじめ地域の要望を聞かせていただいた上でつくったものだということを答弁されましたけれども、そのあらかじめ地域の要望というのは、この意見募集ではなく、どういった形で行われたものを指しているのかということが２点、それから。","respondent":"日下部企画財政課長","answer":"何点かご質問いただきました。それで、まず７月７日の関係町会長への説明の出席者の人数ということですが、こちらにつきましては、連合町会長と地元の町会長お二人ですから、町会長３名です。","voiceIndex":19,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"７月２０日の町会に回覧というところでは、地域の方に伺ったところ、回覧板を見ていないという方がいましたので、その辺も、回覧板がほんとうに有効な手段かどうかということも今後の検討課題ではないかと思いますので、あるいは、ほんとうに回覧が回っていて、こういう大切なこと、私たちが地域に聞き取りに行っても、回覧で知ったという人は結構いましたけれども。","respondent":"日下部企画財政課長","answer":"ただ、幼保の一体施設ということで、従来の保育園としての機能に幼稚園としての機能、その長所、いいところをうまくミックスしているということで、私どもはいろいろ現場の声なんかを聞いておりますと、かなりそういうことに対する期待感が強いということで伺っておりますので。","voiceIndex":21,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"この図案の骨格のところで、大変校庭の利用というのも要望に出されている中で、校庭の砂ぼこりとか、実際に今、原小学校を使っている保護者の方に伺うと、砂ぼこりみたいなものがあって、そういったことを考えると、１階は高齢者福祉施設ではなくて、子どもの施設が１階であったほうがいいんじゃないかという声がありましたけれども、そのことについてどういうふうにお考えなのかということと、あと。","respondent":"日下部企画財政課長","answer":"要望の取り扱いなんですけれども、区民の皆様方に呼びかけをしまして、要望をいただくわけですから、当然、それに対して区としてどういう考えでいるのか、その辺はそれなりの形でお返しをすることも含めて。","voiceIndex":23,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"この区の３番の要望の(4)のところのこういった品川区の交響楽団というか、そこは２３区で初めて区がつくった交響楽団ということで、すごく歴史のあるものだということを伺っていて、こういう団体の方から区にどこか１カ所こういう練習ができる施設をつくってほしいということは再三要望いただいていましたけれども、こういうものがここではなく、今後そういう文化的な施設として考えていくのかというのも。","respondent":"日下部企画財政課長","answer":"ただ、やはりいろいろな施設を、そのときによってまた場所を変えなければいけないとか、そういうことも含めて、もう少し専用で使えるような施設をということでありますけれども、ただ、これはこのオーケストラに限らず。","voiceIndex":25,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"この氷川小学校のところの運営というのは、同じ事業者がやっているんですか。","respondent":"日下部企画財政課長","answer":"ちょっとその辺は、今、調べてみます。港区の例につきましては、これは高齢者の施設と児童館につきましては、運営主体が別です。失礼いたしました。","voiceIndex":27,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ今からでも住民説明会を開いて、対話と協働ですか、第３次長期基本計画が指し示しているものをぜひ具現化していただきたいと思います。それで、そこでまず伺いたいことは、今回、計画策定にあたって、案の状態で一定の区民参加を、新たな試みがありますけれども、区として今後の改善点や問題点、今後、検討課題かなと思うところ、問題意識、そこをちょっと教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"今後の検討課題ということでありますけれども、そういった意味では、そういう幅広いご説明ということで取り組みをしていますけれども、先ほど井上委員からございましたけれども、回覧がどこまで行き渡っているのかというような、その辺のご指摘はありますけれども。","voiceIndex":29,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり参加を保障した、これまでも審議会の話をしましたけれども、今回もいろいろな意見が挙がりましたので、改めて幅広い区民の参加も含めた検討委員会、これをきちんと立ち上げる必要があるのではないかなと、メールでも郵送でもファクスでも、区とその人の１対１の、質問があって回答という形はありますけれども、やはりみんなを、学校はみんなの施設ですから。","respondent":"日下部企画財政課長","answer":"ただ、地域住民の自主的な管理の問題等につきましては、これからまた地域の皆様方といろいろなご意見をいただきながら調整をしていく必要があると、このように考えておりますので、その辺はこれからどういうふうに詰めていくのか、検討をしてまいりたいと。","voiceIndex":31,"id":"exchange-014"},{"speaker":"中塚委員","kind":"確認","question":"少し個々について伺いたいんですけれども、防災について、ごめんなさい、もう１点だけ、西大井シルバーセンターは、引き続き二次避難場所としての機能は維持するのかどうかの確認だけさせてください。楽器の練習だけじゃなくて、コーラスや合唱の練習もいろいろ可能性は広がってくるんじゃないのかなと思うんですけれども、検討しているものがあれば、お考えを教えてください。","respondent":"日下部企画財政課長","answer":"オーケストラの関係で、３階の音楽室の活用ということでお話がございましたけれども、以前もこれは申し上げましたように、Ｌ字型の本校舎の部分につきましては、これはやはり福祉関係の施設としての利用という位置づけで、これは進めていくということが重要だと考えています。","voiceIndex":33,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう中では、何らかの形で区で東大井区民集会所のような形を参考にしながらやっていく必要が、職員を配置する必要が出てくるのかなと思うんですけれども、そこのお考えをお聞かせいただきたいのと、あと、区に寄せられた意見の中の一番初め、先ほどもちょっと説明がありましたけれども、子どもの日本語教室、ＮＰＯ法人とあるんですけれども、ここは今、どういう活動をしているところなのか。","respondent":"日下部企画財政課長","answer":"ＮＰＯの関係です。子どもの日本語教室、これは先ほどもちょっとご説明させていただきました。","voiceIndex":35,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"意見","question":"１カ月半で５件ということなんですけれども、今後もこの意見を聞いていくのかどうかということと、ホームページ以外でも、やはり広く、地元だけではなく、品川区全体の声として受けとめていく必要があると思うんですけれども、その辺はどうなのか、まずお聞かせいただけますか。","respondent":"日下部企画財政課長","answer":"今回、６月３０日から８月１５日まで１カ月半ということで、私どもとしましては比較的長い期間をとらせていただいたということで考えてあります。","voiceIndex":37,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"その手前でお知らせを、ホームページの２枚でしたか、ホームページでアクセスすると出てくる資料、それ自体をまず説明するというところがまだまだ不十分であると思うんですが、そこが１点と、今回のように大井第３地区の関係の地域住民の方とのコンタクトを何回かされているわけですけれども、周辺の方のご意見を十分聞くというのはごく当然なんですけれども、やはりそれ以前の問題として、公有地の活用。","respondent":"日下部企画財政課長","answer":"広い視野に立ってですけれども、やはりこれは基本的な考え方にも述べてありますけれども、学校の跡地というのは非常に大規模で、なかなか得がたい土地でありますので、それをどうやって有効に活用するか、それはそれなりに広い視点に立って。","voiceIndex":39,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"提案","question":"議会、もちろんここの特別委員会が設置をされたわけですから、この委員会の中でかなり検討して、細かい分野までも出していかなければいけないと思うんですけれども、そこの手前のところで、区民のニーズにどうこたえていくのかというところで、ここでの論議も大事ですけれども、広い視野というか、ここの今日の資料の中でも私はつくづく文化とか芸術、あとスポーツのところで。","respondent":"日下部企画財政課長","answer":"ですから、どういう形をとればいいのか、なかなか難しい選択はあろうかと思いますが、現時点では、私どもはホームページで幅広く区民の皆さん方にご案内をする、対象地域につきましては、やはりできるだけきめ細かく回覧という方式をとる。","voiceIndex":41,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"そうやって受けとめてよろしいんですか。そこが１点と、あと、まず前回も区民の要求というところでは、前回、厚生委員会のところでケアホームの待機者の数を伺ったんですけれども、西五反田のケアホームは定員が８１名ですか、そこのところで待機者の人数が３０名と伺いました。続いてここにケアホームを持ってくると、都内で３カ所目になるわけなんです。","respondent":"日下部企画財政課長","answer":"ケアホームといいますと、どうも利用料金が高いというようなこともいろいろご指摘がありますけれども、ただ、例えば今回の都南病院等につきましても、区民の皆さんが比較的入りやすいような条件設定ということで、例えば今。","voiceIndex":43,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"２０万円を切る、もちろん利用者にとって利用料が低く抑えられる、これはほんとうに最も望むところでありますけれども、私たちが言いたいのは、民間でもできるケアホームをなぜ税金を投入して区がつくらなくちゃいけないのか、そこのところを特にお伺いしたいんですが、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"ちょっと正確な数はあれなんですが、たしか民間の有料老人ホームの区内における施設数が１カ所か２カ所程度ということで、これはやはり品川区というのは都心に近接しているということもありまして、そういう民間の施設を建設する、そうするとやはり事業的な問題も含めて。","voiceIndex":45,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"最後になりますけれども、だからこそ、だれでも入れる特別養護老人ホームを区内に建設をしていくことこそ大事なのではないでしょうか。もう一回。特別養護老人ホームをつくれば、団塊の世代の方々だって、もちろん、この数が足りればの話ですよ。じゃないですか。民間の有料老人ホームが少ないから、民間にかわって有料の老人ホームをつくるんだと、ちょっとそこは違うんじゃないですか。これで終わります。","respondent":"日下部企画財政課長","answer":"少なくとも、区といたしましてはできるだけ幅広い高齢者の皆様方に、それなりの収入の条件とか、いろいろあろうかと思いますけれども、それなりの条件に見合った形で、身近なところで品川区内に住み続けられるような、そういう施設をどういう形で展開していったらいいのか。","voiceIndex":47,"id":"exchange-022"},{"speaker":"中島委員","kind":"質問・要望","question":"今の確認の意味で質問します。今、区では一定期間、先のほうを見て今後の跡の利用ということを考えているというお話を伺いました。私はこれはほんとうに大切なことだなと思います。そういった意味で、この施設を何年ぐらい先までもたせるのか、どのぐらい先までの住民の年齢の動向、そうしたものも把握しての計画なのか、その辺のところをどのようにとらえているのか、先にお聞かせいただきたいと思います。","respondent":"日下部企画財政課長","answer":"ですから、私どもとしましては、ある意味では今後２０年間は施設としての利用が可能なわけでありますし、ただ、この間やはり団塊の世代の方たちをはじめとして、今、高齢化率が２０％ほどでありますけれども、これから急速に進むということが統計上もはっきりしておりますので。","voiceIndex":49,"id":"exchange-023"},{"speaker":"中島委員","kind":"質問","question":"先ほど幼保一元の施設ということでお話が、駅から遠いのになぜというお話がありましたが、この辺のところも、現在の教育のあり方、子どもたちの育ち方、こういったものを見据えた上で、何が必要なのか、こういったところはお考えになってのものだったのかどうか、お伺いしたい。","respondent":"日下部企画財政課長","answer":"幼稚園と保育園のメリットを生かすということでありますけれども、やはり幼稚園における幼児教育というものについて、幼稚園に限定しない、やはり幼保一体施設における特色としまして、幼児教育も受けられる、それから預かり時間も朝から夕方までということで。","voiceIndex":51,"id":"exchange-024"},{"speaker":"中島委員","kind":"質問","question":"こういったことをしっかりとらえていかなくちゃいけないんじゃないかなと考えております。こういった親子がともに成長していく場としては、やはり駅に近いからという機能的なものだけではなくて、もっとソフト面でもしっかりとらえて、そういう施設を考えていくことが大事だと思うんですが、その辺のところはいかがでしょうか。","respondent":"日下部企画財政課長","answer":"幼保一体施設の特色としましては、ちょっと答弁の中で欠けておりましたけれども、親子が交流できる、つまり地域交流のスペースというものを設けるということが、今ののびっこ園台場の施設もそうですが。","voiceIndex":53,"id":"exchange-025"},{"speaker":"中島委員","kind":"質問・要望","question":"そういったものにしっかり機能していけるような施設ということで、それがまた住民にとっての、目先だけではなくて、その奥にあるほんとうの住民の幸せということを考えた施設、跡利用ということをぜひ考えていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-026"},{"speaker":"藤田委員","kind":"質問・要望","question":"これは小学校、当の原小学校の児童から周辺の生徒、こうした視点から、もう学校が始まるわけですから、どういうやり方がいいのかわかりませんけれども、教育委員会との話し合いをして、ぜひ取り入れていただきたいなというのが１点、それから、防災機能の維持・強化ということが前回の利用計画案の中の３番目にありますが、防災の避難所、これは旧体育館等というふうになっておりますが。","respondent":"日下部企画財政課長","answer":"防災機能の関係ですけれども、原小学校も防災拠点として機能をする、それから以前申し上げましたが、今度一貫校を、さらに建物も一貫校ですから２校分の建物ができる、そういう意味では。","voiceIndex":56,"id":"exchange-027"},{"speaker":"藤田委員","kind":"質問・要望","question":"ぜひとも、今、周辺の避難場所との整合性もあると思いますけれども、やはりこれだけまとまった土地の中で、ほんとうの防災機能維持・強化というわけですから、具体的にこれは担当の所管と打ち合わせをしていただきたいなと、このように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-028"},{"speaker":"中塚委員","kind":"提案","question":"３の区に提出された主な意見の(1)、先ほどちょっと伺ったんですけれども、もちろん地域住民の意見や要望を第一としながらも、ＮＰＯ法人の方にこういう施設を貸し出すということは選択肢としてあり得る話だと思うんです。ぜひここの、特に子どもの日本語教室の提案について、前向きに考えることを、もし何か問題点があるのかどうかを教えていただきたいんですけれども。","respondent":"日下部企画財政課長","answer":"ＮＰＯ法人は、いろいろ先ほども港区の例でもございましたけれども、ただ、その辺を専有できるようなスペースの確保ということになりますと、なかなか例えばその辺の立地の条件の問題とか、いろいろ検討すべき課題も多々あろうかと思いますので、この辺については。","voiceIndex":59,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"確かにこの問題は原小学校の跡利用計画だけにとどまらない話かもしれませんけれども、いろいろなＮＰＯ団体、また公共的な役割も果たしている団体は数多くあると思うんです。そういうところも今後踏まえて検討していただければと思います。これは要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-030"},{"speaker":"須藤委員","kind":"提案","question":"それからいま一つ言うと、都南病院の跡地は幼児の施設は直営でやります、それから高齢者施設は民間に運営委託します、先ほど来お話があったように、両方をやっている民間企業も非常に増えてきているので、そういったことをここでやっていきたい、そういう考え方があるならば、都南病院の跡地もそういう形で一緒にできる法人なら法人にお願いしてくるという方向性をつくってくればいいんだろうけれども。","respondent":"新美企画部長","answer":"現在、もう少し具体的に運営をする側の意見も聞きつつ検討を進めておりますが、場合によっては、いろいろな制度がありますので、制度の使いようによっては１階を幼保にして、２階、３階を高齢者というような形もあり得るかもしれないというようなことで現在検討中ですので。","voiceIndex":62,"id":"exchange-031"},{"speaker":"井上委員","kind":"質問・要望","question":"認定こども園のところを伺おうと思ったときに、少し今ご説明があって、新たなところではそういう認定こども園というものにしていく、３類型の中の１つだということだったんですけれども、今、各地域で保育園の民間委託ということが導入された中で、とてもその基準が必要だということが、先日ＮＨＫでもそういう番組があって、基準が守られれば民間委託というところもありなのかもしれないというところでは。","respondent":"日下部企画財政課長","answer":"ですから、この辺は基本的には保育課が中心になりまして、具体的にその辺はどういうふうに取り組んでいくかということで検討すべき課題と、このように受けとめております。","voiceIndex":64,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面で、子どもたちにとって内容がどうなのかという視点を常に持ってやってほしいし、以前、厚生委員会のところでも、現行水準は下がらないんですね、下げないでくださいねという質問をしたら、子ども本位で考えていくみたいなご答弁をいただいたわけなんですけれども、その辺、とても私は法律が通ったから即移行していくような印象でなく。","respondent":"日下部企画財政課長","answer":"今、ご質問の中で慎重にというお話がございましたけれども、とにかく認定こども園は概略がといいますか、それが示されたばかりですので、具体的な基準の問題でありますとか、そのほかかかわる内容につきましては、先ほどもご答弁申し上げましたが、保育課を中心としまして。","voiceIndex":66,"id":"exchange-033"},{"speaker":"川西委員","kind":"質問","question":"資料をいただきましたけれども、港区とか、大田区とか、近場で視察の予定はございませんでしょうか。","respondent":"日下部企画財政課長","answer":"区といたしましては、地元企業でありますＴＯＣの申し出を受けまして、跡地を建て替えに伴う代替えの駐車場用地としまして一定期間貸し付けをし、小学校の移転にかかわる経費についてはご協力をいただくという基本的な考え方に沿って調整を進めているところですけれども。","voiceIndex":68,"id":"exchange-034"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、ＴＯＣ側で年度内に関係機関といろいろ計画案を練ってきます。その間は、あそこは何も区として何か利用するよというような形は考えていないんですか。","respondent":"日下部企画財政課長","answer":"今、第一日野小学校につきましては現状のままでございまして、今年度から２カ年にわたって設計に入るということでございまして、第一日野小学校は現状のままです。","voiceIndex":72,"id":"exchange-035"},{"speaker":"伊藤委員","kind":"確認","question":"ほんとうに確認だけなんですけれども、実施計画がこれから決まっていくということは聞きましたけれども、その大前提となるこちらの品川区が一定貸し出す条件であるとか、それから一定の費用を向こうから出してもらうとか、それは変わりがないということでよろしいんでしょうか。それはぜひお伺いしたいと思いますが。","respondent":"日下部企画財政課長","answer":"その辺は基本的に変わっておりません。ただ、詳細については、具体的なものは事業計画は決まって以降、協議をすると、詳細については協議をするです。","voiceIndex":74,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"第一日野小学校がＴＯＣの７００台の駐車場になる時期や規模はまだ詳細じゃないとは思いますけれども、周辺の方との調整、説明などは、今、どういう状況にあるのかどうか、教えていただけますか。","respondent":"日下部企画財政課長","answer":"その辺の具体的なものが出てきた段階で、これは周辺の皆さんにもご説明し、調整をすると、そういうことになっておりますので、それは今後ということになっております。","voiceIndex":76,"id":"exchange-037"},{"speaker":"井上委員","kind":"質問","question":"先ほど出た前提、契約とかいろいろな事業計画が出た段階で、ＴＯＣとは詳細を今後詰めるということなんですが、その中のどういった項目があるのか、計画が出ないと、費用負担の問題とか、どのぐらいの期間の問題とか、前提は変わりませんねと言ったその前提がよくわからないので、そこのところを教えてください。","respondent":"日下部企画財政課長","answer":"第一日野小学校の建て替えの全体像ですが、平成１８年度、１９年度と２カ年にわたりまして設計作業、今年が基本計画、来年が実施設計、建設工事につきましては平成２０年と２１年、その２カ年にわたりまして建設工事を予定しています。","voiceIndex":78,"id":"exchange-038"},{"speaker":"井上委員","kind":"意見","question":"日野中学校の子どもたちが部活で使っているというその状況は、日野学園のグラウンドに問題があるというか、ちゃんと使えるだけの確保ができないのでこっちを使っているということなのか、本来は日野中学校の子どもたちが日野学園で十分に部活ができるということが前提のはずなので、その辺がどういうことになってそうなっているのかということをお願いします。","respondent":"日下部企画財政課長","answer":"日野中学校の生徒が部活で使っているというのは、あそこの日野学園のグラウンドが使えないからということではなくて、例えばサッカーでありますとか、いろいろそういった点で１つのプラスアルファの部分として、そういう形で昼間、例えば平日の昼間の学校が終わった時間帯とか。","voiceIndex":80,"id":"exchange-039"},{"speaker":"井上委員","kind":"質問・要望","question":"利用の要望がないということは、利用の要望を聞き取ったのかどうかということが１つと、今、小学校の中でも、今まで使っていたスポーツをされている子どもたちが、すまいるスクールが導入されたことで利用が制限されて、学校とその団体との協議の上でということで、そういう場所があれば、多分、練習場所として、そうでなかったら今、学校改修でサッカーだとか、野球だとか、子どもたちが使っていて。","respondent":"日下部企画財政課長","answer":"ただ、あいているときに、それはもちろん有効に活用するということで、これはいわば副次的にグラウンドを使っているという状況ですので、別に本体部分が使えないからとか、さまざまな問題があってということではございませんので、その辺は十分ご理解をいただきたいと思います。","voiceIndex":82,"id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"そこは大丈夫なんです。ですから、そこのところで、中学生じゃなくて、ほかに学校改修でグラウンドが使えなかったところとか、すまいるスクールでの制約を受けているそういった子どもたちの利用要望をとったらいいんじゃないかと思うんですけれども、その辺はどうなんでしょうか。","respondent":"日下部企画財政課長","answer":"いろいろもろもろのそういう地域の皆さん方につきましては、日野中学校跡への第一日野小学校の移転問題をはじめとして、当然、地域の皆様方にもいろいろご説明をし、その中でまたいろいろなご意見等も伺っている経緯がありますので、そういった意味では。","voiceIndex":84,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5806#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":42475,"voices":87}},{"id":"h18-20060925-6","meetingId":"h18-cm09","date":"2006年9月25日","dateIso":"2006-09-25","committee":"区民委員会","time":"午前１０時０４分～午後３時１９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６６号議案 品川区国民健康保険条例の一部を改正する条例","agenda":"第６６号議案 品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"土井委員","kind":"質問","question":"なかなか医療費のことで制度の維持をしていくためのという部分と、値上げされるという部分がなかなか合致しないわけですよね。これは頭の中で考えるのは簡単だけれども、実際には体が伴わない、気持ちが伴わないというのが実態ですから、ぜひ聞かせてください。","respondent":"原国保年金課長","answer":"これにつきましては、高度経済成長に助けられながら給付というものを充実してきたわけですけれど、ある意味、経済が順調なところから安定成長に移行した昭和５８年度以降、その前に老人医療の無料化というのが昭和４８年にございまして、先ほど来の経済状況。","voiceIndex":5,"id":"exchange-001"},{"speaker":"本田委員","kind":"質問・要望","question":"この制度を順調にやっていけば、２５年に１兆円くらいになるほどの費用、これをかなり削減することができるというふうに言ってはおりますけれども、これで万全な国民に安心できる医療体制の確立なのだろうかということになるのかなと、私も使ったりすることが多いものですから、お医者さんと気さくに話もできる、そんな話もするんですけれども、いやいや大変だよなんていうようなことを言われるんですが。","respondent":"原国保年金課長","answer":"国民の中には、日本全国いろいろ話題になっていますけれども、僻地等への小児科あるいは産科、こういったものの医師不足の問題でありますとか、先ほど出ておりますけれど、そういった医療の安全対策、それから、患者側から見ますと、領収書。","voiceIndex":7,"id":"exchange-002"},{"speaker":"本田委員","kind":"質問","question":"話が空中戦になってしまうので申しわけないんですけれども、この諏訪中央病院の院長先生の話によれば、確かに現在、厚労省は３２兆６,０００億円ですか、昨年度の医療費を発表していますね。この３２兆円の医療費に、あと２兆円乗せてやれば、がん対策とか、今のいろいろな小児科とか、産科とかの医療体制にかなりの手当てができる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"道筋をちょっと教えていただきたいんですけれども、今、現実的に療養病床に入院しておられる高齢者の方は何人ぐらいいらっしゃるのかという質問と、それから、３割負担になるわけですけれども、３割負担になる高齢者の方々、いわゆる現役並みということで指定されて３割になる方、何人ぐらいいらっしゃるのか。","respondent":"原国保年金課長","answer":"療養病床に入られた方の人数ですけれど、こちらについても、ある時点でとらえた数字で申し上げますと、国保加入者で療養病床に入院している方、この方につきましては１１名ということで把握しているものです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"２割から３割になる方が１２％で、従来１割だったのに税制改正の中で３割の負担をしなければならなくなった方々が７％、７３３人という、こういう数字で、１割負担の方は８割いらっしゃるということで、非常に私は影響が大きいのではないかなというふうに思っているんですけれども、今までご質問された方々もかなり、どちらかというと、手放しでは賛成できないんだという。","respondent":"原国保年金課長","answer":"先ほど来のところで、こういった医療制度、こういったものを国民皆保険ということで少子高齢化、こういったものを継続的で安定的に維持していくという、こういうような基本的な考え方の中で、一方で医療費が伸びていく。","voiceIndex":12,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"その中身として、長期療養が必要な患者向けの療養病床ということで、福岡県内の３０７の病院を調査したら、事情が許せば退院したいんだという、そういう方たちが６５.６％いらっしゃるけれども、そのうちの事情が許さないんだと、いろいろなご家族が病気だとか、仕事をしているとか、高齢な方だとかという、そういうことで事情が許さなくて入院をしている方が４４.６％いるということで。","respondent":"原国保年金課長","answer":"８ページのところに先ほどの５万２,０００円というものを現役並みの所得の方については基本的にはご負担をいただくんですけれど、２番のところで、１つは所得を斟酌するということで、低所得者あるいは年金受給額８０万円以下。","voiceIndex":14,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"今のお話なんですけれども、４０名というお話ですけれども、これは対象者すべての方の数字ではないというふうに思いながら伺っていたんですけれども、そこの辺をちょっと確認したいと思うんです。だからこそ、１０月にもこれから本人への通知とチラシを出すということのご説明だと思うので、どのくらいいらっしゃるのかということもつかめていないということなのかな。","respondent":"原国保年金課長","answer":"委員ご指摘のよりわかりやすさというところは、私どもも努めているつもりではありますけれど、今後、そういった意見を参考に検討していきたいと、こういうふうに思ってあります。","voiceIndex":16,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ大事な数字、とりわけ今回は７０歳から７４歳の方々、高齢者の方々が大きな影響を受けるという、そういう問題ですので、ぜひその辺は数字的にちょっとお知らせいただきたいというふうに思います。今の時間が無理であれば後ほどでも結構ですので、できるだけこの審査のところに間に合うようにしていただければありがたいとは思っておりますけれども、どうぞよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"堺委員","kind":"質問","question":"質問ではなくて、原案に対する見解について。ですから、広い話で見たときに日本の人口がより少子高齢化という時代になり、医療費がますます増大をしてくるという中にあっては、それぞれの応分の負担ということも、これは考えなければならない財源確保の１つではないかなという気がするんです。収入額にしては、高齢者複数所帯では５２０万円、単身者では３８３万円。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"ちょっとずれるかもしれないんですけれども、改正の内容の（６）番の日英租税条約の見直しに伴う規定整備に特例措置がとられているというところで、中の６ページ、７ページに書いてあるんですけれども、このような条例を、日英と書いてありますけれども、同種の条約を結んでいるのは幾つぐらいあるものなのでしょうか。","respondent":"太田税務課長","answer":"申しわけないですけれども、個々の部分で幾つあるかは私はちょっとつかんでございません。今回のご指摘の日英租税条約のものについては、昨年来、従来というか検討されてきて、今年、国会に条約が、日英で成立して国会に批准をしたと。","voiceIndex":21,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"昨年、条約が批准をされたということ、それはなぜ日英租税がいわゆる準拠されながら国民健康保険が一部改正されなければならないのかという点は疑問に思ったのが一つと、日英なんですが、むしろ日米のほうがそういう意味では、税金、所得の、お互い個人の所得資産を考えた場合に、多いとは思うんですけれども、それは税法上はそういう違いはあるんですか。","respondent":"太田税務課長","answer":"申しわけございませんが、今、手元に資料がございませんので、ちょっと正確なお答えはできません。","voiceIndex":23,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"ちょっと言葉じりをとらえることで、確認したいが、そういうことというのはどういうことですか。今、課長がそういうことでとおっしゃっているんですけれども、そういうことがちょっと今、理解できなかったので、そういうことを改めまして教えていただきたい。","respondent":"太田税務課長","answer":"それをきっかけとして、地方税法について条文として一般化をしたということでございまして、当然、日米でそういう租税条約があれば、日米租税条約に基づくものも適用になるという趣旨で、そういうことというふうに申し上げたんです。","voiceIndex":25,"id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、これからも先、どこかの国と条約が結ばれているわけですけれども、条約の変更があった場合に、やはりこのような同じ作業は行われる要素として一部入れられてくるということでいいのでしょうか。","respondent":"太田税務課長","answer":"そういうことを将来、個々の条約が改正をされたとしても、今回こういう形で規定を既にされてありますので、規定の整理は要らないということでの一般化ということで申し上げたんです。","voiceIndex":27,"id":"exchange-013"},{"speaker":"大沢委員","kind":"意見","question":"団塊の世代がこれからますます増えていって、７０代以上の方がどんどん。それによってこの条例の改正が行われたわけだと思いますし、先ほどの資料にありましたように、８ページの１と２でそれなりに負担増というものを、負担額を軽減するという斟酌をしているということで、そこのところでそれはよかったのかなという気がしますので、この条例に対しては賛成をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、今度の療養病床のところの食費、居住費が増えていくということで、品川区では１１名だということなんですが、この少ないからいいということではなくて、やっぱり払い切れない、入り切れないということで出ていかざるを得ない方が発生してしまった場合には、その方々の家族を含む生活を、あるいはご本人の健康をどうやってみていったらいいのかという、そういう問題になるわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-015"},{"speaker":"土井委員","kind":"質問・要望","question":"先ほど申し上げましたように、これは国会で国保の法律的な変更がなされて、全国的に全く同じように、同様に条例等を変えなければならない、こういう中身のものですから、これで反対してやらなかったら成り立つのか成り立たないのかという話にもなりますので、その部分については賛成することになるんだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-016"},{"speaker":"本田委員","kind":"意見","question":"過剰検査などが医療機関の中でないのかどうか。適切に行われているのかどうか。そして、何よりも、これも先ほど強調しましたけれども、医療の安全性という点では、どうも落ちているのではないかということなどを申し上げました。より安心安全な医療体制を願いながら、この改正に伴って、これがそういう方向に進んでいくことを願って見守っていきたいということで、条例改正には賛成をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-017"}]},{"id":"topic-02","title":"移らせていただきます。 第６３号議案 平成１８年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"移らせていただきます。 第６３号議案 平成１８年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ちょっと交番のほうなんですけれども、荏原町のところが廃止と、そしてあとの４箇所は用途変更というふうにさっき説明されましたけれども、具体的にどういうふうなことなのか、ちょっともう一度教えていただきたいのと、それから、地域の声、とりわけ廃止をするところの荏原町のところは、地域でどういうふうな声が出ているのか、もしつかんでおられたら紹介をいただきたいと思います。","respondent":"金子生活安全担当課長","answer":"私ども区民生活事業部でも町会等に説明をして一定の理解を得るとともに、これは過去にさかのぼるのですけれども、荏原警察署長に対しまして交番の存続等については要請を出しているところです。そういった経過を経て、今回の廃止予定についての説明を受けてあります。","voiceIndex":40,"id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"それで、警察がやらなければいけない交番を廃止して、その分を品川区が肩がわりしてしまうという、そこのところがどうしてもちょっと理解に苦しむんですけれども、もっともっと区として安心安全の担当者も配置をして、きちんと区の予算でそういう思いにこたえる行政をしているときに、もっともっと警察に対して、そういう要請をしていただきたかったという、廃止で新しい施設をつくる前に。","respondent":"早津区民生活事業部次長","answer":"それを受けまして、委員のご質問の中にありましたが、生活安全について重点を置いている品川区として、ではどういう対応をすべきだろうかというものを検討した結果、交番は廃止になるけれども、代替施設として、この荏原町安心安全、仮称ですけれども、こういうものをつくり。","voiceIndex":44,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"そういう警察とのやりとりの中で品川区が積極的に予算をつけてまでも対応する、その努力は私は認めたいというふうに思ってはいるんですけれども、しかし、根本的なところが全然違うものになってしまうというところは非常に残念だと思うので、今回、廃止になってはしまいますけれども、やっぱり交番としての少なくとも機能をきちんとそこのところに盛り込んでいただきたいということと、あと、ＯＢ２名。","respondent":"金子生活安全担当課長","answer":"警察ＯＢ２名の配置につきましては、現在、警視庁のほうで区管理の旧交番、これについては検討をしているというふうに聞いております。ただ、区の施設等につきましては、なかなか難しい部分もあるというふうに現在のところは聞いております。","voiceIndex":46,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"品川区は今回、そういう状況を受けて予算をつけて新しい施設を設置し、そしてパトロール、ボランティア、こういう対策をとるというふうなことなんですが、同様、若干温度差はあるにしても、よその自治体でこういう品川区と同じような体制をとっている自治体はあるんですか。","respondent":"金子生活安全担当課長","answer":"こういった区が予算を設けて施設を設置するところは、今のところないようです。ただ、さまざまな今、検討をして、新しいまちづくりも、いい方策がないものかどうか検討しているように聞いています。","voiceIndex":48,"id":"exchange-021"},{"speaker":"土井委員","kind":"質問・要望","question":"そういう中で、交番としての今の施設の質問をします。それが１点。多摩へ行くのですか。それとも源氏前交番のほうに移られて、パトロール強化のほうに回っていただけるんですかという、いわゆる機能ですね、機能をどういうふうになっているのかということを説明しないと皆さん安心しないということだろうなというように思いますので、その辺をちょっと聞かせていただきたいと思います。","respondent":"金子生活安全担当課長","answer":"このうち８８箇所が先ほど言った警視庁管理になるものと、自治体管理になるものとして、それぞれ安全機能を有する拠点というふうに考えるということで、今、検討していると聞いております。","voiceIndex":50,"id":"exchange-022"},{"speaker":"土井委員","kind":"質問","question":"今でもそうなんですが、ほかの交番もお話のあったように私有地の場合、国の場合、都の場合、土地ですからいろいろ借りたりなんかしている契約の関係があるのだろうとは思いますけれども、今までの過去になくなった交番で、建物というか、部屋というか、何ともえたいの知れないものがあるところもあるものですから、どういう管理をしているのかなと思ったんです。","respondent":"金子生活安全担当課長","answer":"そのとおりです。他の４箇所については、現在、検討中であるということで、そういった方向づけでやっていくです。","voiceIndex":52,"id":"exchange-023"},{"speaker":"堺委員","kind":"質問","question":"その辺のことと、今回、新設の目的のところに、今説明ありましたような、要するに、パトロールそのものが強化されるということは、ただ単にそこに交番という建物だけがあることも１つの犯罪防止にはつながるとは思いますけれども、さらにはパトロールの強化、２つあったほうがより犯罪の抑止につながるのだろうとは思いますけれども、いろいろな事情があるのであれば、よりパトロールが。","respondent":"金子生活安全担当課長、山田区民生活事業部長","answer":"経済的負担に関しましては、根本的な考え方としまして、警視庁のほうで必要がないので壊すのであって、それに区のほうとして新たな施設を設けてもらうのは非常にありがたいとは言っておるんですけれども。区の取り組みます安心安全の施策というのはさまざまあります。例えば、私ども独自に開発をし、子どもたちと一緒に渡した「まもるっち」、あちらについても大変な金額をかけているわけですね。","voiceIndex":54,"id":"exchange-024"},{"speaker":"堺委員","kind":"質問","question":"関連して。解体して新たにつくる。これは新たにつくる整備の解体は、これは東京都のほうで全部やるんですか。そうなると、区内の５箇所の廃止交番ですから、おそらく本来荏原町と外４箇所についても、場合によっては建物、交番という施設、それを解体するとなると、解体料はどうするのか。修理については区がするのか、解体はどうなるのかなと。","respondent":"金子生活安全担当課長","answer":"したがいまして、将来的には東急の駅舎等で取り壊されることになるわけなんですけれども、その取り壊し費用につきましては、警視庁でもつということになります。他の４つの交番についてのかかわる費用につきましては、まだ検討中で、はっきりしたことはまだわかりません。","voiceIndex":57,"id":"exchange-025"},{"speaker":"堺委員","kind":"質問","question":"じゃあ、東京都の交番だから、廃止に当たって解体する場合には、それは東京都がお金を出して解体しますよ、自分もそれは当然だろうと思うんです。質素倹約を旨として効率的に財政運営していく、そういう考え方から行けば、なるべくなら国や東京都からお金をもらって区がプラスになるようにしたほうが、可能ならですよ、そんなふうに思って伺いました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-026"},{"speaker":"本田委員","kind":"質問","question":"このまま第６３号議案をやっていくんですか、休憩なしで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-027"},{"speaker":"本田委員","kind":"質問","question":"荏原町のほうは、私はこれでいいんですが、清掃一部事務組合のほうをちょっと聞こうと思っているんだけれども。そうすると、また皆さんいろいろ出るでしょうから、どうするのかなということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-028"},{"speaker":"本田委員","kind":"質問・要望","question":"概要については特別委員会でご報告を受けまして承知しておるわけですが、それに出資というか、お金がついた段階ですので、改めて１点だけお尋ねしておきたいと思います。今、１,５００人くらいの職員でしょう。新会社に対する区なり、一部事務組合のチェックといいますか、全くの独立した民間会社、どういう格好でなるのか、考えられているのか、その点もちょっとお尋ねしたいと思います。","respondent":"中山資源循環推進課長","answer":"予想として、やはり今後、順次、工場の中で可能な部分を委託していくことによって、職員の退職等にも対応しながら効率的な運営を図っていくことを考えております。","voiceIndex":65,"id":"exchange-029"},{"speaker":"本田委員","kind":"意見","question":"よくわかりました。例えば、品川清掃工場、品川区内にあるわけですが、そこでのいろいろなことについて、品川区議会で特別委員会も持っているわけですが、議論をするというような中に、この新しく設立される会社の管理運営にかかわる部分について、仮に意見等が出た場合、それはどのように反映されるのか。具体的なことですけれども、お尋ねしておきます。","respondent":"中山資源循環推進課長","answer":"先ほどの答弁と重複するかもしれませんけれども、こういう報告を受けながら、また議会でのご議論があった場合は、基本的には私のほうから、つまり、一部事務組合の本庁の運営部隊がありますので、そこにご意見をこの新会社に対して区から。","voiceIndex":67,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"幾つか聞きたいんですけれども、現在、品川の清掃工場に限らず、一部事務組合で委託をしている、アウトソーシングを既に始めているところがもしあれば、どこなのか伺いたいのと、２３区全体では２１カ所清掃工場があるというふうに聞いているんですけれども、その２１カ所がどういう計画でアウトソーシングになっていくのか、そのあたりも聞きたいのと、それから。","respondent":"中山資源循環推進課長","answer":"一部事務組合の運営そのものにかかわることは特別委員会の審査であろうかと思いますけれども、新会社と関連するということで、その範囲でお答えしますけれども、現在、委託されている工場は２工場あります。","voiceIndex":69,"id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"電気の卸売事業とかという、その辺がちょっと説明がなかったのであれなんですけれども、要するに、今度はアウトソーシングして電気を売って、そしてコストをできるだけ少なくしていくという、そういうことも株式会社、合弁会社をつくる目的のところには出ているというふうに思っているんですけれども、いろいろ資料を読んでみると、これから設立されて３年、５年間ぐらいで黒字に。","respondent":"中山資源循環推進課長","answer":"各年度の部分については、なかなか詳しくはこれ以上の数字のことは認識できる部分ではございませんけれども、いずれにしても、そういう間に電気事業者を介する部分のものをなくしていくということが１つと、それともう１つは、先ほどのご質問にもかかわるんですが。","voiceIndex":71,"id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"その辺について、改めてこの間、品川区は精力的に説明会をされていますけれども、そういう説明会の場で、その辺の了解、理解というのは、どういうふうになっているのか、ちょっとそこも含めてお考えを伺いたいと思います。","respondent":"中山資源循環推進課長","answer":"今回の新会社を設立して電気を安定的に、あるいは小売りによる一定の利益を確保するという話と、いわゆる今、別の場面で申し上げている廃プラスチックのというのは、もともとの意思決定の過程からしても、ちょっと次元が異なっている部分がございまして。","voiceIndex":73,"id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"一部に廃プラの問題と売電の、この新会社立ち上げの問題は違うんだという意見、この場面だけではなくて、以前にもちょっと聞いたことがありました。でも、私は違うと思うんです。リンクしているから、どうしてもそこまで触れざるを得ないと思うんです。だって、売電をするということは、燃やすものを、プラスチックを回収することに変更したわけですから、そこは違うんですか。質問したいと思います。","respondent":"中山資源循環推進課長","answer":"ただ、結果的に新会社がこういうものを扱う中で、その売却の収支の見通しの中にこういうものが入るかどうかというのは、１つの方法論の結果としてある部分であって、そのために、例えば分別の変更が新会社設立要件と考えられるというようなことは考え方としても。","voiceIndex":75,"id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"そういうことも背景にあるからこそ、そういうふうに住民が不安を感じているということですから、どうしてもこの廃プラの回収、焼却に触れないわけにはいかないというふうに私は思うので、ぜひこのところでの５２０万円の予算をつけるつけないのところにとどまらずに、その背景にあるもの、問題点になってくるもの、そこを同時に審査しないと、賛成も反対もできないですよ。よろしくお願いします。","respondent":"川西委員長","answer":"ご意見ですね。答えはいいですね。３回いただいておりますので。","voiceIndex":77,"id":"exchange-035"},{"speaker":"土井委員","kind":"質問・要望","question":"区民委員会で審査すべき事項と、特別委員会で審査すべき事項を、これはやっぱりしっかり分けるということが必要なので、その立場できちんと仕切りをつけていただくことが１つと、今、問われていることではない話が出てくると、これはもう切りがないようになってしまいますし、仕切りの問題と両方ありますので、よろしくそこのところの進行を図っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"先ほど２３区の状況について伺いましたけれども、第３回定例会で予算化していない、補正を出していないところが９区だという説明でしたけれども、これも新聞報道によるんですけれども、反対の立場で表明している区があり、一部事務組合にその旨を議長名、たしか議長名だったと思いますけれども、それで要請を、港区議会の事務局が２２日に一組に文書を届けに行ったと。","respondent":"中山資源循環推進課長","answer":"この間、清掃一部事務組合としては、評議員会等を経て一定の議論があったところにつきまして、一組の議会の中でやるべきものと、少なくともいろいろ確認のご意見があったということは伺っておりますけれども、そういうようなことは詳しく存じあげてございません。","voiceIndex":81,"id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"そうしたら、２３区の全体的な状況を伺いたいんですけれども、港区のこの関係は承知していないというお話でしたけれども、たしか中央区の区長が、あるいは区長がそれぞれに一組に質問をしているというふうに聞いておりますけれども、その関係と、それから、今回の２３区で、例えば新宿区、あるいは江東区、どういうところにあるかということで、もしわかれば教えてください。","respondent":"中山資源循環推進課長","answer":"各区の、あるいは区長のご意見について、申しわけありませんけれども、お答えできることはございません。","voiceIndex":83,"id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、ぜひ品川区としてもいろいろな関係機関にそういうところの話をやっぱりしていただきたいというふうに思っているんですけれども、その辺、こういう日程については、一般的なやり方として過去にもあったのか、あるいはどうなんでしょうか。短期間の間に非常にあるということで私は思っているんですけれども、その辺はいかがですか。","respondent":"中山資源循環推進課長","answer":"そのタイミングの中で行っていくという中ですけれども、若干事務的なずれが生じたですので、その間、いろいろとご質問があったり、確認の議論があったということはわかっておりますけれども。","voiceIndex":85,"id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"だけど、答弁いただいていないのは、短期間の間に決めていくこういうことについて、品川区としてはどういうふうに、今回のこういう日程のとり方については、どういうふうな見解を持っているのか、やむを得ないと思っているのか、ちょっと早いんじゃないかと思いつつも仕方がないからやっている、どうなんでしょうか、その辺は。","respondent":"岩崎環境清掃事業部長","answer":"ばたばたと何か決めてきたというようなご印象をお持ちのようですけれども、実はこの春ごろからもう区長会ではいろいろと議論しておりまして、課長が先ほどから申し上げているように。","voiceIndex":87,"id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"税金を投入するわけですから、やっぱり区民のところに非常にかかわる問題ですから、上のところで決めていけばいいという、そういう問題ではないというふうに思いますので、できるだけいろいろな情報も含めて、区民に出していくという、そういう姿勢はこの問題に限らず、そういう姿勢を持っていただきたいということをこの際発言しておきたいと思います。それが１つです。その点についてはいかがでしょうか。","respondent":"岩崎環境清掃事業部長","answer":"新会社の経営基盤の話ですが、新会社のやることというのは、工場の運営の一部を受託するという、これもまたリスクの少ない事業と、それから電気を売るという、これも今もう既に売っているわけですから、それを自分たちが売るということで。","voiceIndex":89,"id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、言葉じりをとらえて大変申しわけないですけれども、こういうような気がしますみたいな、そういうあいまいな説明ではなくて、やっぱりこういうふうになっているから大丈夫ですというふうに、やっぱりそういうことで示していただきたいということをちょっと改めてお願いをしたいと思います。とりあえず。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-042"},{"speaker":"堺委員","kind":"質問・要望","question":"手短に何点か質問をさせていただきたいんですけれども、まず資本金の５２０万円に関連してです。この辺をまず１つ。","respondent":"中山資源循環推進課長","answer":"表からは見えないんですけれども、大体１工場当たり、直営の現状のものを基本にすると、新会社によるアウトソーシングを行うことで、約６,０００万円弱の経費削減が見込まれる。","voiceIndex":92,"id":"exchange-043"},{"speaker":"堺委員","kind":"質問","question":"出資金の５２０万円は書いてある。東京都は、あるとすれば、その分担金が幾らですよと、それが毎年これからだんだん電気の販売によって減ってきますよということなのかどうかという、８００億円の中で４００億円ですか、それはもう既に分担金として出ているものですよね。ではなくて、この会社が設立されるに当たってはどうなるのでしょうかという、その辺お願いします。","respondent":"中山資源循環推進課長","answer":"この細かいことまでは申しわけありませんが示せていませんけれども、今、出資を上回る削減効果につながるです。","voiceIndex":94,"id":"exchange-044"},{"speaker":"堺委員","kind":"質問","question":"そうすると、今、品川区が年間１５億３,０００万円分担金がある、それは来年の４月以降、すぐその分担金が毎年出ていくんですか。そのための費用が５２０万円。あわせて今年度１５億３,０００万円という１年間の分担金も支出されていくんですか。私は今、平成１８年度の予算の中の中身はちょっと覚えていないものですから申しわけないんですけれども、そこをもう１回。","respondent":"中山資源循環推進課長","answer":"ここにあるように、当初は企業経営そのものは、先ほどご説明したように、３年間ぐらいは企業経営としてはむしろマイナスになってくるので、この分は資本金をある種、拠出していくわけですが、受託工場が増える中で黒字になっていくという中で、先ほど５年後と申し上げたのは。","voiceIndex":96,"id":"exchange-045"},{"speaker":"堺委員","kind":"意見","question":"ごめんなさい。そうすると、それをまた２３区で４億を、品川区的には、５年後でも１５億３,０００万円の年間の分担金がありますよね。３,０００万円ぐらい。今、計算すればいいんですけれどもね。","respondent":"中山資源循環推進課長","answer":"この４億円は確かに見込みですけれども、仮に２３で割れば２,０００万円弱になりますから、その分が効果として来るということで、またそれが予算編成の中で判断する部分になりますけれども、いわゆる運営経費が下がってくることによる見返りがあるということです。","voiceIndex":100,"id":"exchange-046"},{"speaker":"堺委員","kind":"意見","question":"だから、工場数の規模によるのかどうか私はわかりませんが、ただ数字だけ見ると、工場数が１つあるいは２つ増えたことによっての電気の購入費というのは、そんなに差はないのではないかなと思うんだけれども、今見るとかなりの数字の減ったり増えたり、また増える金額も、どんと増えたり、そんなでもなかったり、ちょっとその数字が、こういう数字なのかどうかちょっと背景になるものがわかりませんので。","respondent":"岩崎環境清掃事業部長","answer":"それまでは卸しですから、今もう既に売っている電気料に安全率を掛けて、このぐらいは見込めるだろうというようなことを計上したものだと、こういうことです。","voiceIndex":102,"id":"exchange-047"},{"speaker":"堺委員","kind":"意見","question":"それからもう１つは、今ご説明いただいたのでわかるんですが、要するに、受託工場数がわざわざ一番上に書いてあって、下で電気販売と書いてあるから、どうしても我々なんかが見るとそれに関連づけて読んでしまいますから、だれが見てもパッとわかるというような表にするなら、収入については電気販売、これは工場数が幾つあって、それでどうなるんですよとか、支出の工場について、だから。","respondent":"中山資源循環推進課長","answer":"ただ、いずれにしても、ここで言っているのは、そういう卸しから小売りを行うことによるプラスがあるよということを一部事務組合のほうではじいたということでございまして、逆に言えば、この辺を細かく分析するとなると、その時々の、例えば電気料金の相場を実際には考えないと。","voiceIndex":104,"id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"いえいえ。ですから、どうしてもそこのところに触れないわけにはいかないし、リンクされている問題ですから、どうしてもそういうところで考えていかなければいけないとも思っております。ですから、そういう点で、やっぱり検討する時間も非常に早過ぎるということと、いろいろな波及される問題が多過ぎるという点で、どうしても賛成するわけにはいかないということで、反対の態度を意見表明します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-049"}]},{"id":"topic-03","title":"請願第１５号および請願第１９号 固定資産税における償却資産に関する意見書提出の請願","agenda":"請願第１５号および請願第１９号 固定資産税における償却資産に関する意見書提出の請願","exchanges":[{"speaker":"本田委員","kind":"質問","question":"内容ではないんですけれども、２３区の他区の動きというのはあるんですか。","respondent":"太田税務課長","answer":"今年については、現時点では数区出て、これから例年ですと第４回定例会にかけて出てくるような状況ではないかと。都議会のほうに意見書が出て、都議会のほうで第３回定例会から第４回定例会、来年の第１回定例会にかけて結論を出す、こういう流れが大体例年のようです。","voiceIndex":149,"id":"exchange-050"}]},{"id":"topic-04","title":"なります。 請願第２０号 出資法の上限金利引き下げに関する請願","agenda":"なります。 請願第２０号 出資法の上限金利引き下げに関する請願","exchanges":[{"speaker":"南委員","kind":"質問","question":"それで、改めて伺いたいんですけれども、引き下げて１５％ぐらいのところまで引き下げていきたいという話だと思うんですけれども、さっきちょっとどなたか、借りる金額によってパーセンテージがちょっと違うみたいな、金額、例えば１０万円を借りるとか、そういう部分の低い金額の融資を受ける場合は、利息がどんと高くて、大口みたいな、１００万円とか、数百万円とかというと、利息を若干低くするみたいな。","respondent":"鷹倉区民課長","answer":"私も２２日金曜日の新聞によりますと、当初の１０万円を５０万円、１００万円を５００万円にする案にすると無理が生ずる、それで、その新聞報道によりますと、その５００万円というのを、５００万円ないし３００万円にする一方、５０万円はそのままにするという。","voiceIndex":159,"id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱりこのところのグレーゾーンをやっぱり全部なくしていくということが大事だというふうに思いますので、注目をしていきたいとも思っています。それと、意見書を出すということがここで決まっていった先には、その意見書の中身には、区民の皆さんの生活実態などもちょっと盛り込んでいただきたいなと思います。明日のところでそれは案文をいただいて議論するのでしたか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-052"},{"speaker":"大沢委員","kind":"質問","question":"意見書と明日の臨時国会、２６日の臨時国会でこの法案は提出されるということですけれども、意見書が可決であった場合、結果によっての意見書の扱いはどうなるんですか。可決されてしまって法制化されましたと、後付けで意見書を出すとなった場合、どういう対応が望ましいか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-053"},{"speaker":"大沢委員","kind":"意見","question":"何とかするレベルではなくて、扱いをどういうふうに、意見書提出をどうすればいいのか。法制化、可決されて、後から区のほうで意見書を出す、そこのところがちょっと疑問なのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":167,"id":"exchange-054"},{"speaker":"本田委員","kind":"質問","question":"ただ、動きの中に、やっぱりこういう業者の意向を酌むというか、意見を受けているんじゃないかというものがあったりして、国会の動きはいろいろあるようですけれども、この請願の趣旨は、金額とか、パーセントとか入れているわけではないし、みなし規定をなくせとか、そういうことを言っているわけですから、私はこれは当議会では採択をして、やはり国に対して消費者の立場を守るという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-055"},{"speaker":"土井委員","kind":"質問","question":"今もおっしゃったような形でいいと思います。先ほどちょっとその意見書に関連をして、もし通ったらというお話でしたが、この請願の趣旨のところの５行ぐらいですか、禁止することまで極めて単純明解に書いてあるので、もうこれでいいんじゃないですか。こういう多重債務による死亡、いろいろ国民生活に資するために書いてある、十分だと私は思うんですけれども、あまりぐだぐだ書くと中身がぼけてしまう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-056"},{"speaker":"堺委員","kind":"質問・要望","question":"年間申し立てが１８万件を超える自己破産者、夜逃げ、経済苦による自殺、一家心中等々の悲劇をもたらしているという事態、なぜそうなったかということも、本文の下から５行目のところにあるように、まさにこのとおりだろうと思うんです。まさにそのとおりだろうと思うんです。ですから、その辺で重ねて請願の趣旨を生かす形で意見書を提出していただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-057"},{"speaker":"南委員","kind":"確認","question":"委員長、ちょっとこの意見書の意見なんですけれども、いいですか。確認。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-058"},{"speaker":"南委員","kind":"提案","question":"明日、今回、本会議を兼ねていますよね。明日提案していただいて、これをちょっと見てくださって、議運にかけてというふうになるんですね。その辺を確認させてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":178,"id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2468#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":68225,"voices":183}},{"id":"h18-20060925-7","meetingId":"h18-cm09","date":"2006年9月25日","dateIso":"2006-09-25","committee":"厚生委員会","time":"午前１０時０４分～午後２時３３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"１点だけ。今一番最後にご説明いただいた７０歳以上の方は少数とおっしゃった、現実にはまだいらっしゃるんですか。療養病床に入っているんじゃなくて、実際に親が７０歳以上、少数という言葉にちょっと引っかかったんで。","respondent":"諸岡児童課長","answer":"現在７０歳以上の方は７人おります。なお、先ほど申し上げましたように療養病床に入院している方はおりません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"７０歳以上の方が７人いらっしゃるということで、これからこれが適用されるという可能性はあるということなので、これは本当に先日の老人医療のところでも申し上げましたけれども、２万４,０００円が５万２,０００円になってしまうわけですから、２倍以上になってしまうので本当に大変な負担になるわけなんですけれども、これはこれを適用させない。","respondent":"諸岡児童課長","answer":"生活療養負担額を補助の対象としないという扱いをしないことができないのかですが、これまでひとり親家庭等の医療費助成制度の改正につきまして、公費助成と利用者負担の均衡を図るということの中から、食事療養費の負担額、これは保険でも一部負担をされておりますが。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それで、今度２００８年から７０歳から７５歳までの医療費が、窓口負担が１割から２割になりますけれども、そのことに関してはここには関係してこないというふうに考えていいのか、そのことについてちょっとお聞かせください。","respondent":"諸岡児童課長","answer":"老人保健法の改正云々ですが、あくまでもこの制度は老人保健法の算定式を準用して１割負担しているものですので、老人保健法の制度そのものの変化というようなことの影響はございませんで、あくまでも算定式がこのひとり親家庭等医療費助成制度につきましては。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、なおかつその上で７０歳以上になってまた１８歳以下の子どもさんを育てているということになると、本当に大変な状況というのは想定されますので、ぜひそういうふうな方向で検討していただきたいという意見を述べて、とりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"教えていただきたいんですが、まず基本的なことなんですが、食材料費の算定の方法はどういう形の中身になっているのかなと。それが、目安の中で増えているというところでの算定について、もう少し詳しく教えてください。","respondent":"諸岡児童課長","answer":"療養病床に入院する場合の食費ですが、これが４６０円で、３食で１,３８０円程度、あくまで目安です。光熱水費が３２０円の３０日でほぼ１万円というような、あくまでこれは目安として設定をされているもので、内容としてはそのような内訳です。","voiceIndex":12,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"１食分、光熱水費もかかるんでしょうけれども、そこの算定が所得によっていろいろ違うとはいいつつも、先ほどの４６０円というのは、これは入院しているときのですか、ちょっと４６０円、１日１,３８０円という形をおっしゃったんですけど、それが一般的に高いのかな、安いのかなというところですね。","respondent":"諸岡児童課長","answer":"このもともとの健康保険法の改正によりまして、この食事療養費、それから入院食事代となってございましたので、もとの健康保険法の変更に伴って、このような形になって、それをひとり親の医療費助成制度において反映したです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"もう少しこれを安く算定できるんだったら、もうちょっと負担額が減るんじゃないかなという部分、そういう考え方もあるかと思いますし、その額については、それだけ品川区が言える権限があるのかどうかわかりませんけれども、そこら辺はあとは品川区で負担というのはなかなか難しいにしても、妥当性がどうなのか、もう少し全体を物価の上昇とか。","respondent":"諸岡児童課長","answer":"このひとり親の医療費助成制度につきましては、先ほど申し上げましたように、健康保険法、それから国民健康保険法、老人保健法の均衡を図る意味で、それらを準用して設定されてありますので、そういう意味では、今回の健康保険法、その他の改正に準じて、こちらも改正を行うです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"それはよくわかっているんです。その話ではなくて、負担するという中で、その負担額について、制度で変えなきゃいけないのはわかるんですが、４００円とか、３００円とか、２００円とかというふうな算定をされるときに、何百円と言ったときの金額が妥当性があるのかどうか、そういう話はないんですかね。例えば地域によっても違うと思うんですよね。","respondent":"木下福祉高齢事業部長","answer":"これは昨年の秋前からの論議だったものですから、ちょっと私のほうでお答えいたしますけれども、１,３８０円がどういう形で出てきたかということにつきましては、いわゆる介護報酬について、昨年１０月、特別養護老人ホーム、老人保健施設。","voiceIndex":20,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"今部長がおっしゃったような形で、こういう状況があるから、こういうふうに今回直して、いろいろな数字がありますので、品川区の中では該当者がいないという形になっていますけれども、それはラッキーなんですが、やはり、今後制度改正で何かが変更になるといったときの根拠はやっぱり示していただきたいなというふうに思っていますので、意見として終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"三村委員","kind":"質問","question":"今回、このひとり親家庭の医療費助成の変更というところが老人保健法の改正によるというところから来ているということだったんですけれども、老人保健法のほうでいろいろお金の支給やなんかを見ていきますと、あんまですとかマッサージ、はり・きゅうなんかにも支給されているんですけれども、こういったところは区の助成という形で出ているんですか、そういうのも国で定めた基準か何かでされているんですか。","respondent":"諸岡児童課長","answer":"健康保険法等に、老人保健もそうですけども、定められて、自己負担、いわゆる保険適用外となっているものについては、同様に自己負担ということでお願いをしております。","voiceIndex":23,"id":"exchange-010"},{"speaker":"三村委員","kind":"質問","question":"品川の福祉の９５ページのここの支給額のところに、１億円近く、あんま、マッサージというところで１億円近く、はり・きゅうのところで３,０００万円ぐらい出ているんですが、ここはどういったお金なのか、区のほうから出ているお金なのかなと思って理解していたんですが、違うんですか。","respondent":"冨岡高齢事業課長","answer":"これは医療費支給額ですので、個人負担の分を除いた分で、区のほうから出ているものです。個人負担を除いた分です。区から出ているものです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"三村委員","kind":"質問","question":"こういったあんまですとか、はりとかきゅうというところの、区から助成をしているというようなことを考えると、やっぱり切実度で言うと、先ほど鈴木（ひ）委員もおっしゃっていましたけど、７０歳以上で１８歳以下のお子さんを育てられていて、しかも入院をしているというような状況下で、こういったところにこれだけのお金をかけられるんであれば、実際に現在適用者がいないというような状況も考えて。","respondent":"諸岡児童課長","answer":"療養病床に入院されている７０歳以上の方、これが１８歳未満の児童の親として子どもを監護している状況かという部分の話になってくるわけですが、厳密に申し上げますと、この制度においての親として監護している条件の中に、一つは同居していること。","voiceIndex":27,"id":"exchange-012"},{"speaker":"三村委員","kind":"質問・要望","question":"適用の可能性、そういう対象者が出てくる可能性というのはかなり低いというようなことだったんですけど、逆にそういう対象となられた方が出てきた場合はものすごく厳しい状況下に置かれるというのは容易に推測できる状況にありますので、今回は高齢者の医療費の法律のほうの改正にのっとってということだったんですけれども、その一方で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今度の改正自体が老人保健法の改正に伴うものであるのと同時に、７０歳以上の方で子どもさんが１８歳というと、出産時で考えると５２歳、なかなかケースとしても少ない。これからもあまり出るケースではないんじゃないかなということからも、万が一７人の方が対象となった場合、費用的な負担はかかるかもしれませんが、最後に説明いただいた部分でもやむを得ないと思いますので、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-014"},{"speaker":"三上委員","kind":"意見","question":"私も賛成いたします。特に先ほど来説明がありました７０歳以上の方について、同居ということが前提になっているということでありますので、この方たちが同居という条件が外れた場合には何らかの対応をせざるを得ないと、こういったことがきちっと説明がありましたので、そのことについては将来的にもそう不安はないんではないか、こういうふうに思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"条件そのものが本当に違いますし、そして、先ほどご答弁にもあったように、７人の方が既に７０歳以上の方がいらっしゃるということでは、可能性としてこれから出てくるということで、しかも、この可能性を考えると、かなり厳しい状況の中でこれだけの大幅な負担増をするということに対しては反対ですし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、そうなったときに、少人数ということもありますので、きちんとそこは区のほうで把握をしていただいて、問題が起きたときに、やはり子どもさんの保護というのは非常に大切なことですので、対象のほうを基準どおりにしていただきたいなというふうに思っていますので、お願いをして賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-017"},{"speaker":"三村委員","kind":"意見","question":"私たちの会派としては反対です。先ほども述べたように、次世代育成ということで、子どもを育てている家庭の経済的支援をしている中で、こういった逆行するような制度改正ということには賛成できないということで反対をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この地域密着型多機能ホームの施設ができるということは、本当に区民の方も待たれているものですし、喜ばしいことだと思っています。それともう一つは、第２項の食費その他の費用で利用者に負担させることは適当と認められるものというものの中身はどういう中身なのか、そして、それが具体的にはどれぐらいになるのかということをまず教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"１割負担の部分ですけれども、小規模多機能型居宅介護につきましては、要介護２の場合ですけれども、月に約１万７,５００円です。それから、すみません、小規模多機能について、ちょっと今ほかのものが、手元に資料がございませんので、後ほど。","voiceIndex":42,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、ちょっと私も仕組みがいま一つよくわからない部分が小規模多機能なんですけど、これはショートステイを利用する、それから利用しない、どれぐらいの頻度かとかと、そういうことにかかわりなく１割負担というのは同じというふうに考えていいんでしょうか、そこら辺の仕組みもちょっと教えてください。","respondent":"蓼沼高齢福祉課長","answer":"対象者につきましては、基本的には重度という方を想定しておりますけれども、要介護１から５までの方が利用できることになっております。予防ということで、先ほど申し上げましたように、要支援の方も利用することは可能です。","voiceIndex":44,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その利用料は所得によって減免をするという制度というのはできないんでしょうか、そこのところをちょっと教えてください。","respondent":"蓼沼高齢福祉課長","answer":"やはり、一定程度利用料の中に家賃相当の部分が入ってくるのは、それはいたし方ないところです。低所得の方への減免というのは、今のところは予定をしておりません。","voiceIndex":46,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やっぱり、区がつくる施設ですから、一定所得以上の人しか対象にできないというのは問題があると思うんですよね。そういう点では、所得の低い人でも減免制度をつくってここに入れるという施設にぜひご検討いただきたいというふうに思うんです。それともう一つお聞きしたいのが、３点目の介護予防拠点ということなんですけど、これは具体的にどういう中身なのかをちょっと教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"今後法人、運営事業者とどのような事業を実施するかというのは詰めていくところですけれども、地域の方々になるべく気軽にご利用いただけるような、介護予防事業に効果のあるメニューを考えて、そういうものを実施していきたいというふうに考えております。","voiceIndex":48,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その場合、介護予防拠点の中身はまだこれからということなんですけど、それがどういうものが想定されるのかということと、その利用料、そのことがどうなるのかということをちょっと教えていただきたい。","respondent":"蓼沼高齢福祉課長","answer":"今現在、介護予防事業につきましては、７種類ぐらいのメニュー、デイサービス活用型、あるいは区民共同型ということで実施をしておりますけれども、こういった今現在行っている事業を参考としながら。","voiceIndex":50,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"利用料はできるだけかからない方向でよろしくお願いします。ここの第８条から手続については書かれているわけですけれども、ここのところには指定管理者の指定を受けようとする団体は申請書に事業計画書、その他規則で定める書類を添付してということで書かれているんですが、この中身、規則で定める書類というのがどういうものなのかをちょっと教えてください。","respondent":"蓼沼高齢福祉課長","answer":"これにつきましては、事業計画その他ということで、法人の定款ですとか収支計画、重要事項証明書等、ちょっと今思いつくのはそのぐらいですけれども。","voiceIndex":52,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうに前にご報告いただきましたけれども、次回の第４回定例会のところで、議会の中で、この委員会の中でもその問題を議決するに当たって審議していくと思うんですけれども、そのところに、私はこの事業計画書、その他規則で定める書類、それから私はこの規則もまだできていないということで、決裁を受けていないというふうなことで課長からちょっとお聞きしたんですけど。","respondent":"蓼沼高齢福祉課長","answer":"指定管理者に関する基本的に所管が企画部のほうということで、中心に今動いておりますけれども、そういった企画との調整もありますので、今後第４回定例会で提出する資料については検討させていただきたいと思います。","voiceIndex":54,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当は、本来であれば、私はこの指定管理者の包括条例というふうな形でしっかりとそこら辺の問題を条例の中で規定して、どの指定管理者に対しても適用できるという大もとのものをつくるべきだというふうに思うんですけれども、それが今はない時点ですから、ここの中にぜひ情報公開条例を適用するというふうなことでお願いしたいと思います。","respondent":"木下福祉高齢事業部長、蓼沼高齢福祉課長","answer":"今度の委員会の中でどういう資料でご説明するかにつきましては検討させていただきたいと考えています。その辺、よろしくお願いします。新生寿会がその規定があるかというのは、すみません、ちょっと把握しておりませんけれども、いずれにいたしましても、区内の法人も今そういう規定がないところは整備しておりますし、既にある法人もありますので。","voiceIndex":56,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"しかも、いろんな問題が今起こっていますよね。じゃあ、その給食調理はどういう体制で、どういうふうな状況になっているのかというのは、全く私たちが情報を得ることもできないし、チェックをすることもできないというのが今の状況になっているわけなんですよね。そういうふうなところでどう考えられるのか、株式会社がそういうふうなものを持っているかというか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本来であれば、包括条例というのがあれば、全体でどうするかというふうな論議を行財政改革特別委員会とかそういうふうなところでできていくと思うんですけれども、そういうふうなのがなくて、今回は一つ一つのこういう条例の中でその中身についてというふうなことを規定せざるを得ないというのが今の品川区の仕組みになっていますので。","respondent":"木下福祉高齢事業部長","answer":"このやり方については、株式会社の指定管理者が生じた場合についても、基本的には同様の考え方で、区のほうとしては対応していきたいというふうに思っております。","voiceIndex":61,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが今の品川区の実態ですから、私はこういうふうなところからふじみ野市のプールの事故のようなことにもつながっていったとしても、それをチェックできる仕組みに品川区がなっていないという状況なので、ぜひこの問題については情報公開条例を、個人情報のこともこういうふうに規定を入れられているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-029"},{"speaker":"三上委員","kind":"意見","question":"ちょっと私もあれなんですけど、小山の家というのがありますよね、同じような、近くのところに。逆に、施設側が利用者に何らかの瑕疵があって損害を与えた場合ということが抜けているということになると、私は法律的にどうなのかちょっとわかりませんけれども、対抗できるのかどうかと、そういったことについての検討はされているのかどうかということについて、ちょっとお知らせいただけませんか。","respondent":"蓼沼高齢福祉課長","answer":"名称の問題ですが、委員ご指摘のようにわかりやすい愛称のようなものをつけられないかですが、これにつきましては、まさしく私どももそのとおりだというふうに認識をしておりまして、ご寄附いただいたのが亀田さんということで、地元の人等からも。","voiceIndex":64,"id":"exchange-030"},{"speaker":"三上委員","kind":"質問・要望","question":"それは無責任なことはしないということはわかりますけれども、利用者に対しての説明は当然こういったことで、これは条例に基づいて利用者にいろんな資料提供すると思いますけれども、そういったところで見たときに、そういった文言というのは入っているほうがより親切じゃないのかな、安心していただけるんじゃないかな、こういうふうに思うんですけれども、どうなんでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"万が一利用者に何かあった場合のときの対応、あるいは安心というお尋ねですけれども、この条例ではそういう規定はないわけですけれども、当然のこととして、指定管理者として指定する際に提出をしていただく必要な書類。","voiceIndex":66,"id":"exchange-031"},{"speaker":"三上委員","kind":"意見","question":"そこらあたりはお願いしておきますけども、やはり、しっかり検討していただいて、できるものについては一応やはりうたっておく必要があるんじゃないか、こういうふうにだけお願いしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"セキュリティですね。指定管理者ですと、３年とか５年とかという規定があると思うんですが、その中での継続性がどうなのかという、継続的なサービス提供もある程度きちっとうたっておくべきではないのかなと。その辺も入れるべきではないかなと思います。この条例の中で見ますと、そこは条例化をするわけですから、きちっと責任の範疇というのは明記をするべきではないかなというふうに思っています。","respondent":"蓼沼高齢福祉課長","answer":"継続性等につきましては、今現在企画のほうでも指定管理者のその後の管理の安定的な継続性ということで、あり方について検討していますので、そういった点も含めて検討していくべき内容なのかなというふうに考えます。","voiceIndex":69,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、この管理をするという条件の中で、やはりきちっと条例化をして、責任範囲というのはここなんですよということはうたっていかないと、ここに地方自治法と書いてある部分があるんですが、そこの項目を別建てにして、ここまではきちっとやってくださいという、それが契約になると思うんですよね。そこで決定という形になりますので、できる限り整合性をとっていただきたいというふうに思っています。","respondent":"木下福祉高齢事業部長","answer":"そのこと以前に、やはり事業者として事故対応というのは特に福祉の現場では重要な要素でありますから、この辺が適切にできないような事業者は逆に指定管理者にはたぶんならないと思うんですけれども、区のほうも適切な指導をしながら。","voiceIndex":71,"id":"exchange-034"},{"speaker":"飯沼副委員長","kind":"質問","question":"この課題については何点かあるんですが、周知方法や時期、この辺はかなり行われてきているんではないかなと思いますけれども、議会への説明および情報提供、この点と、あと選定委員会の構成、あと評価の基準、作成というところがこのときの課題で大きな部分であったと思うんですが、この辺がその後どうなっているのか、私どもとしては、指定管理者制度の手続条例とか、包括条例とかをつくる方向にいけば。","respondent":"蓼沼高齢福祉課長","answer":"先ほど少しご説明いたしましたけれども、その評価の基準等につきましては、今現在企画のほうで検討を進めているという状況です。具体的に今どの辺まで進捗しているかというのは把握してございません。","voiceIndex":73,"id":"exchange-035"},{"speaker":"飯沼副委員長","kind":"提案","question":"この指定管理者制度というのは、区が、行政が選定をして議会に提案をしてくるというところですけれども、一番は指定をするところのやっぱり透明性とか公平性がすごく大事であるなと思っているんですが、そのスタートの時点のところで、昨年ですか、平成１７年９月１日に指定管理者制度活用に係る基本方針というのが出ていますけれども、この辺を見ても。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-036"},{"speaker":"飯沼副委員長","kind":"質問","question":"昨年の８月に今後の予定表をいただいたわけですけれども、こういった事業者を選定しました、あと、こういった中身で具体的に進んでいますという報告は受けているわけですけれども、やはり最終的なところで議決の部分、この条例の中身と議決の部分でしか私たちはきちんと表明ができないというところにおいては、やはりそのところが企画部で論議をしている部分でも。","respondent":"蓼沼高齢福祉課長","answer":"企画部のほうで、そういうことで今いろいろご指摘のあった点も含めて検討することになるのではないかというふうに思っておりますので、いろいろな先ほど継続性ですとか、罰則等についてのご意見もありましたので。","voiceIndex":77,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も賛成です。先ほども申し上げましたように、利用料はぜひだれもが入れるような減免制度、それから低廉なものにしていただきたい。そしてまた、指定管理者のところでは、情報公開、ここのところをしっかりと今後整備をする方向でご検討いただきたいという意見を申し述べて、この条例については設置条例ですので、賛成ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、改めてこの児童学園というのがどういう施設なのかということを教えていただきたいんですけども、どういう子どもたちが対象になるのか、そして、どんな経過の中でこの児童学園を利用することになってくるのか、また、事業の内容、ここら辺についてちょっと教えていただけないでしょうか。","respondent":"西島障害者福祉課長","answer":"集団の中で個々の充実を促し、また、適切な助言を行いまして、望ましい母子関係の充実を図っていく、こういうような事業を実施しています。","voiceIndex":92,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"利用料については、階層が段階別になっていて、４,５００円から３万３,７００円ということですけれども、これが今度の３月までこのまま延期ということですけど、もし本来の形になるとしたら、非課税の方の低所得の１、２、それから、市町村民税２万円まで広げられたということなんですけれども、その場合と、それからそれ以上の一般の方の負担というのが１割の利用料と、それから食費ですか。","respondent":"西島障害者福祉課長","answer":"これは制度の関係で、例えば３万３,７００円の方は母子通園ですと、週３日行かなくても３万３,７００円、５日行っても、３万３,７００円、措置の時代はそうなっていましたけども、これからは来た日数で変わってまいりますので、そういう意味では。","voiceIndex":94,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは食費も含めてということでしょうか。それと、先ほどどういう施設かということでご説明いただいたんですけど、ここに通う経過なんですけど、これは例えば保健所とか安心センターとか、そういうところでの、どういう形でここに通っていくかというのをちょっと教えていただきたいんですけど。","respondent":"西島障害者福祉課長","answer":"ここへ行く方はさまざまでございましょうけれども、保健所の３歳児健診等でアドバイスというようなこと、あるいはどうもちょっと発達に遅れがあるんではなかろうかという親御さんなり、あるいは周りの方が感じていらっしゃった方が相談をして。","voiceIndex":96,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これを見ると、子どもの発達相談室というのがあって、さまざまいろいろ相談を受けたというふうなのが書かれているようなんですけれども、それが１９９８年からすごい短い１ページにも満たないぐらいの福祉の記載になっているんですけれども、ここら辺の移り変わりがどうなっているのかということと、それともう一つ、予算面で、２００３年のときは、８,３２４万円ぐらいの予算に。","respondent":"西島障害者福祉課長","answer":"とは言いましても、１０分の１０では足りませんので、区がそれに上乗せをして、事業を運営してきたという経緯があります。それから、今後どうなるかですが、自立支援法の枠に入ってまいりますので、２分の１、４分の１、４分の１という形になってくるだろうです。","voiceIndex":98,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"財源が今までは東京都から１０分の１０、そして区が上乗せしていたものが、２分の１、４分の１、４分の１という構成に変わってくるわけですけど、このことで先ほどの延期をする部分、百数十万円は除いて、こういうふうに負担割合が変わることで、区の財政負担というのはどれぐらい増えるかわかったら教えていただきたいと思います。","respondent":"西島障害者福祉課長","answer":"先ほど言いましたように、区がそれに２,５００万円ぐらいを上乗せして払っているということもありますので、そんなこともご考慮いただければというふうに考えているところです。","voiceIndex":100,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回区がこういう形で軽減策をとられたというのは本当に評価しますし、よかったなというふうに思っているわけなんですけれども、これはぜひ今後もこういう形で継続をさせていただきたいというふうに思うんですが、その区がこういう形で延期をする、また助成をするというのは、今回のこの条例とは関係なくて、規則か何かで決まるということになってくるんでしょうか、そのことだけ教えてください。","respondent":"西島障害者福祉課長","answer":"法律の構成上、そこの部分を条例にというのはなかなか難しいので、条例は条例として成立をさせていただきたいというふうに思ってあります。","voiceIndex":102,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"２５人今通園されているということなんですが、大体先ほどもお話がありましたが、お子さんに初めから、産まれたときから障害があるというふうにわかっていればいいんでしょうけれども、そうじゃないお子さんというのは結構いらっしゃるんじゃないかなと思うんですね。そういう方たち、いわゆる併用して使われているというケースが多いんでしょうか。それとも、ここ児童学園だけという方が多いんでしょうか。","respondent":"西島障害者福祉課長","answer":"ここで先ほど説明しましたけども、一定の訓練といいますか、お母さんの気持ちの整理もあわせてさせていただいて、概ね１年、１年半で区内のほかの保育園なり、幼稚園なりに転園して、そこで集団生活が可能になる。","voiceIndex":104,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"当然トータル的に考えたときに、どう考えていくのかなという、これは担当が変わっちゃうかもしれないんですが、これからの就学前の子どもたちというとらえ方もあるだろうし、幼稚園・保育園という考え方もあるだろうし、制度もいろいろ変わってくる中で、この考え方というのは今後見直していくということはあるんでしょうか。","respondent":"西島障害者福祉課長","answer":"ただ、だからといって、それをそのまま利用料に反映していいのかというところの部分は、先ほどお話ししましたように、若い保護者の方が多い、それからまだ障害の認知も親御さんの気持ちの中で整理されていない方に対してどうなのかというようなところもありますので。","voiceIndex":106,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"今回の経過措置をとっていただいたということは非常にありがたいなとは思うんですけれども、実際に来年の４月から決定していかなきゃならないというところでは、そこはなるべく負担にならないような形で、品川区としてこういう子どもたちに対しては、こういうことをするべきだというようなある程度のものをつくっていただきながらの利用料であると助かりますので、ぜひ半年間の中でいろいろ考えて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-047"},{"speaker":"三村委員","kind":"質問","question":"先ほど来、保育料制度を目安にということだったんですけれども、今区立の保育園を利用しますと、保護者の所得に応じてかなり細かく段階が分かれて、料金設定がされているんですけれども、それと同じように、低所得であるがために通えないということが出ないような、そういう親が負担できる範囲内に、親の所得に合わせて細かく規定していくというような方向で考えていらっしゃるのか。","respondent":"西島障害者福祉課長","answer":"ただ、私ども今回この条例改正に当たりまして調べましたところ、比較的低所得の方は少ないというのが、これはどういうあれなのかわかりませんけど、たまたまなのか、児童学園については比較的住民税均等割以下の方はいらっしゃいませんでしたので。","voiceIndex":109,"id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この児童学園の職員体制がどうなっているのかについてだけ教えてください。","respondent":"西島障害者福祉課長","answer":"現在１０名の方が、これは施設長も含めてですが、児童学園にはいらっしゃいます。２名が非常勤です。それ以外に、いわゆるＳＴとか、それからお医者さん等は別途、それは非常勤で来ていただいているという内容です。","voiceIndex":111,"id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"意見","question":"児童福祉法の改正に伴っての規定整備ということですので賛成です。それと同時に、３月までの負担の対応をしていただいている、４月以降も大分ご検討していただいているということで、この改正条例に対して賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-050"},{"speaker":"三上委員","kind":"意見","question":"国がこういった形でいろいろ考えているということでありましたので、それはいいことだと考えています。そういったことを受けて、品川区の条例を整備するわけですので、私どもはこれについて賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ぜひ、この問題については、半年間で百数十万円ということですので、ぜひ負担を増やさないということでお願いしたいというふうに思います。この条例に関しては、そこは規則で決めるということで、この条例そのものは自立支援の１割負担というふうなところに、そういうものをもとにした規定ですので、この条例そのものに対しては反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-052"},{"speaker":"木下委員","kind":"質問","question":"国のほうの児童福祉法が改正されて、それに伴ってということで、それと品川区のほうとしてもできる限りの対応をやっていきますというお話ですから、私としては賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-053"},{"speaker":"西本委員","kind":"質問・要望","question":"今回、非常に国のほうの法律化が遅くなったという事情を含めて、いろいろできる限りのことをしていただいたと考えています。先ほども言いましたけれども、このまま来年４月に向けて、なるべく一人ひとりが平等にいろんなサービスが受けられるような形をぜひ考えていただきたいと思いますので、条例に賛成という形でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-054"},{"speaker":"三村委員","kind":"質問・要望","question":"今回いろいろ利用料の負担が増えないような形で整理していただいたということと、あとぜひ先ほど明確なお答えはなかったんですけれども、ぜひ保育料程度というところで現在の区の保育園の料金体系等も考え方の中に反映をさせていただきたいということを強く要望いたしまして、この条例には賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-055"},{"speaker":"三村委員","kind":"質問","question":"３５ページの戸越台の特別養護老人ホームの屋上緑化についてお伺いしたいんですけれども、この屋上緑化というのは、ただ単にヒートアイランド対策みたいな形で緑化をするのか、それともそれに屋上緑化を使って高齢者の方に作業してもらったりとか、そういう作業療法の視点も取り入れたものになるのか、その辺のところについてちょっとお伺いできればと思います。","respondent":"蓼沼高齢福祉課長","answer":"それともう一つ、戸越台中学校との合築ですので、子どもさんたちにも緑化で何か作業といいますか、お手伝いできるところがないかなということで、中学校の子どもさんたちとの触れ合いの場、交流の場ともしたいということで。","voiceIndex":127,"id":"exchange-056"},{"speaker":"三村委員","kind":"質問","question":"ぜひ高齢者の方たち、緑豊かな環境で小さいころから育たれて、そういった園芸療法だとか、そういう緑に触れるということはたぶんとても影響があるかと思いますので、ぜひ収穫の喜びだとか、そういうのも取り入れられるような、稲なんかでも小さいスペースとかでできたりとかしますので、ぜひそういった視点を取り入れて進めていただければなと思います。その辺、１点だけお伺いできればと思うんですけれども。","respondent":"蓼沼高齢福祉課長","answer":"この夜間対応型訪問介護につきましては、最初にこの事業の創設を考えたきっかけというのは、緊急通報システムだというふうに聞いておりますので、これ自体につきましては介護保険制度を利用しての高齢者に対するサービスになりますけれども。","voiceIndex":129,"id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点だけ確認をさせてください。認知症高齢者グループホーム整備助成事業、追加の３,０００万円ですが、これは八潮ということだったんですけど、八潮のどの辺で実施ができるのかなというのが１点と、それから、数字からすると、２,５００万円が来る分で、５００万円は区の一般財源ということになっているんですか、その２点。","respondent":"蓼沼高齢福祉課長","answer":"交付金が２,５００万円ということで、これは国からの交付金です。残りの５００万円につきましては、一般財源ですけれども、東京都と今引き続き協議を進めておりまして、備品の購入費ということで、一定程度補助できないかということで、今協議を進めているところです。","voiceIndex":132,"id":"exchange-058"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"グループホームができるということで、これからうまく運営のほうもやっていっていただきたいということだけ要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"夜間対応型の訪問介護についてお聞きしたいんですけど、これは登録者制になるのか、ちょっとイメージがいま一つよくわからないので中身を教えていただきたいんですけど、登録者という形になるんでしょうか。それと、この運営事業者は株式会社ジャパンケアサービスということなんですけど、なぜこの事業者なのかということについても、３点お聞かせください。","respondent":"蓼沼高齢福祉課長","answer":"ニーズにつきましては、個別具体的に把握してはおりませんけれども、やはり、この２４時間３６５日在宅生活を支援するということでは、この地域密着のこのメニューとしては、先ほど申し上げましたような２０万人の規模に３００人という利用者を想定しているですので。","voiceIndex":135,"id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、公募があって、選定してきたということなんですけど、どういうところが、どれぐらい公募してきたのかということを教えていただきたいのと、それともう一つ、ここの中身なんですけど、オペレーションセンターがあって、訪問介護にというふうなことになっていて、訪問介護にというのは、毎日２名以上ということになっているんですけれども。","respondent":"蓼沼高齢福祉課長","answer":"ヘルパー２名を配置して、基本的には定期の巡回とそれから随時の訪問ヘルプという組み合わせになりますが、２名のほか、今後事業を実施して、どういうような利用者の見込みといいますか、推移が出てくるかによると思いますけれども、そういう定期訪問。","voiceIndex":137,"id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その介護報酬とそれにプラスする形で委託費という形で出てくるというふうに考えていいんでしょうか、その点だけ教えてください。","respondent":"蓼沼高齢福祉課長","answer":"当初在宅介護支援センターのほうも同じような流れで直接国保連から在宅介護支援センターに支払うということで話を進めておりましたけれども、在宅介護支援センターというのは、品川区の場合は独自の形で地域包括支援センターが１カ所という位置づけになっています。","voiceIndex":139,"id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ということは、この新予防給付ケアプラン作成委託費というのは、在宅介護支援センター１９カ所で、新予防給付のケアプランをつくったときの、その介護報酬という意味で、それがこの１０月から来年の３月までのという意味でいいんでしょうか。そこの確認だけ。","respondent":"蓼沼高齢福祉課長","answer":"今委員おっしゃったとおりです。","voiceIndex":141,"id":"exchange-063"},{"speaker":"木下委員","kind":"質問・要望","question":"ちょっと先ほど運営会社を選定する際、ジャパンケアサービスさんともう１社があったということで、ジャパンケアサービスは実績かなんかがほかのところであったかどうかというのをちょっとお聞きしたいのと、利用料金の設定なんですが、料金の設定は何かの基準があってこの料金にされていらっしゃると思うんですけれども、そこら辺のことをちょっとお聞かせ願えますでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"ジャパンケアサービス、夜間対応型訪問介護の実績ですが、これはご案内のように、世田谷区のほうで、厚生労働省のプロジェクトとしてモデル的に取り組んでおりまして、世田谷区のほうでは既に実績があります。９月現在１０１名の方が利用されているというふうに聞いております。","voiceIndex":143,"id":"exchange-064"},{"speaker":"木下委員","kind":"質問","question":"要するにいろいろな業者がいらっしゃるので、ここの夜間訪問型介護のサービスを受ける場合には、定期型巡回サービスも必然的にこちらの会社になってしまうという理解でよろしいのかということで、ですから、今別な定期巡回サービスを頼んでいらっしゃるところが、新たに夜間対応型サービスを受ける際には、その場合は定期巡回型サービス会社はそのままで。","respondent":"蓼沼高齢福祉課長","answer":"今行われている既存の２４時間巡回型のサービス、これにつきましては、事業者が幾つか入っていると思いますけれども、２４時間と夜間対応型とは別の制度になりますので、こちらのほうは今事業者がジャパンケアサービスということで実施をしていく予定ですけれども。","voiceIndex":145,"id":"exchange-065"},{"speaker":"木下委員","kind":"質問","question":"ちょっと細かいことになっちゃうので。基本的に定期巡回サービス、ジャパンケアサービスでサービスを受けていない方が、夜間対応型訪問介護を受ける際には、ジャパンケアサービスのほうに定期巡回サービスを頼まなければならないのかという意味合いでちょっとお聞きしたんですが、それは別のサービスということなので、別にジャパンケアサービスのほうに頼まなくてもいいという理解でよろしいでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"はい、そういうことです。","voiceIndex":147,"id":"exchange-066"},{"speaker":"三上委員","kind":"質問・要望","question":"今のところで、説明のときに聞き漏らしたのかどうかちょっと確認させていただきたいんですが、利用者の方が夜間の介護に不安のある方で、世帯状況は限定しないというような説明書きになっている。この世帯状況は限定しないということは、要するに、介護する人が、家族がたくさんいたにしても、そういうことは問題ないですよと。希望すれば、それに随時応じていきますという、そういう理解でよろしいんですか。","respondent":"蓼沼高齢福祉課長","answer":"ご家族の方がいらしてもサービスが利用できますということで、特に夜間の介護ということが家庭での、在宅での、介護の困難性の負担の一つになっておりますけれども、そういうことで、介護者がお休みになっているときに。","voiceIndex":150,"id":"exchange-067"},{"speaker":"三上委員","kind":"質問・要望","question":"もう一つちょっと確認させていただきたいんですが、認知症高齢者グループホームのほうで、八潮でミモザという会社が整備するということで、完全に民設民営ということでは聞いておりました。既に地元説明会を行ったのか、これからなのか、要するにやるということだけの案内はちゃんと私も見たんですけども、その説明会というのは終わっているんですか。","respondent":"蓼沼高齢福祉課長","answer":"八潮に整備予定のグループホームの件ですが、地元説明会は２１日に実施されてあります。","voiceIndex":152,"id":"exchange-068"},{"speaker":"鈴木（真）委員","kind":"確認","question":"もう一回ちょっと確認させてください。夜間対応型の件で、利用料のところを見ていて確認をしたかったんですが、基本料金はわかるんですけど、定期巡回サービス、これは１回３７０円というのは、１日１回という間隔で、１カ月約１万円ぐらいが入ってくると思うんですよね、３０日と考えると。","respondent":"蓼沼高齢福祉課長","answer":"そのとおりでございまして、基本料金とあとは随時だけなら随時だけでもという利用の仕方も大丈夫です。ちなみに、定期巡回につきましては、国の想定ですと、大体お一人１日１件といいますか、定期利用があるのではないかというような想定をしているようです。","voiceIndex":154,"id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"イメージが私はちょっとつかないところがあるんですけれども、地域密着型サービスで、具体的なところになってしまうんですが、地域を常に車なんでしょうかね、それが回っているという状況なんですか。先ほどもちょっとあったと思うんですけれども。そこら辺はもっと要望が多くなってきた場合に持ち出し金とかが将来的にどうなんだろうなというところがあるんですが、その辺の見通しはいかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"３,０００万円というお話ですけれども、これにつきましては、当初のいわゆるオペレーションシステム、ケアコール端末設置のそういう設備の整備費用です。","voiceIndex":156,"id":"exchange-070"},{"speaker":"西本委員","kind":"質問","question":"わかりました。結構このサービスを利用するケースは増えてくるんじゃないかなという予測はあるんですよね。それで、特に先ほどもありましたが、世帯状況は限定しないということですから、やはり夜間の介護は大変ですから、たぶんそういうことではお願いしたいというケースもかなり増えてくるんじゃないかなというふうに思うんですが、その辺の見通しはいかがなんでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"初年度あたりは、やはりどうしても利用者が少ないであろうということで、経営的にはマイナスというのが想定されますけれども、シミュレーションとしてはそんな形で、２年後、３年後では平年度化されれば事業は回転していくと、そういう見込みを立てております。","voiceIndex":158,"id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"初めは難しいだろうというところで、では、その難しいとなったときに、例えば区としてある程度補てんしてあげるとか、ある程度支えるとか、そういうことは全くまだ考えていない。要は、事業所のほうで考えてやってくださいねという形になってしまうのか、区のかかわり方、資金的なところも含めて、それはいかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"そういうことで、事業者のほうが収支が立つということで手を挙げてきたです。利用者につきましては、区のいわゆる在宅介護支援システムを通じてご利用者については案内といいますか、紹介するというようなことは当然連携をとってやっていくことになります。","voiceIndex":160,"id":"exchange-072"},{"speaker":"飯沼副委員長","kind":"質問","question":"ちょっと最初のご説明で聞き漏らしたのかもしれませんけど、地域介護・福祉空間整備等交付金、あと空間推進交付金と目新しい名前なんですけれども、これがどういう中身なのかというのと、今回の夜間対応型の訪問介護以外にも使える交付金なのかどうか、ちょっとそこの中身の性質のところをお伺いしたいのと、上のタイトルのところに「地域密着型サービス」と書いてあるところにおいては。","respondent":"蓼沼高齢福祉課長","answer":"今回の夜間対応につきましては、推進交付金という交付金のほうになります。これはソフト系と言っておりますけれども、そういう設備等の整備に対する助成。大まかに言いますと、そういうような使い道になります。","voiceIndex":162,"id":"exchange-073"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"認知症の高齢者のグループホームのところなんですが、ちょっと認識がなくて、どこの場所なのかなと思っていたら、八潮にというところで、ここで整備費助成事業の追加分と書いてあるんですが、ここに関しての追加分なんですか。そういう意味じゃなくて。どのくらいのお金がこの民間の支援に入っているのかなと、ちょっと総額のところを教えていただきたいです。","respondent":"蓼沼高齢福祉課長","answer":"当初予算に計上しておりますのが５,２００万円ほどありますが、これについては中延のほうに今やはり民間の方が整備を進めている、ツーユニットですけれども、グループホームがありますが、こちらについての支援をするということで、当初予算に計上しているものです。","voiceIndex":164,"id":"exchange-074"},{"speaker":"飯沼副委員長","kind":"質問","question":"このようなたぶん助成が入る基準というのがありますよね。そういった面で、利用料を設定するときの助成金が入っていく上での条件とか指針とか、そういった利用料を設定するに当たって何かあるんでしょうか。その辺、ちょっとわからないので教えてください。","respondent":"蓼沼高齢福祉課長","answer":"利用料ですけれども、これにつきましては、事業者のほうからの提案を受けて、これは都と区で協議をいたします。なるべくそう高くはない、低廉な価格でということで具体的に都と区と事業者、三者協議の中で設定をしているという状況です。","voiceIndex":166,"id":"exchange-075"},{"speaker":"飯沼副委員長","kind":"確認","question":"三者協議の中で適切な料金にしていくというところなんですね。そういう確認でよろしいんですね。","respondent":"蓼沼高齢福祉課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-076"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今のご説明で、最後は東京都の返還の時期が変わったというご説明があったと思うんですけど、変わった理由というのは、特別な理由というのは何かあるんでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"時期が変わったということではございませんで、償還の期限が１月末という指定がされておりますので、最終補正では間に合いませんので、今回補正を組んで期限に間に合うように返還するです。","voiceIndex":182,"id":"exchange-077"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それじゃあ、自分が聞き間違えたのかもしれません。さっき最終補正でやっていたのが、今度１月末に変わったのでというご説明だというふうにとったんですけど、それで理由は何かなと思ったんですけど。","respondent":"蓼沼高齢福祉課長","answer":"すみません、私の説明の仕方が不十分だったようで。通常は、こういう清算の場合は年度末にやるということになっておりますけれども、このうち都に返すものが、返還の期限が１月末という指定があったということで今回補正を組ませていただいたです。","voiceIndex":184,"id":"exchange-078"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今回補正は十分わかったんですけど、そういえば、去年今聞いていて、最終補正で介護保険をやらなかったんですよね。これは第３回定例会で補正して、そのまま最終でやらなかったというのを今思い出しました。わかりました。去年も同じようにやっているということで、わかりました。態度表明しちゃうと賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":189,"id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この１億４,０００万円余が国庫支出金返還金となっているんですけど、今の話を聞くと、都に７００万円というふうに言われたかと思うんですけど、この１億４,０００万円余のうちの国と都は、都が７００万円で残りが国ということになるのかということを一つお聞きしたいのと、もう一つ、こういうことは毎年起こっているということで、額も大きいのでということがあったんですが、超過交付金ということで。","respondent":"蓼沼高齢福祉課長","answer":"この返還金の中身ですけれども、都が約７００万円、国が約７,６００万円、それから支払い基金のほうが５,６００万円です。","voiceIndex":190,"id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この超過したという中身の主なものはこういうものがというふうなのがあればということで思ったんですけど、全体でということで、それはわからないということですので、それでは結構です。それで、この補正予算に対しては賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":192,"id":"exchange-081"},{"speaker":"三上委員","kind":"意見","question":"態度表明は賛成いたします。中身が余りにも国庫支出金等返還金というだけで、ちょっと中身がよくわからないという印象は持っていますが、そこらあたり、もう少しきちっと説明を、記入できないのかわかりませんけど、もうちょっと丁寧にわかるようにしていただければありがたいなということをつけ加えておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":193,"id":"exchange-082"},{"speaker":"西本委員","kind":"意見","question":"私も賛成いたします。が、やはり、改めてこんな補正を組まないといけない、やはりかなりずれるんだなというふうなことは実感しました。もう少しこちらのほうも中身を知りたいなというふうに思いました。賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":195,"id":"exchange-083"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"三村委員","kind":"質問","question":"一般質問で原議員がされていた障害者の自立支援について、今後、基本計画のほうをつくっていくかと思うんですけれども、その進捗状況と今後のスケジュール、また当事者の声をどのように聞いていくのか、パブリックコメントなんかはどのようにされていくのかお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3156#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":60548,"voices":203}},{"id":"h18-20060925-8","meetingId":"h18-cm09","date":"2006年9月25日","dateIso":"2006-09-25","committee":"建設委員会","time":"午前１０時０４分～午後０時１５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"今回の廃止の認定のところでは、ここの都市計画の部分で大変反対のあったところだと思いますけれども、その後の経過として、どのぐらいの計画が進んでいるのか、昨年の第３回定例会のときには、まだ地域の方たちとの理解が得られていなくて、区が事業者に説明を求めているという状況がありましたけれども、今の状況では、事業計画が進む、まちづくり協議会とか。","respondent":"青木都市開発課長","answer":"その後、ご指摘のとおり、いろいろご意見をいただいている中で事業を進めておりまして、直近では間もなく、平成１８年９月末、もう９月は終わってしまいますけれども、若干おくれているようですが、この秋に改めまして近隣の方々への説明会を開催する予定と聞いております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"説明会の開催というのは、どのレベルの説明会ということなのでしょうか。","respondent":"青木都市開発課長","answer":"これは条例に基づく説明会になりますので、建物の高さの２倍ということで、今回、この地区で計画されております建物の高さが海抜から１５３メートルほどということですので、敷地の外側３００メートルぐらいの範囲に入る近隣の方々に、お声をおかけして説明するというものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"井上委員","kind":"意見","question":"この説明というのは、建設に関する建築事業者の説明ということなのか、もっと前段階の説明になっているのかということと、区にも住民の方から相談が来ていると思うんですけれども、その状況というのは、まだまだ住民の方が納得しているというレベルではないのか、その辺の状況を知りたいんですけれども。","respondent":"青木都市開発課長","answer":"この説明というのは条例に基づくもので、高さの２倍の範囲ということで実施しておりまして、また、ご指摘の区のほうにいろいろな地元の方からのご意見があるのかというご質問ですけれども、直接は私どものところには近隣の方々からのご意見等はいただいておりません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"井上委員","kind":"確認","question":"再開発組合はもうそこで組織されたのかということが１つと、建築確認のような計画にのっとった説明ということなので、建築確認を申請する前の地域住民の説明会ということなのか、私はこの計画にずっと、前回の地区計画のときにも私たちのところでは反対をしているんですけれども、ここの場合、そういった今、動きがどの程度どういうふうに来たかということで質問させていただいているので。","respondent":"青木都市開発課長","answer":"再開発組合につきましては、平成１８年３月、本年３月に設立されております。現在は建築確認に向けての事前協議ということで、品川区、私どものほうには開発指導要綱に基づく協議書が回ってきております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"井上委員","kind":"確認","question":"確認だけです。出ているかどうかは、都とかがしないと多分わからないと思うんですけれども、出ているか出ていないかということを把握していない、報告がないということで聞いているということになるんですか。","respondent":"青木都市開発課長","answer":"大変申しわけございません。私の所管として、今、委員のおっしゃるとおり、どこまで出したかという報告を詳しく受けていないです。申しわけございません。","voiceIndex":14,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"この第７０号議案、第７１号議案の理由ですとかその趣旨については十分に理解できますので賛成いたしますが、ただ、これから工事を進めていく中で、この道路の工事と本体工事がぶつからないか、その辺の周辺の環境についてお聞かせいただきたいと思いますが、その手続を踏んでからでないと当然進められないし、先に道路を整備してしまうと、やはり工事車両が往来する中で道路が傷んじゃうとか。","respondent":"青木都市開発課長","answer":"その管理の期間が終わった後に実際の封鎖等の行為を行うんですけれども、工事につきましては、ご指摘のとおり、かなり長い期間の工事になりますので、最終的に道路線形あるいは歩道の形などがきれいに整うのは建物の完成の後になるかと思うんですけれども。","voiceIndex":17,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"少し教えていただきたいのは、先ほど説明がありましたけれども、東五反田二丁目６番地で今、事業計画に入っている面積が幾らかということと、６番と１０番のところで、容積率が幾らから幾らに変わるのかということを、そういう意味では、１０番なら１０番の間の路線もとれますから、全体の面積が変わってくると思うんですね、道と道の間の位置が。","respondent":"青木都市開発課長、松代管理工事課長","answer":"今回の道路が廃止されることによって容積率が変わるというものではないんですけれども、ここの第７０号議案の裏面に書いてありますように。それが今回付け替えで、周辺に地区幹線１－４号、区画道路１号、２号という形で計画を進めておりますが、その全体面積が２,０７６m2あります。申しわけございません。先ほどの従前の容積率ですけれども、現在、一般規制上は３００％の指定になってあります。","voiceIndex":19,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回、この道路の付け替えというんですかね、道路の変更によって、そのねらいは何なのかというところを少し教えていただきたいんですね。先ほどの近隣説明会の中でも、近隣住民からも規格の問題がご指摘されていますけれども、容積率が従前ですと３００％、一番南側ですと９９０％で変更するわけですよね。道路の付け替えをなぜこうするのか、そこがもう少し明確になれば。","respondent":"松代管理工事課長","answer":"生活環境がよくなって、都市基盤整備の道路が整備される。そういった目的で今回、廃止をし、新たに付け替えをし、認定をする、そういった手続を進めたものです。","voiceIndex":23,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"今の説明の中でも、生活環境がよくなるというお話がありましたけれども、私はとても近隣に住んでいる住民の方々、隣には学校があるわけですから、環境がよくなるどころか、日影、風害、それから生活空間が壊れてしまうようにしか思えないんですね。要するに３００％ですと、最高何ｍの高さができるんでしょうか。９９０％ですと何ｍの高さができるんでしょうか。そこを教えてください。日照被害が生じる。","respondent":"松代管理工事課長、青木都市開発課長","answer":"周辺の道路も、今回の地区計画の中で現道がほとんど１２ｍ、もしくは８ｍで、現道が５ｍ、８ｍの道路、周辺道路がそういう拡幅されることによって歩道等ができ、また、かつ一方通行がこの周辺は多いんですが。ご指摘の今回の再開発事業に伴う日影のお話ですけれども、従前３００％の容積率であったとしましても、これを高層化することは可能でございまして、大変申しわけないんですけれども。","voiceIndex":25,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"大きな影響はない。この前の説明ですと、周辺の開発を含めて、学校への影響は最大５時間だったと記憶しているんですけれども、日野学園のすぐ隣に１５３ｍの高さが建つわけですよね。ちょうど５ｍから１０ｍの歩道があるから、子どもたちも安心して通行といいますけど、実感としても、例えば西大井駅前のＪタワーとコアスターレがありますけど、あそこは１０ｍぐらいあるんでしょうかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"私はこういう形のときに現場を見たかった。現場を見ていないものですから、あの地区はほとんど足を踏み入れない。まあ、議員は自分で調べていらっしゃいというのかもしれないけれども、どういう状況になっているのか。そういう意味では、事前に見て、ここがこうなって、ここが廃止になんて、現場を見てこうなるんですという形があると、よかったと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今回、区道の廃止と認定なんですけれども、ちょっと確認しておきたいんですが、この再開発の地権者が３１人ぐらいいたのかなと思うんですけれども、内訳というのがわかったら教えていただきたいと思いますけれども。","respondent":"青木都市開発課長","answer":"私が持っています時点の資料で反対者はゼロ、保留という形で、例えば同意書にあたっての印鑑証明の手続がまだ終わっていないとかという、当時の段階でそういった方が３名いらっしゃったという状況で、原則全員同意ということでできております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、説明がありましたけれども、もうちょっと詳しく教えていただければということと、あとそもそもこの手法がどうなってこういうふうになるかというのがよくわからないので、教えていただきたいんですけれども、もともと特別区道を一たん全部廃止して、再開発のこの建物が建つ部分をまた新たに特別区道にして、その両側がまた認定道路になるということになるんですよね。","respondent":"松代管理工事課長、青木都市開発課長","answer":"これを一たん廃止をしませんと、次の裏のところの白抜きのここの部分を廃止することができませんので、一たんこの１路線を全部廃止をしまして、この白い部分が事実上廃止されます。先ほどのご説明でちょっと言葉が足りなかった部分ですけれども、権利者の同意の中で保留ということについてのご質問でしたけれども、保留というのは、原則同意はしていますけれども。","voiceIndex":33,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"今まで１本の道路だったのを３つに分割して、まず特別区道だったのが、両側が認定道路になるんですか。この性格というか、この真ん中のところは特別区道になるわけですね。認定道路と特別区道との違いというのは、ちょっと私よくわからないので、性格が違うのか、その辺がちょっとわからないんですけれども。","respondent":"松代管理工事課長、岩田まちづくり事業部次長","answer":"ここの部分が今回廃止になりますので、この部分は従前と同じように区道としての全くの同じような位置づけで管理をしていきますけれども、管理をするためには、そこの路線をきちんと認定をして、路線番号をつけて。これが認定外道路と言われていまして、これも区道と同じ扱いで、道路法の適用は受けませんけれども、区道として区が管理をしている道路が別に存在していますので。","voiceIndex":36,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問","question":"同じだということは、そうすると再開発でこの道路のところ、特別区道ですよね。こちらのほうも特別区道と同じということになくと、こちらの再開発の中にあるんだけど、区が管理して、いろいろ補修だとか、そういうのも責任は区が持っていくということになるんでしょうか。","respondent":"松代管理工事課長","answer":"そうです。","voiceIndex":39,"id":"exchange-015"},{"speaker":"宮崎委員","kind":"確認","question":"それとあと地権者のほうで保留が３ということで、原則合意ということで今、説明があったんですけれども、私は原則同意というのはどういうふうに確認するのかというのが、私はあくまでも書類上でそろっていかないと、なかなかそれは合意というふうにいかないんじゃないか。どういう形で確認しているかによっては、もしかしたらいろいろ状況が変わってくるということもあり得るわけですよね。","respondent":"青木都市開発課長","answer":"私が今、ご説明した資料の時点ということで、権利変換計画を申請した時点の資料でご説明申し上げましたので、その書類を都に提出した段階で、一部不備等で同意とみなされないものがあったということで先ほどご説明したものでございまして、その後聞いておりますのは全員同意で。","voiceIndex":43,"id":"exchange-016"},{"speaker":"宮崎委員","kind":"確認","question":"だからちょっとそこのところで、書類の不備で書類がそろっていないということになれば、これはあくまでもこの議案として出してくるのは、ちょっと後先が違うんじゃないのかなと思うし、いろいろ書類がしっかりなっていない、書類がしっかり形になっていなければ、その後どういうふうになったかというのはわかりませんから、それはどういうふうになっているんですかということをお聞きしたい。","respondent":"岩田まちづくり事業部次長","answer":"もちろんいろいろな方がいらっしゃいますので、全員同意ではございません。ただし、今まで品川区が行ってきました再開発事業は、いわゆる督促型なんですが、全員同意のタイプの再開発をやってまいりました。","voiceIndex":45,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"意見","question":"全員合意を前提にやってきたんですね。どうも今回のはそうじゃないということで、書類の不備ということであっても、全員合意じゃないところで申請がいくというのは、これはちょっとやり方によっては無理やり合意を強いているということになりかねないんですよね。これは今回、道路の認可の問題に限らず、再開発そのものについても大問題だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-018"},{"speaker":"井上委員","kind":"意見","question":"第７０号議案のほうなんですけれども、その１とその２は、再開発のエリアになっている部分で、ほかに建物ができてしまうと、ここは通り抜けができない道路になるわけで、その辺の道路の状況なんかが正常にいくのかどうかということが１つと、特別区道の２－４５、４６、４１、１４なんかの再開発によって、私たちはこういう資料がその都度出されていくので。","respondent":"青木都市開発課長","answer":"こうなりますと、面積については、大変申しわけないんですが、今はちょっと細かい数字はございませんけれども、冒頭管理工事課長のほうからご説明がありました廃道する面積、２,０００m2ぐらいでしたか、に対して、今ご説明しましたとおりに。","voiceIndex":48,"id":"exchange-019"},{"speaker":"井上委員","kind":"意見","question":"そういう意味では、先ほど松澤委員もおっしゃったように、地域のこれだけでは見えない部分というのは相当ありまして、いろいろなところでたびたびこういう計画ができてくる中で、まだまだ状況が見えてこないという点と、あと、この道路の付け替えによって、今のようなお話であるならば、資料としてここの計画、この道路だけではない計画があってここの道路の付け替えということの議案だと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-020"},{"speaker":"藤田委員","kind":"質問・要望","question":"ですから、区としてもそれだけ協力をするわけですので、主導的な役割をぜひ担っていただきたい。ガードレールの所在だとか、さらにはデザインだとか、住宅等もできますので、街路灯も普通の街路灯じゃなくて、再開発しているまちにふさわしいような、そういう一つ一つ細かなことをこれからぜひ地元とも話し合いをしていただきたいということを、ぜひ要望しておきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問・要望","question":"質問というよりも、議案に対して道路の付け替えだけであるのでこれで認定しましょうというのは、そもそもこれがどういう影響をその周りのまちづくりがあるかということで言えば、この賛否だけであるものではないと思いますから、そのことが出された上での賛否というのは当然だと思いますけれども、この道路によっていろいろなまちが変わるということであれば、この委員会でその資料があって、皆さん。","respondent":"岩田まちづくり事業部次長","answer":"これは都決定ですけれども、その段階で当然品川区の都市計画審議会、あるいは品川区の建設委員会等にもこの都市計画の中身について十分ご説明をし、議論をしていただきました。","voiceIndex":52,"id":"exchange-022"},{"speaker":"井上委員","kind":"提案","question":"それともう１点、私は神楽坂のほうに視察に行きましたけれども、同じようにマンションを建てるときに、区が住民の反対を押し切って区道を廃止し、新たに認定をしたことで大きなマンションが建つというふうになっていたところで、今でもしこりが残っているというまちの実態も見学してきましたけれども、そういう意味で、住民の方たちのそういった、今後このまちに住まわれる方もそうですし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-023"},{"speaker":"中塚委員","kind":"意見","question":"今の議論でいきますと、近隣住民の合意の件も当然ですけれども、今まで全員合意を少なくとも前提にしていた区の姿勢が、大きく後退をしている。少数の意見が多数によって押し切られちゃう。それが直接自分の生命、財産にかかわる問題であるがために、こうしたことというのは非常に問題だし、あってはならないと思います。第７０号議案は反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-024"}]},{"id":"topic-02","title":"ありがとうございます。賛成多数です。よって本案は原案のとおり可決決定いたしました。 次に、２の第７１号議案、東五反田二丁目地内特別区道路線の廃止","agenda":"ありがとうございます。賛成多数です。よって本案は原案のとおり可決決定いたしました。 次に、２の第７１号議案、東五反田二丁目地内特別区道路線の廃止","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"簡単なことなんですけれども、耐震診断をする場合は、まず建物を診断されますけれども、同時に周りにあるもの、塀とか建物以外のところの診断というのは進んでいるのかなというすごい不安があるんです。建物のことはよく話題になるんですけれども、診断の際に、いわゆる万年塀が残っている、倒れやすい、この現状を教えてください。","respondent":"齋藤住宅課長","answer":"区営住宅につきましては万年塀はあります。区内には、築年数が古いものがありますけれども、その間に６.０から７.０程度の地震が来ても、ちょっと壊れても崩れない、耐震の補修等を行います。","voiceIndex":65,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"今、万年塀の話ですけれども、万年塀の診断は進んでいるんですか。それとも万年塀というのは、関東大震災級の地震ではもう危ないよということで、今、変えましょうという話だと思っていたんですけれども、速やかに変えていく必要があるのではないかなと思うんですけれども、もう一度お願いします。","respondent":"齋藤住宅課長、岩田まちづくり事業部次長","answer":"ただ、区営住宅につきましては、近隣との境で万年塀で仕切ってございませんので、ただ幾つかは直しておりますけれども、区営住宅に関して言えば、緊急に改修するような万年塀というのはありません。万年塀については特に今まであれはないんですけれども、通常、地震のときには万年塀がバタンと倒れた例というのは私は聞いたことがなくて、柱が揺れたときに段違いになって、外れてばたばたと下に板が落ちるということなので。","voiceIndex":67,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後という話ですけれども、いつ来るかわからない地震の対策、繰り返すまでもなく強調されている話ですので、ぜひ速やかに進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"今のブロック塀のことなんですけれども、ちょっとずれるかもしれないんですけれども、１.４ｍ以上はもうだめだということで、でも現在、残っている調査とか、そこに改修するときは改修してくださいとかという、そういう取り組みについての状況というのはどうなっているんでしょうか。","respondent":"片田建築課長","answer":"建築基準法の中で定期点検というのがありまして、区営施設についても、今後やっていきましょうという方向で法が改正されてありますから、そういう機会をとらえて、不ぐあいとか、そういうものを調べまして、必要な改修については、当然行ってまいります。","voiceIndex":71,"id":"exchange-028"},{"speaker":"井上委員","kind":"質問・要望","question":"公共施設で生け垣やフェンスというのは当然だと思うんですけれども、現在そういうところのブロック塀がどのくらい品川区に存在しているのかという調査が、防災のほうの点でいっても大変重要だと思うので、そういったところは進めていっていただきたいなと思うんですけど、あるいはみどりを増やしていこうとか、Ｔ字路であればブロック塀だと見えなくて、この間。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-029"},{"speaker":"藤田委員","kind":"質問・要望","question":"私も確認していません。長年の周辺住民の希望なんです。ですからこの際、ここもぜひ神経を使っていただきたいなと。あわせてあそこは５階建てですので、高齢者の方が本当に多い住宅なんですね。エレベーターとか、何かいろいろ言われていますので、ぜひそういう診断とあわせて、そういうものを想定しながら、ぜひこの際にやっていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-030"},{"speaker":"本多委員","kind":"質問","question":"補正でこのような形で出てくるというところで、本来の当初予算ではそれぞれ区の施設でいろいろ耐震診断を予定されて実行されてきたんだと思うんですけど、それで小中の耐震診断の終了後にこれに手をつけていくということで、大体その流れが順調なんだろうなと思って、その辺の進みぐあいと、あと今、区営住宅が１３ありますけれども、比較的古い場所の２つですけれども。","respondent":"齋藤住宅課長","answer":"こういった事情もあります。したがって、年度計画で今後やらなくてはいけないという認識ですが、かなり多額の費用がかかりますので、計画的に、１回で全部できればいいですけれども、計画的にやっていきたいと思います。","voiceIndex":75,"id":"exchange-031"}]},{"id":"topic-03","title":"前回に続き建築確認事務","agenda":"前回に続き建築確認事務","exchanges":[{"speaker":"宮崎委員","kind":"確認","question":"耐震偽装は大変な事件だったんですが、今日の説明でもありましたが、いわゆる指定構造計算判定機関、これも同時に問題だと思うんですけれども、今回の問題、最大の問題の背景は、民間に建築確認ができるというところが、やっぱり問題だと思うんですね。建築する側がそこで確認をすると。そういう構造、こちらのほうも大きなの問題だと思うんですけれども、いかがですか。","respondent":"片田建築課長","answer":"ただ区のほうとしては幾つかの専門機関が立上った場合に、どう対応するかということもありますので、基本的には都道府県レベルでの対応について注視しているです。","voiceIndex":82,"id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問","question":"今、計算も検算してといいますが、本当に改善されるのかなと思うんですけれども、もう１つ、この専門機関は、財団法人か何かですか。","respondent":"片田建築課長","answer":"そうすると、財団系以外にも民間の機関についてもいろいろ検討しておかないと、法律の主旨に沿った対応ができなくなると考えています。","voiceIndex":84,"id":"exchange-033"},{"speaker":"宮崎委員","kind":"意見","question":"わかりました。感想になりますけれども、いろいろ耐震偽装の問題からわかったことですが、私はこの検査する機関が、ほんとうに公正中立であり得るのかということが最大の問題としてあると思うんですね。そういう意味でいろいろ民間機関ということもあったんですけれども、結局これが今のああいう事態を引き起こしたわけで、また今度は財団系でも、また同じような理屈ではないかと感じました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"藤田委員のみどりのモデル地域というところがそういう制度があるということで、なかなかそれが使われていないという現状があると思うんですが、その実態と、どういうふうに広げられているのか、それが効果的なものだという答弁だったので、その辺のことをちょっと伺いしたいということ、あと原委員の質問で、１６３号線のところでにぎわい創設助成なんかを使いながらまちづくりを考えていくという中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3860#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":34494,"voices":96}},{"id":"h18-20060925-9","meetingId":"h18-cm09","date":"2006年9月25日","dateIso":"2006-09-25","committee":"文教委員会","time":"午前１０時０３分～午前１０時５８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査を行ないます。１の第６３号議案、平成１８年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"議案審査を行ないます。１の第６３号議案、平成１８年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"前回の文教委員会で報告があった、この新教育システムの委託費の問題なんですが、１から４までのテーマがあって、４の小中一貫教育の問題で説明があったと思うんですが、もう一度、ちょっとそこら辺の内容について、何を、どのような角度で、委託を受けて研究するのかということを教えていただけるとありがたいんですが。","respondent":"吉村小中一貫教育担当課長","answer":"新教育システムの大きな四つの柱ということで、前回、ご説明させていただきました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"２番目に言われた施設一体型の義務教育学校を設置するということですが、この義務教育学校というのは、今までの６・３制のものではなくて、９年間一貫した学校の、法改正をにらんでの義務教育学校という意味合いかどうか、ちょっと教えてもらえませんか。","respondent":"吉村小中一貫教育担当課長","answer":"委員のおっしゃるとおり、９年制ということで、９年を一貫した学校に向けての提言をしていくです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"将来の制度改正を見据えてということを、今度のシステム開発で言っているわけなんですが、そうしますと、品川区で行った小中一貫一体型と、連携型の一貫教育を、基本的には、思いとしては、国の新たな制度として法改正を見通してやるということ、それが最終的に取り入れられるかどうかは国の文部科学省が決めることでしょうけれども、そういうことでよろしいんでしょうか。","respondent":"吉村小中一貫教育担当課長","answer":"今現在、６・３制ということですけれども、これからの義務教育については、６・３制というのも一つの方法であるし、自治体の裁量、その自治体の実態に応じて９年制という学校をつくるということについても、やはり法改正をして認めていただきたいという意味で。","voiceIndex":9,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"意見","question":"補正予算書の３８ページの報償費から委託料までの説明をいただいたけれども、さっきお話された日本の伝統・文化のほうの都の委託費は講師の方々の報償費に使うということだけれども、この予算の中の１,０１５万７,０００円と役務費の２万２,０００円、東京都のそれに対するお金は、この予算書の中のどれに入っているのか。この予算についての分配の方法というか、それをちょっと説明してください。","respondent":"河野指導課長","answer":"日本の伝統・文化理解教育推進事業ですが、委託金額８万８,０００円のうち、講師謝礼が２万６,０００円、それから消耗品等ということで、茶器とかお茶等に６万２,０００円という内訳です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"報償費の１,０００万円というのも、ちょっと説明がほしいんです。その外部評価を、委託して分析してもらうというのは、品川区は何もやらないというふうにとられないんですか。","respondent":"吉村小中一貫教育担当課長","answer":"こういった部分については、東京大学大学院の学生をかなりの人数動員をしてやっていくです。そういった部分での報償費、それから学識経験者から指導していただくための報償費、そういったものを考えております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"あえて聞きますけれども、品川区の教育委員会はどこで、何を仕事するんですか。","respondent":"吉村小中一貫教育担当課長","answer":"ここで教育委員会事務局が全体の検証の方向性を定めていく。そして、その下部組織になります作業部会７課で、やはり教育委員会事務局と、先ほど言いました実施協力機関、学識経験者、大学関係、それから校長会関係といったところと実務レベルでも一緒にやっていくです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"意見","question":"品川区の教育について、こういう仕組みの中で進めていくのがいいのか、どうかというのを検証していく。これは１,６００万円もかけやるのに、ほとんどが外部にお金を出して事業を成り立たせるというのは、僕はちょっと納得いかない選択と思うんですけれども、その辺もう少し説明をください。","respondent":"吉村小中一貫教育担当課長","answer":"できないだけではなくて、教育委員会事務局だけでやるというよりも、ある程度これについては、外部の方からもいろいろなご意見をいただきながら分析をしたいということで、今回、こういうふうに進めているところです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"意見","question":"しつこいようだけれども、委託して、その分析を頼むのはいい、だけれども、その分析結果を、品川区に合っているのか、合っていないのか、あるいは、品川区として改正するというか、ここを伸ばす、ここを削る、取捨選択をしていくのは、あくまでも品川区教育委員会がやるべきで、そこまで人に頼むんだったら、これは何のためにやるのか、国のためにやるんじゃないでしょう。","respondent":"吉村小中一貫教育担当課長","answer":"ですから、最終的には、品川区の小中一貫教育についてどうだということは、当然品川区が考えていくということです。それについては、国も品川区のそういう考えについて応援してくれているということでご理解いただければと思います。","voiceIndex":21,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"お金が少ないから、効果が少ないとは言いたくないけれども、８万８,０００円で、先ほど聞いたら、２万６,０００円で講師を頼んで、消耗品ということだったけれども、具体的に学校名を挙げるのはまだ早いかもわからないけれども、どこの学校でやって、どういうことを、この事業によって得たいと思っているのか、その辺の意図というのか、それを聞かせてください。","respondent":"吉村小中一貫教育担当課長","answer":"教育課程に位置づけた日本の伝統・文化理解教育に関する組織的、計画的な進め方についての研究開発、こちらのほうを主に源氏前小学校で行っておりますが、日本の伝統・文化につきましては、研究受託のほかに、市民科の中でも茶道等を取り入れて。","voiceIndex":23,"id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"だから言っているんです。品川区全校でこれをやっているんでしょ、市民科という新しい教科の中ではっきりこれをうたわれているわけでしょ。それをなぜ、今さらこれを源氏前小学校だけで取り上げてやるのか、じゃあ、ほかの学校の市民科でやるこの授業はどういう位置づけになるわけですか。","respondent":"河野指導課長、若月教育長","answer":"市民科につきましては、今年の４月からということで、この内容については相互にリンクするものですので、市民科は市民科で、もちろん全校で情報交換しながら取り組んでおりますし、また、源氏前小学校は。そうした中で、一つパイロットスクール的な役割を、今回果たしているし、東京都の教育委員会も、そういった意図で、ぜひこれをやってもらえないだろうかと、こういう中から実現したとご理解をいただければと思います。","voiceIndex":25,"id":"exchange-010"},{"speaker":"林（宏）委員","kind":"意見","question":"最後にします。教育長の思っていることは、教育委員会全体に伝わっていないと困る。だって、今、指導課長の話では、検証して、東京都に返すと言っているんですよ。違うでしょ、品川区の教育委員会の市民科の授業に生かすために、今言われたようにパイロット的ということ。それだけは言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-011"},{"speaker":"武内委員","kind":"質問・要望","question":"今の伝統・文化の東京都の委託事業の件ですが、もとが６６３万７,０００円で、今回８万８,０００円の補正となっているんですが、先ほどの茶器だとか、講師料を、今回、補正で新たに組んだというのは、今までお茶のがあまりなかったのが、今回出来たとか、何かそういう事情があれば教えていただきたい。","respondent":"河野指導課長","answer":"この８万８,０００円というのは、あくまでも都からおりてくるお金を、今回の補正に組み込んだです。","voiceIndex":29,"id":"exchange-012"},{"speaker":"武内委員","kind":"質問","question":"平成１７年度から委託されたということなんですが、平成１７年度の、都から委託されて源氏前小学校でやった同じ事業の結果というか、効果というか、子どもたちとか、またお母さんたちが、やったことに対してどういう評価をされているかというのは、どういうふうにとらえているんですか。","respondent":"河野指導課長","answer":"昨年度の内容から申し上げますと、今まで茶道等に取り組む機会がなかなかなかった子どもたちにとっては、日本古来から伝わる作法ではありますが、とても斬新なものに映ったようで、非常に印象深かったように聞いております。","voiceIndex":31,"id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"そうすると、今回はあくまで茶道のみという形なんですか。","respondent":"河野指導課長","answer":"茶道が中心ですが、華道も一部に取り入れて実施しております。","voiceIndex":33,"id":"exchange-014"},{"speaker":"築舘委員","kind":"質問","question":"今の東京都の委託事業の続きなんですけれども、茶道の先生なんですが、この先生の選び方というのは、地域の民間の方を選ぶんでしょうけれども、どういう形で選んでいくのかというのが一つ。それから、何年生を対象にして茶道を教えているのかというのが一つ。区の市民科で、茶道を今年からやっているということで、区の予算は幾らついているのかというのが一つ。とりあえず、三つ教えてください。","respondent":"河野指導課長","answer":"茶道についてですが、今、手元に細かい資料がございませんので、具体的なことはちょっと申し上げられませんが、区の予算の６６３万円の中から、茶器であるとか、茶筅であるとか、例えば茶碗ですけれども、現在。","voiceIndex":35,"id":"exchange-015"},{"speaker":"築舘委員","kind":"質問","question":"それぞれの学校が市民科のほうでやっているということなので、茶道も、場所として品川歴史館とか、そういういいところもあるので、生徒たちも、１回ぐらいそういったところに出向いて習うと、また場所も違っていいのではないかと思うんですが、そういった場所はどうなっているんでしょうか。","respondent":"河野指導課長","answer":"これはあくまでも授業の一貫ということでやっておりますので、現在は、学校の中を使っているというのが現状です。今、委員ご指摘のように、区内に茶をやるのに大変ふさわしい場所もありますので、そういうような利用についても、今後検討してまいりたいと思います。","voiceIndex":37,"id":"exchange-016"},{"speaker":"原副委員長","kind":"質問","question":"今の話の続きなんですが、講師の選び方なんだけれども、今、裏千家の話が出ていましたけれども、茶道には表もあればいろいろあるんですけれども、何で裏千家なんですか。","respondent":"吉村小中一貫教育担当課長","answer":"ご指摘のとおり、確かに表と裏とあるわけですけれども、裏千家のほうは、以前から学校茶道ということで、学校教育に茶道を取り入れるということに非常に熱心に取り組んでおりまして、子ども用の教科書であるとか。","voiceIndex":39,"id":"exchange-017"},{"speaker":"原副委員長","kind":"意見","question":"わかるんだけれども、品川区の中には茶道、華道文化協会というのがあって、区長が協会長をやっていたはずなんだけれども、今裏千家になった理由はよくわかったんだけれども、多分、そういう話も出てきちゃうのではないかなと思って、そちらにしても、我々にしても。だから、そういったところも考慮の中に入れる形を広く持ってほしいなと思うんです。","respondent":"吉村小中一貫教育担当課長","answer":"確かに最初は、学校茶道ということと、先方のほうからも申し入れがあったということで、まず初年度ということでしたので、そういう形で始めましたけれども、当然、私どもも裏千家にこだわっているということではございませんので、地域で、品川区の市民科。","voiceIndex":41,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"採決の前に意見表明をしたいんですけれども、よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"},{"speaker":"沢田委員","kind":"提案","question":"反対の点は二つありまして、一つは、小中一貫教育はいろいろな形で全国で試みられていますけれども、品川区が特に義務教育学校に向けた提案を行うと、２で言っていますけれども、法改正までこれを持ち上げるということは、品川区の現実の小中一貫教育、あるいは一体型の一貫校の教育を見た場合に、これは問題があまりにも大きすぎると思います。学びからの逃走、勉強嫌いの子が相当出てくることを懸念します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"さっきも質問のときに言ったんだけれども、品川区の子どもたちのため、品川区らしい教育、そういうものをきちんと踏まえて、言い聞かせて、品川区の教育委員会が動いてくれることを強く要望して、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-021"}]},{"id":"topic-02","title":"品川歴史館特別展","agenda":"品川歴史館特別展","exchanges":[{"speaker":"林（宏）委員","kind":"確認","question":"確認だけさせてください。ごめんなさい、特別展のほうではなくて、工事のほうで、建て直すんじゃないですよね。現状のままで、空調その他を新しくするのか、その辺をもうちょっと詳しく。","respondent":"富田生涯学習課長","answer":"今おっしゃるとおりでございまして、改築ではございませんで、配管と空調がかなり傷んでおりますので、個別の空調を入れたり、あるいはそれに伴いまして、天井と内装に若干手を入れたりということで、あまり目立たない部分での改修工事です。","voiceIndex":58,"id":"exchange-022"}]},{"id":"topic-03","title":"品川区立総合体育館の利用状況","agenda":"品川区立総合体育館の利用状況","exchanges":[{"speaker":"武内委員","kind":"質問","question":"それとも、これは４月から６月なので、時期的に運動とか、そういうもので利用が多いのか、冬になってくると利用が減ってくるのか、その辺の見通し。それから、温水プールなんですけれども、以前一般質問でも、ある議員から出ましたけれども、私もちょっとお聞きしていたんですが、排水のほうがうまくいかないようなことがあったと思うんですが、それは完全に直ったんですか。その２点、お聞きしたいんです。","respondent":"富田生涯学習課長","answer":"夏休みに入る前にということで、７月上旬に９日程度臨時休館させていただいて、改修工事を終えたものです。","voiceIndex":65,"id":"exchange-023"},{"speaker":"林（宏）委員","kind":"意見","question":"今の話もそうなんだけれども、利用数、稼働率というか、こういうのをこうやってしてくれるのは大変ありがたいし、また、利用者数、利用率が増えてきているというのはご努力だろうと思うんですけれども、報告をされるときに、利用状況ということなんだから、こういうお客さんから不満があるとか、あるいは褒められることもあるとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4582#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":15853,"voices":75}},{"id":"h18-20060925-5","meetingId":"h18-cm09","date":"2006年9月25日","dateIso":"2006-09-25","committee":"総務委員会","time":"午前１０時０３分～午後０時２０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"全部読めたわけではないので、なかなか質問がわからないところもあるんですけれども、一つお聞きしたいのは、第２章、本文ですと４ページになりますけれども、基本的な人権を尊重していくということで書かれているんですけれども、この中に、これは区民ということなんでしょうけれども、「国民の自由と権利に制限が加えられるときであっても、その制限は必要最小限のものに限り」とあるんですけれども。","respondent":"桑村危機管理室長","answer":"基本方針に掲げる人権尊重というのが挙げられてありますので、この場合、自由と権利に制限が加えられる、これは考えられるとすれば警戒区域みたいなものを設定した場合、その中に入らないでくれというようなもので、これは区でやる場合もありますし。","voiceIndex":5,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"そのときに、その権利制限そのものが、憲法上、あるいは法律上、超えたものになっているというような判断をするというのは、その時点で、一体だれになるんでしょうかね。この協議会の構成委員の皆さんは、例えば弁護士だとか、そういった方はなるようですけれども、その辺のことをお聞きしたい。","respondent":"桑村危機管理室長","answer":"うちの区のほうの対応する部署をしっかり決めなさいと聞いておりますので、基本的に、訴訟の関係になれば、私どもの総務課文書係の対応になろうかと思いますが、そういった部署も決めていることになってあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"もう１点のほうなんですけれども、罰則規定として、保護計画そのものにはないんですけれども、関連をする法体系の中には、自衛隊法にしても何にしても、それに準ずるようなものというのは常にあるわけですから、要請に対して断ればどういう状況になるかというのは、単にこの計画だけではなく、あらゆる法律との関係でもって見ていく必要があるでしょうし、区民に周知をするという場合に。","respondent":"桑村危機管理室長","answer":"基本的に、こういう計画をつくって、その中の実施について周知するというのは、区の役割でもあるでしょうし、また、ここにも載っていますけれども、区民の方へどういうことが必要なのかは、今後、マニュアル等もつくって周知する必要があるだろうと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"現実的に、自然災害の場合は、区に指導権があって、有事が発令されれば、都知事、基本的には国になるんでしょうけれども、そういう違いが出てきますけれども、ちょっとその辺も含めて、相違点がどこにあるのかということを、ちょっと教えてください。","respondent":"桑村危機管理室長","answer":"そういう意味では、想定している事態というんでしょうか、国民保護計画で想定しているのは、先ほど、８類型と申しましたが、ここだけが予定されているような事態ですとか、例えばテロなんかもそうですけれども、非常に近いところだけというんですか。","voiceIndex":11,"id":"exchange-004"},{"speaker":"塚本委員","kind":"質問","question":"現実にそういう事態に対応するある種の力というものは、軍隊であり、警察署であり、消防署でありということが大きいわけですから、この中で責務を明確にしていくということは、各編で文章化されているんですけれども、これはほんとうに調整がついているのかなという気がします。原案の分厚いほうの４ページで、下の７、指定協力機関および指定地方公共機関の自主性の尊重ということは、どういうことなのか。","respondent":"桑村危機管理室長","answer":"最初のほうですが、区が責務といったのは、関係機関との相互的な区内の調整をするということで、実質的な武力攻撃があったときの対応というのは、警察署ですとか、消防署に頼る機会が多いと思います。","voiceIndex":13,"id":"exchange-005"},{"speaker":"塚本委員","kind":"提案","question":"前回、私は総務委員長をやっておりまして、その元の議論をやったので、ある程度承知はしておるんですけれども、これができてきた背景ということ、改めて提案された背景、国が求めてきたものを教えていただきたい。例えば、この間結審したサリン事件のようなもの、あれはここに照らした場合に、どのような扱いになってくるのか、発動されるのかどうかということ。その２点を教えてほしいんですけれども。","respondent":"桑村危機管理室長","answer":"二つ目の、サリン等というようなお話でございましたけれども、どれが事態対処に当たるか、あるいは、対策本部を設置するかというのは、基本的に国が考えることですけれども、私どもがつくっている原案につきましては。","voiceIndex":15,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"もう１点、概要版の最後のページの、協議会の構成を見ながら質問しますけれども、会議体としては人数が多くて、議論百出というような会議体ではないといいますか、連絡を主にすることになってしまうだろうということが想像できるわけですけれども、このメンバーは何種類かに、民間人と官の人と分かれますし、また、先ほど言ったように、消防署、警察署といったある種の実の力を持っている人たち。","respondent":"桑村危機管理室長","answer":"そういう意味では、協議会は非常に多くの構成ですので、先ほども言いましたように、この場で審議をするのはなかなか難しいので、その下のレベルというんでしょうか、少し落として会議を開こうかなという進め方になってあります。","voiceIndex":17,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"日本人は、水と安全はただだという感覚が抜きがたくありますけれども、そういう国柄のため、北朝鮮の不審船を銃撃して追ったというあたりから少し意識が変わってきたとは思いますけれども、我々の中にまだまだそういうところがありますので、しようがなしに餅の絵をかいてみたというような感じがないわけではありませんので、ぜひ緊張感を持って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"何かうまいぐあいに、国から一斉に発令できないのかなということもあるんですけれども、その辺をお聞きしたい。それから、例えばこういう保護法が発令されますと、住民は、そういうふうに行動しなきゃいけないとか、一定の法的なものに縛られるということがあるんですかね。","respondent":"桑村危機管理室長","answer":"国のほうは一斉伝達の仕組みというのは検討しておりまして、全区市町村の防災無線を使って一斉伝達ができる仕組みを検討しているようです。ただ、これを受けるか、どうかというのは区の判断になるというのは出てくるものと思います。","voiceIndex":20,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"最後に１点だけ。やたら救援と言っても、やっぱり人材には限りがありますし、いつ、何時、どこで、どう起きるかわからない状態ですから、地域センター等ありますけれども、逆に可能ならば各町会にお願いして、１カ所ずつ物資を保管する、場所は区で提供するにしても、医薬品、それから必需品の物資等を確保するような体制をとっておいたほうがよりいいような気がするんですね。","respondent":"桑村危機管理室長","answer":"物資等の備蓄ということになろうかと思いますけれども、地域防災計画の基本的な考え方を使うということでので、何日間かはそれなりの対応ができるような備蓄をしていますし、またほかの、例えばスーパーですとか、米穀協同組合ですとか、そういうところへもお願いして。","voiceIndex":22,"id":"exchange-010"},{"speaker":"菊地委員","kind":"質問・要望","question":"だから、その辺も、確認すべき事項というのは一体どういう内容なのかということについて、教えていただきたいんです。","respondent":"桑村危機管理室長","answer":"いわゆる自衛隊が武力攻撃の排除ということで、例えば、武力侵攻はあまり可能性はないと言っていますけれども、何かそういったことがあったときに、行動を起こすときに、自衛隊の方々がこの幹線道路を使うというような考え方になろうかと思うんです。","voiceIndex":24,"id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"ということは、この計画そのものに、今、危機管理室長が話をされた一つの想定でしょうけれども、自衛隊と、その辺の想定をされる事項について書き入れていくということはないんですか、この計画そのものに。","respondent":"桑村危機管理室長","answer":"計画案そのものはこういう形になろうかと思います。私どもとしては、国民保護の計画をつくっているわけですので、何か自衛隊の行動と国民保護上の行動がぶつかったときに、どう調整するかということを、何らのか形で書く必要があるので、ここに入れさせていただいたです。","voiceIndex":26,"id":"exchange-012"},{"speaker":"山村委員","kind":"質問・要望","question":"国の事態認定前に区が何ができるのかとか、どこまでできるのかというのを、改めて教えていただきたい。それから、大体、大規模集客施設とかを見てみると、僕が全部読みきれないのかもしれないんですけれども、大学関係とかがあまり出てこないので、そういう大学施設、文教関係とはどういう取り組み、取り扱いになっているかというのを教えていただきたいと思います。","respondent":"桑村危機管理室長","answer":"それからもう一つは、大学等が抜けているという理由ですけれども、ここで挙げさせていただいたのは、例と書いてありますけれども、不特定多数の方が来るというのが、まず基本的な前提でございまして、事務所ビルですとか、大学とか。","voiceIndex":28,"id":"exchange-013"},{"speaker":"山村委員","kind":"質問","question":"国からの事態認定を受ける前は、そういうことはできるのかどうか、明らかなテロというのをだれが判断するかということと、そういう対応が、国および都からの事態認定が来る前に行動を起こすことができるのかどうかというのを教えてください。","respondent":"桑村危機管理室長","answer":"ただ、実質的に事態認定が起こる、あるいは事態認定に準じたような形で何か、例えば大規模な火災が起こっているというようなことについて、警察署も、消防署も、当然私どもも動くわけですので、その中でそれに準じたものについても対応しようというのが、今回の計画です。","voiceIndex":30,"id":"exchange-014"},{"speaker":"山村委員","kind":"質問","question":"基本的、品川区国民保護計画というものができて、区内でシミュレーションにおける訓練というのをやられるんだと思うんですけれども、そういうのは、どのぐらいやられるつもりなのか、教えてください。","respondent":"桑村危機管理室長","answer":"訓練の話ですが、どういう形でやるか、これはちょっとまだ検討中なものですが、先ほど、警察署、消防署の話もありましたけれども、そういった関係機関とうまく連携しなければ、いい訓練にならないだろうと思っています。ですので、まず一つはそことの連携をどうするか。","voiceIndex":32,"id":"exchange-015"},{"speaker":"山村委員","kind":"意見","question":"やっぱり、我々はテロなんて起こらないと思っているわけで、アメリカはたしか、３、４年で１,０００パターンの訓練をやっているわけですよ、地方自治体が。やらないでしょ、そんな。本気でテロとかいう危険性が生じてきたときに、どう訓練するのかというようなことは考えておいたほうがいいだろうと思います。ただ、よりよい、これを生かす体制づくりはいろいろ知恵を出してやっていただければとは思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"一つだけちょっと。資料の一番後の質問１０のところで、企業集積などによって経済波及効果云々と書かれていますね、再生目的というか、今後の効果として。ここで、改めて企業集積云々と、具体的なものって、総務課長に聞かれても困るかもしれないけれども、何が出されているのか、どうか。","respondent":"桑村総務課長","answer":"そういう意味では、臨海副都心によって企業集積が行われて、こういう効果があったというものを、東京都としては考えているというか、見解を持っているということだろうと思います。","voiceIndex":40,"id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"立場上、質問ではなくて、補足の説明もということ、また、議長会で二度しっかり議論をしております。定款に当たるものですけれども、それから言うと、臨時の総会を開いて出資を決めるべきではないかという指摘がなされておりまして、それは今後、改善するという話になっています。せっかくですから、質問をちょっと言いますけれども、合併をするんだということで、何のために合併するのかということ。","respondent":"桑村総務課長","answer":"これまで３社で、こういう形の融通をきかせてなるべく経営や何かを省力化して動かすことが有意義だと進めてきたんだろうと思うんですけれども、今回、それでもなかなかうまくいかないということなので、何とか３社をまとめて民事再生をかけて、逆に。","voiceIndex":42,"id":"exchange-018"},{"speaker":"塚本委員","kind":"質問・要望","question":"他の２社の経営状況というのは、そこも同じように負債を抱えているということは考えられないのかということと、それから、経営の方針として、持っているものを売却して幾らかでも出資者、あるいは債権者にお返しするという考え方もあろうかと思うんですが、その議論はどの程度あって、どういう説明をなさっているのか。当事者でないからわからないでしょうけれども、わかる範囲で教えていただきたい。","respondent":"桑村総務課長","answer":"新聞に載った資料ですけれども、東京都が、臨海三セクの民事再生法の開始の申立てということで、そこで経営状況が出ておりました。東京臨海副都心建設ですけれども、営業利益は２５億円、経常利益は１１億円、平成１７年度ですけれども、決算見込みです。","voiceIndex":44,"id":"exchange-019"},{"speaker":"塚本委員","kind":"意見","question":"後のほうは仄聞の話ですけれども、これから地価が上がるから、もう少し我慢していけば、借金を踏み倒す、こういう言い方をしてはいかんか、持ちこたえるのではないかというような話も聞こえてくるということだけ言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-020"},{"speaker":"山路委員","kind":"質問・要望","question":"９ページの質問１０のところに、再生後の２３区民および２３区にとっての効果、還元力についてということで、2)で、「２３区共通の財産になると確信しております」と書いてありますが、品川区として、今まで出してこられた分担金、プラスマイナスといいますか、今後どういう出資か何かが必要なのかどうか、その辺についてちょっと、わかる範囲で聞かせていただきたい。","respondent":"桑村総務課長","answer":"臨海副都心そのものの何らかの出資ということになれば、例えばりんかい線等についても、区内の対応があったです。","voiceIndex":47,"id":"exchange-021"}]},{"id":"topic-02","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"山村委員","kind":"質問","question":"降任、降格制度の検討となっているんですけれども、免職というわけではないじゃない、そういうのも人材育成の中に入るのかなと。酒気帯び運転で捕まった場合なんか、ああいうものをもっと明確化していくべきだと思うんですけれども、それはこの人材育成などのところでは絡めていかないんですか。","respondent":"榎本人事課長","answer":"関連はしますけれども、あくまでも降任、降格というのは、職務能率が落ちた場合の制度ということで、非違行為によるものについては懲戒処分ということで、別の指針を検討して、その中できちんとやるようにしていきたいと考えています。","voiceIndex":60,"id":"exchange-022"},{"speaker":"山村委員","kind":"意見","question":"行政のプロというのは、プロフェッショナルという意味をちゃんと考えると、区長以外いないと思うので、行政のプロというのを使われると、ちょっと僕は嫌だとと思う時がある。辞めさせられない人たちがプロというのはおかしいなと、僕は思う。結局は、行政のプロというのは区長以外いないはずなんです。公務員はプロじゃないと、僕は思っていますということだけを述べておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-023"},{"speaker":"山路委員","kind":"質問","question":"前回、ちょっと違う角度だったので、人材育成という基本方針案に沿ってつくられているので、これはこれでいいと思うんです。一人の人間の素材をどう引き出していくか、これが人材になってくるわけですよね。心だって、一つをとらえたら３,０００ぐらいあるというわけですから、いろいろな能力があると思うんです。その中で評価していくわけですから。コメントがあったら、お願いします。","respondent":"榎本人事課長","answer":"後段のアイデア募集等のことにつきましては、また検討させていただきたいと思います。","voiceIndex":63,"id":"exchange-024"},{"speaker":"山路委員","kind":"質問・要望","question":"もう１点、部長の表彰とかなんですけれども、社内の表彰はいいんですけれども、区民サービス、区民側から見たご意見等とか、区民に非常に納得性のある窓口とか、いや、ここは冷たいとか、区民評価もあると思うんです。その辺も加味していただければ、もちろん部長表彰だから入っているとは思うんですけれども、それを再度、加えていただきたいと思います。","respondent":"榎本人事課長","answer":"区民の視点という部分でいきますと、やはり区民の声等で、窓口対応の場合にお礼状が来てあります。そういうものを含めて、それぞれ事業部長や区の表彰等に取り入れていきたいと考えてます。","voiceIndex":65,"id":"exchange-025"},{"speaker":"塚本委員","kind":"質問","question":"１０年単位で、新入社員の特徴みたいなものを教えていただいて、私が思っているようなことがあっているのか、いないのか、またもっと詳しくこういう特徴があるとか、３０年前はこんな職員だったとか、どうやら４０年前の人もいるみたいなので、その辺を教えていただければと思います。","respondent":"榎本人事課長","answer":"その前につきましては、競争とかいろいろないい面、悪い面等ありますけれども、そこまで画一的でない職員というのが中にはいて、そういう職員もきちんと組織の中に根を張りながら仕事をしてきたということがあると思うんですけれども、どちらかというと、今の職員はルールの中。","voiceIndex":67,"id":"exchange-026"},{"speaker":"塚本委員","kind":"質問","question":"前にも、私、指摘しましたけれども、一桁採用の時代が１０年近く続いて、私、陥没の世代と自分で名前をつけましたけれども、今そのことのお話があったように、指導する相手がいなくなっちゃったということの問題というのはあると思うんです。そういう悩みについて、率直なお話を伺いたい。","respondent":"榎本人事課長、本間総務部長","answer":"特に降任、降格につきましては、今までもやってはいるんですけれども、本人同意なりが必要な制度ですので、本人の意に反した形で、処分という形で具体的なものをやってきたわけではありませんので、今回は、育てる部分。ただ、今、品川区はそれで手をこまねいているだけではなくて、今言いました、今の制度の中でも、きちんと対応すべきところは対応しようということで、いろいろ問題ある職員等については、各所管と人事当局が連絡を取り合って。","voiceIndex":69,"id":"exchange-027"},{"speaker":"塚本委員","kind":"質問","question":"本来的に、民間人と比べると守られた環境の中で、それから、割合定型的な仕事をなさってきた方たちですから、いわゆるタフネスということとはちょっと遠い人たちですから、民間と競争しなさいよとか、あるいはサービス面に徹しなさいよというようなことを言われていることに対して戸惑いがあるのは当然だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-028"},{"speaker":"菊地委員","kind":"質問","question":"いつも、私はわからなくなるんですけれども、先ほど、人事課長のお話で、成果実績主義を取り入れてというお話がありましたよね。そのときの成果とか、実績の判断するのに、この間もちょっと似たようなことをお聞きしたんですけれども、その判断の基準そのものがどこにあるのかというところを、お聞かせ願いたいと思います。","respondent":"榎本人事課長","answer":"判断の基準ですけれども、やはり、きちんと注意すべき点が注意できるのかどうか、それから、注意しなきゃいけないタイミングで注意しているかどうかとか、そういうものは具体的に必要だと思うので、主任なり、係長なり、それぞれのポストに応じて。","voiceIndex":73,"id":"exchange-029"},{"speaker":"菊地委員","kind":"意見","question":"別に箇条書き的に基準があってという考え方ではないんですよね。ちょっとそこをもう少しお願いします。","respondent":"榎本人事課長","answer":"その部分につきましては、急激な単年度の措置ということではなく、少なくとも３年、４年、長ければ１０年程度のきちんと指導育成記録をした形での処分をやっていくものになろうかと考えています。","voiceIndex":77,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1730#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":45959,"voices":84}},{"id":"h18-20060926-6","meetingId":"h18-cm09","date":"2006年9月26日","dateIso":"2006-09-26","committee":"区民委員会","time":"午前１０時０３分～午前１１時３５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の「専決処分について（報告第２１号）」","agenda":"の「専決処分について（報告第２１号）」","exchanges":[{"speaker":"南委員","kind":"質問","question":"やむを得ないというか、不注意の事故なんですけれども、ちょっと事故発生の時間が午後５時５０分ということで、勤務時間外なので、必要な仕事上のあれだったんだと思うんですけれども、どんな内容だったのか教えていただければと思います。","respondent":"田中環境課長","answer":"この時期、「涼しさ回復プロジェクト」で、測定機器を第四日野小学校に設置するのを職員のほうでやっておりまして、時間が過ぎたわけですが、それを終わって、設置資材等を車に収納する際に駐車して、路肩にとめて、そこの車に運び込もうとしたわけですが。","voiceIndex":22,"id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"一般的なこの種の事故の場合の示談成立というものは２種類あって、完全に民民で話をしてやる場合、一応警察官立ち会いして、そういう事故処理をした上でやる場合とあるんですけれども、この場合、皆さん、警察官立ち会いがきちんとなされていたのかどうかということだけ教えてください。というのは、場合によっては、とまっていること自体問題だったのかもしれないというのもなきにしもあらずですから。","respondent":"田中環境課長","answer":"接触事故がありましたら、すぐに警察署のほうに連絡しまして、事故の現場の確認をしていただきました。それに基づきまして、保険会社に対応をお願いしたという形になっております。","voiceIndex":24,"id":"exchange-002"},{"speaker":"本田委員","kind":"質問・要望","question":"防ぐためにぶつかったというようなことがあるわけですけれども、十分その辺は安全対策といいますか、ハンドルを持つ場合にも、徹底といいますか、そういうことが今強く求められているという、これ自身大事だと思うんですが、毎回こういう報告を受けるわけですし、今回たまたま軽微な事故だったからよかったとは思うんですけれども、そういう点についてはどういう徹底をされているのか。","respondent":"島袋品川区清掃事務所長","answer":"そのほかにも、警察署の安全講習会を受けるとか、あと班長会議とか、そういうものです。特に飲酒運転については、毎週１回ずつ、技能長のほうから注意していると、そういう状況です。","voiceIndex":31,"id":"exchange-003"},{"speaker":"本田委員","kind":"質問・要望","question":"私も長年、車関係の会社に働いていたことがありますけれども、特に飲酒、過失というか故意になっちゃうわけだから、よもや深酒をして、早朝から酒を残して事故を起こすなんていうようなことが絶対あってはならないと思いますし、特に飲酒運転については、特段の徹底を図って、起こすことのないようにやっていただきたいと思います。要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-004"}]},{"id":"topic-02","title":"で、「品川区青少年対策地区委員会発足５０周年記念事業について」","agenda":"で、「品川区青少年対策地区委員会発足５０周年記念事業について」","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"場所なんですけれども、なぜ西大井広場公園なのかということで、できれば、周年行事であれば、より庁舎に近い、本来であれば中央公園のグラウンドを使ったほうが僕はいいと思うんですけれども、そこら辺の考えをどういうことでなのか聞かせていただきたいと思います。","respondent":"田村地域活動課長","answer":"ただ、あそこは、やはり中にグラウンドがあったり、全体の意向とすれば、実行委員会とすれば、何か子ども中心のイベントなので、雨天でもできるステージをつくりたいということと、あと、それを取り囲むように露天がかなりの数並びますので、それを考えると、全体的なスペース。","voiceIndex":38,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"歴史が５０年もあるということを改めて承知したんですけれども、本当に町の中では、地区委員の皆さん、本当に日常的な活動で苦労されていますので、そういう意味でも、ぜひ楽しみにしておきたいと思っているんですけれども、子どものイベント事業の関係なんですけれども、青少年ですから、ある程度大きい一定程度の学童以上の子どもさんが対象なんだろうと思うんですが、こういうイベントを組むに当たって。","respondent":"田村地域活動課長","answer":"それと、後地小学校のソーラン踊りとか、やはり子どもの意見も、地区委員会ですから、お子さんとの接触を実現していくということで、子どもが楽しんでくれないと来る価値がないというのがあるので、その辺は大人も、地域ごとにその辺の意見も。","voiceIndex":40,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱり、いろいろな子どもの参加というのを、本当に大事にした、すごくいろいろな部署で設けていただきたいと思っているんですけれども、今回は子ども中心の場面もあるということで、本当に意味があって、大いに期待していきたいと思っているんですけれども、子どもの発想だとか、子どもの企画、子ども同士が意見交換をすることによって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-007"},{"speaker":"堺委員","kind":"確認","question":"今、地域活動課長さんからご説明いただいたので、例えば、中央ステージでいろいろな学校、いろいろな児童センターにかかわらずということですが、確認なんですけれども、青少年対策地区委員会と、それから児童保健事業部かな。そういうところとのかかわりはないんですか。私、区民としては、何らかの形で、具体的にはちょっとアイデアが浮かびませんが。","respondent":"田村地域活動課長","answer":"そういう方も約２００名ほど西大井広場公園で、要するに所管とすると、生涯学習課、教育委員会のセクションですが、その方もお呼びしようと。","voiceIndex":43,"id":"exchange-008"},{"speaker":"堺委員","kind":"確認","question":"それが地域の中心として、地域内にある児童センターも含めた形、あるいは児童センターも積極的に地域行事にかかわっていくという相互連携のもとでの、いわゆる地域力、そして児童の育成については、地域が主体となっていくという、そういうとらえ方でいきますと、積極的にかかわっていただいたほうがいいかという感じがしますので、確認までにお尋ねしているんですが、これからもひとつ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-009"}]},{"id":"topic-03","title":"品川区年末対策特別事業資金２００６の実施について","agenda":"品川区年末対策特別事業資金２００６の実施について","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"資料の９番目、融資あっ旋と実行なんですけれども、２５件実行されなかったということなんですが、実行されなかった主な理由というのはどういうようなものがあって実行されなかったのかを伺いたいということと、そういう融資が実行されなかった部分で、どこかほかに融資を頼まなければいけない、先ほどのグレーゾーンではないんですけれども、そこへ流れてしまう恐れがあるんですけれども。","respondent":"金子産業振興課長","answer":"不実行が２５件、その内訳等のお尋ねですけれども、２５件のうち、本人が辞退されたのが１２件、それから区の他の制度融資に切りかえられた方が４件、それから保証協会否決が９件ということで、まず本人辞退の１２件ですけれども、これは融資の必要がなくなった。","voiceIndex":54,"id":"exchange-010"},{"speaker":"大沢委員","kind":"意見","question":"９件の部分は、中小零細の企業努力というか、経営体質を改めなければいけないとは思うんですけれども、否決された場合に、やはり事業を行う上で運転資金など入り用であるから申し込んだんですけれども、そこが否決されちゃった場合のセーフティーネットというか、中小企業診断士の方に相談をするのもいいんですけれども。","respondent":"金子産業振興課長","answer":"金融機関が融資をして、返済の見込みが立っている方についてのみ保証協会も保証するわけであり、また金融機関のほうも融資をするわけでありますから、その部分について、仮に返済の見込みがないと認定されたものについては、改めて融資をするということは難しいことだと思います。","voiceIndex":56,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"今のところは私も伺いたかったところだから、伺ってよくわかったんですけれども、そのほかに先ほど、なかなかこの不況の中で、不況が脱出できていないんだという、そういう説明が冒頭あったんですけれども、改めて区内の、いわゆる経営力が磐石でない、そういう方々の経営状況というか、倒産も含めて、どのような景況状況になっているのか、数字的なところを教えていただければと思います。","respondent":"金子産業振興課長","answer":"もう少し詳しくご説明申し上げますと、昨年の８月以降、国全体が景気回復の基調にあるというところから、やはり区内の中小企業においても、先ほどちょっと申し上げましたけれども、依然としてマイナスではあるけれども。","voiceIndex":61,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"例えば、営業も閉ざしてしまわざるを得ない、あるいは倒産だとか廃業だとか、そういうことも含めて数字がわかれば、わかる範囲でいいんですけれども、教えてください。","respondent":"金子産業振興課長","answer":"東京都全体で見ても、たまに大きなところがあると数字が動いてしまうんですが、全体の傾向としては、倒産の状況については減少しているというところがあります。区内企業の動向としては、以上です。","voiceIndex":63,"id":"exchange-013"},{"speaker":"南委員","kind":"確認","question":"確認なんですけれども、倒産が減少しているとおっしゃったんですが、倒産はあるにはあるけれども、数として縮小している方向だという、そういうことでいいんですか。","respondent":"金子産業振興課長","answer":"今、委員がご指摘のとおり、倒産については、全くなくなったというわけではありません。ちょっとうろ覚えで恐縮ですけれども、区内においても、本年で大体１０件程度あったと思います。そういう意味では、今までの数字よりは少なくなっているという現状です。","voiceIndex":65,"id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"もう１つは、実は、さっき２５件の融資不実行のところがあったというんですけれども、最近ちょっと聞いた話で、区のほうでそういう制度はやっていただいているけれども、その方が努力をしても、こういったいろいろな状況があって、なかなか融資が実行されていないという、そういう経験をされた方なんだろうと思うんですけれども、なかなか厳しい状況だということを、私も直接伺ったことがあるんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-015"},{"speaker":"堺委員","kind":"質問・要望","question":"十分足りているということのようなんですね。そのことによって品川区そのものが活性化する。それで、参考までに、このまま本人負担が０.４％ですから、それ以外の部分は区がご負担いただいているわけですけれども、その辺の、今までの累積の、区が負担している金額というのは把握されていると思いますけれども、大体どの程度の金額になるということですか。","respondent":"金子産業振興課長","answer":"今までの累積の利子補給の数字ということなんですけれども、ちょっと似て非なる数字なんですが、まずはこの年末対策特別事業資金については、どの程度見込んでいるかという、ちょっと違う数字で申しわけないんですけれども、先ほど申し上げたとおり。","voiceIndex":71,"id":"exchange-016"},{"speaker":"堺委員","kind":"質問・要望","question":"これ以上増やしていいかどうかという論議になってしまうのかもしれませんが、それが増えるということになると、本人負担金利が下がる、本人負担金利が０.４％ですから、それが仮に０.２％ぐらいにしていただくと、あと２％は区の増加になっているので、それがいいとか悪いとかの問題は難しいから、あまりはっきり申し上げにくいんですけれども、要するに中小企業対策、中小企業振興策という面でも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-017"}]},{"id":"topic-04","title":"の廃プラスチック分別変更モデル事業の速報値","agenda":"の廃プラスチック分別変更モデル事業の速報値","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"その辺のことをもう少し詳しく教えていただきたいのと、あと可燃ごみと不燃ごみと相殺して、そんなに１日１００ｋｇ程度ぐらい減少しているというお話で、数字的にも減った分増えて、増えた分が減っているという関係なんだろうと思うんですけれども、そういうことで、資源の混入率が減っているということの説明だったんですが、廃プラの収集に当たって、例えば人だとか車だとか。","respondent":"中山資源循環推進課長","answer":"先ほどのアンケート調査ですけれども、時期は１０月下旬を予定しております。資料にもありますけれども、約１,０００世帯を対象にアンケート調査を行い、分別変更に関する影響であるとか、意識であるとかをお聞きしようと考えております。","voiceIndex":78,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"今の最後のところは、焼却をしたときのデータがこれから出るというお話なんですけれども、そのときに区民委員会にも報告していただいて、ぜひ紹介していただきたいということを改めてお願いしておきたいのと、それから、こういうモデル実施をして、アンケートは当該地域でやるということはわかったんですけれども、改めてモデル実施をした後に、こんな実態になったとか、こういう問題点があれば。","respondent":"中山資源循環推進課長","answer":"２３区の中でも、こういうモデルの扱いについても、いろいろと効率的に進めるための参考ということで、ということです。","voiceIndex":80,"id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"どういうふうな状況になるのか、予想されない問題点も含めて、どういうことになるのかということを実験的に行うというのがモデル事業だと考えていますので、ぜひ本格実施の前に、すべての状況を区民に、ホームページにとどまらずに、文書とか口頭だとか、いろいろな機会を通じて全区民の協力をいただかなければいけない問題ですから、範囲を狭めないで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2470#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":25137,"voices":93}},{"id":"h18-20060926-7","meetingId":"h18-cm09","date":"2006年9月26日","dateIso":"2006-09-26","committee":"厚生委員会","time":"午前１０時０４分～午後４時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"請願・陳情審査を議題にします。審査に入ります前に、先日の委員長会で委員会の活性化","agenda":"請願・陳情審査を議題にします。審査に入ります前に、先日の委員長会で委員会の活性化","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私の地域でもシルバーセンターでカラオケをやるのが楽しくて仕方がないという声をよく聞くんですけれども、そういう点では、やっぱりシルバーセンターを充実させていくというのは本当に大事なことだと思うんですけど、理事者に初めにご説明を受けましたので、お聞きしたいんですけど、２１年度に保育園のほうが、都南病院跡地のほうに移るということで、改修するということですが。","respondent":"冨岡高齢事業課長","answer":"それからお風呂の設置が難しいことの理由ですけれども、１つには今申し上げましたように、これは細かに検討しなければいけないんですが、広さの関係がございまして、確かに１階部分が移転するわけですが、セットバックしなければいけない部分がありまして。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが移転した後で、シルバーセンターとしては大きく広がるのではないでしょうか。そして、先ほどゼームス坂の途中に１軒あるという朝日湯ですか、そこのところも、ちょっと地域の方にお伺いしたら、すごく高齢の方で、去年も医者に行かれて、いつまで続けられるかという状況だとお聞きしたんですよね。カラオケは全く防音装置がない中で、シルバーセンターというのはカラオケをやっているんでしょうか。","respondent":"冨岡高齢事業課長","answer":"シルバーセンターは、例えば平塚橋みたいな、新しくできたところは問題ございませんが、古い建物ですので、もともとカラオケがはやるより前にできておりまして、なかなかそれを追加工事で防音にするということは今まで難しい状況がございました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"さっきも言いましたように、私はこのカラオケでいろいろな方とお友達になれて、地域の人の話だと、元気の源になっている感じで、カラオケが楽しくてと、生き生きして話されていたので、やっぱりこれは高齢者にとってカラオケというのは本当に楽しみなんだなというのを改めて思ったんですけど、そういう点では古いので、カラオケは後からということなんですけれども、これに対応する防音設備というのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"木下委員","kind":"質問・要望","question":"すみません、あまり詳しくないので、事実関係だけちょっと教えていただきたいんですが、先ほど２１年度に保育園のほうが都南病院跡地に移転するということで、先ほど何か課長の話だと、建て替えとお話しされたんですけど、後で改修という話も出て、そこら辺、正式に建て替えと改修はかなり違うので、どちらなのかということと、それから例えばそういう形で保育園が移動するということであれば。","respondent":"冨岡高齢事業課長、木下福祉高齢事業部長","answer":"お風呂屋の数ですけれども、４６年当時は把握しておりませんで、１０年ぐらい前に「出会いの湯」が始まりました時点で、あと４軒ぐらいあったと思います。２１年度には今回の本会議でもご答弁申し上げましたように、シルバーセンターを中心にどのような施設にするかということを検討してまいりますということで、お答えをさせていただいたところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"木下委員","kind":"質問・要望","question":"そうしますと、費用対効果の問題ですとかいろいろありますから、例えば費用が安ければ、数年間の利用でも検討に値するだけの価値があるかどうかの判断もできるんですが、費用がちょっとわからないとなると、２１年度という形で、その後の施設をどうするか検討するということであれば、その際に地域の皆様方の要望というのをよくお聞きして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"こういう要望があるけれども、将来、２１年度に改修を予定されていると。その上で、現状が今わかったというところで、理事者のほうにはちょっと確認だけしたいんですけれども、このシルバーセンターに対しての設備改善で、今までどういう要望があったのかということです。今まで、ここにおいて同じようなことが毎年上がってくるとか、要望が強いというのはいかがですか。","respondent":"冨岡高齢事業課長","answer":"すみません、エレベーターの設置については出たと聞いております。今申し上げたように、外のほうにつくれないものですから、それが既存不適格ですので、つくれないという形でお答えしたところです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"シルバーセンターですから、やはりエレベーターのご希望があったんだろうなと思うんですね。お風呂のほうもわかります。それともシルバーセンターの中にご意見箱を置くか、実際いろいろな意見を言える場所があるとか、そういうのがいいかと思います。","respondent":"木下福祉高齢事業部長","answer":"したがって、いわゆる利用者のご意見等は、日々の仕事の中で、私ども、十分把握しているつもりでありますので、その辺を踏まえながら、跡利用については私どものほうでまず基本的に整理をして、ご説明をするというふうに考えております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今、西本委員がこの両方をいつの時期にという、改修ということが出ている段階で、そこのところをはっきりさせるのが必要なんじゃないかということを言われましたけれども、本当にこのところは、ちょうど都南病院の跡地に保育園が移転するということで、改修の時期が２１年度ということが決まっていますので、確かにそういうことだと思うんですね。この請願代表者の方にそこら辺のところは、聞かれていますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-008"},{"speaker":"西本委員","kind":"意見","question":"ただこの中で、主にシルバーセンターの設備を改善してほしいという、その思いをしっかりと受けとめるというのがまず先だろうと思います。これが次期改修のとき、こういうことを考慮してくださいという言い方であれば、はっきりと明確に趣旨がわかるんですけれども、そこまでは入っていないのでありますが、十分に私はその気持ちを踏まえながら、発言させていただいています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから何が何でも今すぐにということではなくて、こういうことの要望があるということを受けとめていただいて、これは時期としては、代表者の方にお聞きしたところでは、改修のときになるということがあるかもしれない。だけれども、こういう地域の方々の要望があるんだということを汲んでいただいて、要望を実現できるようにしてくださいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-010"},{"speaker":"三村委員","kind":"質問・要望","question":"質問というよりは意見なんですけど、今、この中には改修の時期というところで議論があったかと思うんですけれども、当然区民の方には行政的な流れだとか段取りだとか、そこまで把握するというのは難しいと思いますので、実際にシルバーセンターの下にあった保育園の移転の計画もきちんと決まりましたし、それに合わせて、そこの場所があくというのは、この中では決まっていることなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-011"},{"speaker":"三上委員","kind":"質問・要望","question":"１つ、確認させていただきたいのは、先ほど課長の説明の中にありました、公衆浴場との約束というものが、この取り交わした協定書なるものというのは、ずっとさかのぼって現存しているのかどうか。百二、三十から、多いときは百四、五十あった。公衆浴場組合というのは今もありますけれども、その浴場組合が本当に今もそれを守ってくれと言っているのか、それともどうなのか。","respondent":"谷田部健康課長、冨岡高齢事業課長","answer":"これが区内において適正な数かどうかというのは、非常に難しい問題でございまして、当然地域バランス等もございまして、特に荏原地区については、比較的卑近な距離に浴場がある。浴場組合との文章の関係ですが、昭和４８年に敬老会館に対する浴場が要望ということで出ておりまして、それに対して回答している文章で、その中で先ほど申し上げということです。","voiceIndex":22,"id":"exchange-012"},{"speaker":"三上委員","kind":"確認","question":"そうすると、その回答したという文章は現在でも生きているということで、もう一度明確に確認させていただけますか。","respondent":"冨岡高齢事業課長","answer":"現在でも生きていると思います。","voiceIndex":25,"id":"exchange-013"},{"speaker":"三上委員","kind":"質問","question":"ですから、この問題については、そういった点で、一度お話し合いをされていく必要があると、私は思います。ですから、それを改修するという話になってくると、大幅に建物そのもの、構造自体、骨組みを削り取った形でないと、既存不適格の建物をセットバックすることはできないですね。そうすると、この建物というのは昭和３４年に建てられたというわけですから、４７年経年。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それとも今後移転したことを踏まえての話、請願なのかという点も確認をさせていただいたつもりです。というのは、多分、私が連絡をいただいたときは、この文章はできていたんでしょうから、そのことをご存じですかということをお聞きしたときに、ちょっとはっきりつかめなかったんですけど、ご承知だったような感じもしますし、今後のことというのも話はありました。階段の幅が９０センチぐらいかな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-015"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そういった面では区民の皆さんにより利用していただける方向で、区のほうにもお願いしたいという意味では、今の段階でのこの請願の趣旨をどれだけくみとって、地域要求にこたえていくのかなというところを私たちは今、求められているんだと思うんです。お風呂の件なんですけれども、ぜひ浴場組合のほうと話し合いをしていただきたいと思います。シルバーセンターのお風呂って、９カ所じゃないですか。東品川。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"一番初めに風呂ができると狭くなるということなんですけど、現在の保育園のスペースが１,０７９m2、そんなにないですか。ちょっと保育園のスペースとシルバーセンターのスペースは何m2ずつあるのかをもう一回教えていただけないでしょうか。","respondent":"小林保育課長","answer":"全体の面積をちょっとつかんでおりませんので、保育園の保有財産台帳によりますと、敷地は９９１.２４m2、建物の保育園部分が建築面積が３９５.５０、延床面積は５６２.６０m2です。","voiceIndex":30,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、現在の保育園のほうが１.５倍ぐらいシルバーセンターよりも広さとしては広いということですね。そこら辺はどういう跡地の計画ということにかかわってくる問題ではあると思うんですけれども、現在ある保育園の一部を使って、お風呂をつくるということは、今のシルバーセンターを減らさなくてもできるのではないかと思うんですけど、その辺はいかがですか。","respondent":"木下福祉高齢事業部長","answer":"ほかの目的で使えないかと、この辺も考えなければいけないということでありますので、現段階ではそういうもろもろの検討要因があるということ。その辺については今後、十分時間をかけながら、慎重に検討していきたいというのが区の立場です。","voiceIndex":34,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どちらにしても、保育園が移転した後は、今のシルバーセンターよりは広くなるということは明らかということですので、これだけ地域からの強い要望ということなので、この観点に関しては、ぜひ区のほうとしては受けとめていただきたいと思いますし、私たちとしては請願にはこたえていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この請願の中には、時期については書かれていませんし、現状、こういう要望があるので、改善をしてほしいと。それに対しては平成２１年度の保育園が移転した後ということでもあり得るということも踏まえたところで、そういうことでも、この趣旨というところで考えていくことはできるんだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問","question":"現状のところでの請願ということはそうですね。もちろん今すぐに実現できることなんて、そう簡単にはないじゃないですか。議会が区民の皆さんの今のこの願いをどう受けとめていくのかというところで、私はこちら側でそれを受けとめればいいのであって、だから決して今すぐできるできないの問題ではなく、やはり将来的なところの願いであるという受けとめ方で、私はしていけばいいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"保育園が移転した後にシルバーセンターは１階に入れば、何でエレベーターが必要になるんですかという問題も出てくると思う。基本的に要望の方の意味は十分わかっていますけれども、現在の段階でどうするかという判断をしなければ、この請願をどう取り扱うかというのはできないと、私は思っておりますので、現状においてという判断をしなければいけないかなと私は思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-022"},{"speaker":"西本委員","kind":"意見","question":"先ほども話をさせていただきましたが、やはりこの請願をきっちりと読むことが必要だと思うんですね。だから、きっちりと読んで、先ほど委員長も言いましたけれども、１階が保育園、２階から３階がというふうにちゃんと書いてあるという現状もあるし、それから将来的なことを考えるのであれば、そういう文言がやはり入ってくるべきだと思うんですね。でも思いはわかります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それでできれば、それはすぐにやっていただければ、それにこしたことはないということはありますけれども、南品川シルバーセンターは１階が保育園、２、３階が高齢者倶楽部とシルバーセンターになっていますというのは、現状のそれをそのまま書いただけですから、それに対してこういう要望がありますと。そして私はその代表者に聞きました。あったら逆に教えていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"逆に言うと、下から５行目ぐらい、「古くなった設備の交換」というのがありますけれども、ここら辺は現状でやっぱり望んでいる部分じゃないのかと、私は判断した。ですから、この中身の問題は理解しますけれども、現状でこの請願の現在の段階、さっき伺った費用対効果の面等を考えていくと、やはり現状でエレベーターの設置は難しいんじゃないかなと思っています。あくまでも現状で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、そういうふうなものまで改築のところまで延ばさなくてもいいだろうし、改築でなければできないよというものに対しては、改築のときでもやむを得ないということですから、全部ゼロか１００かということではなくて、ただ地域から出る要望というのはこういうことになるのが当たり前だと思うんですね。この品川区の実態を知り尽くした状況でやっているわけじゃないんですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-026"},{"speaker":"三上委員","kind":"質問","question":"伝わるのは何か。ですから、先ほど私が申し上げたのは何かというと、軽々に今日の段階では結論を出すのはどうかなという問題も少しありますよということがあるがゆえに、私は今日は無理して結論を出す必要はないと思いますけれども、取り上げ方については、この請願項目ということについて、明確にうたっている部分について、どう判断するかということをしていくべきではないかと、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-027"},{"speaker":"三村委員","kind":"質問","question":"区の仕組みとして、すぐ民間と違って、今日、こういう計画を実行すべきという計画を決定したとしても、すぐさまそれが実行に移されるという行政の仕組みとして、そういうものではなくて、やはり決定をしても、それから時間をかけて、計画をつくって、それから実際に建物ができるまでには、やはり何年かという時間の長さというのがどうしてもかかるわけじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-028"},{"speaker":"三上委員","kind":"質問","question":"だからこそ、紹介議員というのがいるんです。紹介議員がしっかりと請願者の皆さんのご意見を伺い、そういうことを理解したがゆえに、紹介議員になったということに通じてくるわけですから、そういうことであるならば、紹介議員にきちっとその趣旨を、どういうふうにあなたたちは受けとめたのかということを聞くということも大事なことだと私は思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"意見","question":"中身は十分わかっています。現状でという判断をどうするか。例えば道路が狭い。既存不適格だといった中で、全員が現状をきちっと把握して、じゃ、直したときにエレベーターを現状でつけたときに、どこをどう直すんだというものも見ていらっしゃるのかどうか、そこら辺からいくと、継続するのもいいかなと思っています。それで全体的な結論としては基本的に継続でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-030"},{"speaker":"三上委員","kind":"質問・要望","question":"私は先ほど、お伺いした話の中から、浴場組合との協定ということについては、やはりもう一度確認する必要もあるだろう。その上で結論は出してもいいのかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は今日、決定していただきたいと思います。それからお風呂をつけてほしいということではないということで、ですけれども、現在でもできる改善に関してはやっていただきたいという住民の方からのこの要望に対して、ぜひこたえていきたいと思うんですけれども、そういうところで、今日結論を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-032"},{"speaker":"木下委員","kind":"質問","question":"今までの議論をお聞きしていて、やはり浴場組合等の問題、それから３年後、平成２１年度の保育園の移転等で大幅に変わる等々、それともう一つ、費用が全然概算でも出ていないということで、費用対効果という点で、ある程度金額的にそんなにかからないことであるんだったら、物理的にはお風呂の取りつけ、エレベーターの設置、先ほど難しいという話ですが、防音対策ですとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"何度も言うようですけれども、この請願書をきっちりと読む必要があると思うんです。思いがいろいろあるのはわかりますが、判断をする中で、この文章そのものを素直にとるべきだとは思っております。ですから、私は先延ばしというのは、あまり請願者にとってもどうなのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-034"},{"speaker":"三村委員","kind":"確認","question":"私は先ほど出ていました、公衆浴場組合との関係というのは、やっぱりきちんと確認をしたほうがいいのではないかなとは思います。ただ、あまり大幅に先延ばしにするのではなくて、近々のところで再度議論するというようなことで、継続にすべきではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何点かお伺いしたいんですけれども、ガイドヘルパーの全身性障害の方に対しては、重度訪問介護という形で外出介助も含まれているということだったんですが、これがホームヘルプサービスのほうの時間数というのが、その人に幾らというのがあって、その中で移動支援のほうまでなかなか使えないということを聞いているんですけど、そこら辺のところの時間数と。","respondent":"西島障害者福祉課長","answer":"１点目の質問の重度訪問介護という枠組みにこれから移ってまいりますが、当然ご本人のご要望もお聞きしながら、この方が地域でできるだけ自立して、生活していくために何が必要かという観点の中から支援プランをつくりまして、その中で必要な時間については支給をしていますので。","voiceIndex":63,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、このガイドヘルパーの利用料も、例えば知的障害者のガイドヘルパーはほとんど無料で、今まで出しているという方はほとんどないんじゃないかということでお聞きしたんですけど、そこら辺のところが、ガイドヘルパーの７割が３％といっても、３割の方は１割の利用料というふうなことと、７割の方も３％になるわけですから、そういったところではほとんど無料で受けられていたサービスが。","respondent":"西島障害者福祉課長","answer":"その辺のことも総合的に勘案をしながら、検討をしています。","voiceIndex":65,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから本当に品川区の５０倍、新宿でも３０倍という形で使われているんですけれども、ほかの区もおおよそこんな感じなんですけど、こういうところと、何で品川区が特別こんなに少ないのかというようなところは、区としてどう考えられていて、これからどういうふうに改善をして、もっと使いやすくしようとしているとか、そういう研究をされている部分がありましたら、その部分に関しても。","respondent":"西島障害者福祉課長","answer":"あるいは教育委員会のほうでも青年学級とか、自主学級とかという知的障害の方を対象にした、いわゆる社会参加の事業なんかも実施をしていることの中で、そういうものが少ないのかなと思ってあります。","voiceIndex":67,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほどの続きで、ちょっとお伺いしたいんですけれども、知的障害のガイドヘルパーなんですけれども、使い勝手のよいものにということで、ちょっと確認をさせていただきたいんですけど、この厚生労働省が出している移動支援事業は目的、事業内容、留意事項と書いてありますけれども、ここのところに書かれていることを考えると、突発でも使えるようにすべきだということなので。","respondent":"西島障害者福祉課長","answer":"いわゆるショートステイですけれども、このショートステイにつきましても、やはり事前に申請をして、支援プランをつくって決めていくわけですが、確かに人間ですので、親御さんが急に亡くなったり。","voiceIndex":71,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このガイドヘルパーというのは移動支援ということで、自立支援の一般的なヘルパーとは違うということで、地域生活支援事業の区が独自にやる事業としての１つが、この移動支援ということですので、私はここのところは改めて具体的なところでは、今言ったような中身はぜひご検討いただきたいのと、あとは親御さんからの要望にこたえて、ぜひこれは改善をしていただけるように、お願いしたいと思います。","respondent":"西島障害者福祉課長","answer":"その中で支援プランをつくるときに、そういう外出あるいは通院等の分も含めて、作成するときにご本人の要望をお聞きしながら、どういう状況が望ましいのかということもお聞きしながら、プランをつくっておりますので。","voiceIndex":73,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、他区に比べて、やっぱり地域生活支援事業の内容が、実態が、実績が現実少ないというのが品川区の今の状況なのではないかと思うんですけど、そこら辺のところの実態をどう考えられているのかをちょっと教えていただけないでしょうか。","respondent":"西島障害者福祉課長","answer":"この額ですが、どういうふうに計算をされたのかというのは、国のほうから明示されておりません。都を通じまして、どういう出し方をされたのかということを確認しておりますが、国は内容については説明なし。逆に説明をしないことで、ご自由にお使いいただきたいと。","voiceIndex":75,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ただ、今回大きく変わるわけですから、移行時期ということで、実績を８割ということで組んだということでお聞きしましたけれども、その段階で、私はこれだけ低いというのにちょっと驚いたんですけれども、その中身はそういう小規模作業所や福祉ホームという、そこら辺のところがあるかどうかというところは、私はちょっとよくわかりませんけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-042"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"だから、これを別枠で受けられるようにしてほしいという趣旨であると、私は受けとめているんです。ということは突発的に対応ができないかもしれないけれども、とりあえず、今受け入れられなかった分をどうしたら受け入れられるのかとういところの努力を求めていると思うんです。ぜひその辺を前向きに受け入れていただけないかなと思うのが、まず強調したい点なので、ご答弁をお願いします。","respondent":"西島障害者福祉課長","answer":"品川区でもこの辺については十分考慮しながら、制度の構成を考えてありますので、ただ物理的に間に合わないというのは多々ありますので、その辺につきましては、区の中で十分検討はしてまいりたいと思ってあります。","voiceIndex":78,"id":"exchange-043"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"これは何回聞いても同じですので。ぜひ、そこの改善を前向きにしていただきたいと思います。これは強い強い要望です。自筆で書くと、こんな震えちゃって、読みにくいんだけど、メールだとだれでも瞬時に伝えられるということで、とても便利なので、ぜひこれは、もし国のほうで移ったんですかね。バリアになってしまうなと思うので、ぜひこの点は、検討中ということなので、ぜひいい方向で入れてほしいです。","respondent":"西島障害者福祉課長","answer":"日常生活用具としては、そういう情報伝達の周辺機器というのは大変重要だろうと考えていますので、その辺については、今、先ほどお話ししましたように、当事者も含めた検討委員会の中で、必要だということになれば、当然、それは日常生活用具として。","voiceIndex":80,"id":"exchange-044"},{"speaker":"三上委員","kind":"確認","question":"確認だけです。２番の項目について、通所施設に通い続けられるように、利用料を無料にしてくださいということは、先ほど制度の根幹にかかわると、おっしゃられましたけれども、制度の根幹にかかわるということは、これを変えてしまった場合には、法律的に違法性が生じるという受けとめ方でいいのですか。","respondent":"西島障害者福祉課長","answer":"ここを変えるというのは、区段階ではもちろんできません。国段階でこれは検討していく内容ですが、この辺のところは今お話ししたところは、制度の基本ですので、そこをいじるということはまず考えられないのではないかと思っているところです。","voiceIndex":82,"id":"exchange-045"},{"speaker":"三上委員","kind":"質問","question":"それから３番目のパソコンについてはよくわかりました。ですから、そういう考え方からすると、私はたとえ、その方に生活能力はあまりないかわからないけれども、家族として協力し合う中にあって、きちっとした負担を保っていけるということであるならば、それはそれで私はいいと。そういうことで、私の意見がちょっと入っちゃいました。","respondent":"西島障害者福祉課長","answer":"２点のご質問ですが、日常生活用具につきましては、実はあまりこれを言うと手前みそなので、言うのを控えていたんですが、先ほどお話ししましたように、日常生活用具、当事者を入れた検討会を持っているのは、恐らく品川区だけだろうと思います。","voiceIndex":84,"id":"exchange-046"},{"speaker":"三上委員","kind":"質問・要望","question":"小中一貫教育にしたって、それから公立保育園が夜間の１０時までやっているだとか、品川区はほかのところがやらないことを率先してやってきた。ですから、さらにきめ細かく、これはいろいろできることはやってあげていただきたいということはお願いしなければならないと思いますけれども、そういった団体の皆さんの要請を十分受けとめていただいて、区がきちっと対応していっていただきたいと思うところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-047"},{"speaker":"三村委員","kind":"意見","question":"パソコンの件、これから当事者でいろいろ議論されるということなんですけれども、もちろんこの中でいろいろ議論されることですが、その公共の施設で結構今、バリアフリーが進んでいますね。住宅なんかでもバリアフリーの住宅はきちんと中は一律で、バリアフリーで整備されている、そういったところでも入口に５段ぐらい段差がある。そういうような状況にならないように。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほどの２番の通所施設の利用料の問題なんですけれども、品川区が３,０００円を一律補助をしていますね。この３,０００円という考え方を教えていただきたい。","respondent":"西島障害者福祉課長","answer":"これは障害者自立支援法がまさに言っている、地域で自立して生活ができることを中心としていくんだというのが１つのテーマですので、そういう意味では在宅で頑張って通所している方について、それを応援していくんだという観点から、これは所得制限なしで一定減額を導入したです。","voiceIndex":88,"id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところでは、ぜひ通所のところで品川区が今回の自立支援で財源としてプラスになる部分というのもあるということですので、その財源を使えば、十分できることですから、このことに関しては改めて軽減策を拡大していただきたいということで、要望をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-050"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この２点目の無料のところなんですが、自立支援法の根幹に触れるところでできないというご答弁だったんですけれども、このところ、本当にこの自立支援法ができた後で、４月から実施をされていく中で、いや、こんなはずではなかった。そういった面では、ぜひこういうところも品川区として、検討していただきたいと強く思います。だから、軽減策だけじゃなくて、無料。","respondent":"西島障害者福祉課長","answer":"負担のこともありますけれども、そういうふうに考えているところですので、そのようにご理解いただきたいと思います。","voiceIndex":91,"id":"exchange-051"},{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党として結論を出すということでお願いしたいと思います。この請願趣旨は十分理解はできると思うんです。さらに、品川区としては軽減策の実施ですとか、各種検討している中で、利用料に関して言えば、障害者自立支援法の制度の基本・根幹にかかわる部分ということもありますので、本件は不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-052"},{"speaker":"三上委員","kind":"質問・要望","question":"それだけに、そういう問題が起きたときにはすぐそういうふうに言える間柄でもあるということであって、そういうことで、そういった皆さん方が強くこういうことを求められるのであれば、私も納得できるんですけれども、そういう団体からではないということになってくると、果たして自立していこうということについての考え方にちょっと違いがあるのではないかということを受けとめさせていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は採択を主張したいと思います。私はこの方の請願趣旨を読んでも、それから地域の方々で障害の子どもさんを持った親御さんからもたくさんの方からお話をお伺いしていますけれども、今回の４月からの障害者自立支援法で、本当に負担が大変になったというのをいろいろな方からも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということで、本当に障害を持ったということで、当たり前の生活を支援していくということに、すべてお金をかけていくという中で、やっぱりこれでは障害者の自立支援という名前にしておきながら、実は自立を阻害するものだということで、障害者団体の皆さんからもたくさん出ていますけれども、そういうふうなところで、品川区としてもお金がないわけではありませんから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-055"},{"speaker":"木下委員","kind":"質問・要望","question":"請願項目の２番目のところの項目にしても、これは国の問題、制度の問題で難しいものがあったりですとか、あと品川区の場合ですと、日常生活用具の検討会ですとか、先ほど入札制度の取り入れを検討しているですとか、他の自治体がまだやっていないようなことも積極的に取り入れて、対応をなさっているですので、私としては今回のこの請願、お気持ちはわかりますけれども、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問・要望","question":"今日、結論を出していただきたいと考えています。この請願の趣旨は本当によくわかります。ただ、項目になってきますと、例えば１番のところでは、ほかの方法・手段として手立てがあるような感じでしたし、利用料ということになってきますと、これはちょっと別次元の問題になってきてしまう。制度がわからなかったのか、それともどういうふうだったんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-057"},{"speaker":"三村委員","kind":"意見","question":"本日採択ということで、結論を出すというべきだと考えています。結論といたしましては、今回、２番目が制度の根幹にかかわる問題というところで、なかなか実現が難しいということでありましたけれども、私どもとしては、この制度の根幹そのものに問題があるのではないかということで考えておりますので、ぜひ採択をしてほしいということで結論を出しております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-058"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"確認をさせていただきたいと思います。内容の中で、定員が一時預かり１４人と書かれているんですが、短時間の契約保育というのは、そういう規定があるのかどうか、それに対する保育士の設置条件はどのぐらいになるのかというところをまず教えてください。","respondent":"小林保育課長","answer":"これをもとにして、今考えております場所が、建物全体として１５坪、５０m2ぐらいありますが、いろいろな設備もありますので、そうすると、３０m2程度が保育施設になるということで逆算をして、設置基準に照らし合わせまして、１４人が限度という形になっておりますが。","voiceIndex":107,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"わかりました。それと、この助成金ですけれども、これはいつまでということ。一時的なものなのか、それとも長く続くようなものなのか、それとも将来的にはここが独立していって、助成金がなくて成長していくというのを見通したものなのか、いかがですか。","respondent":"小林保育課長","answer":"現時点での事業フレームとして、この金額が運営費として継続されるというふうになります。","voiceIndex":109,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"今、空き店舗の利用というところではいろいろ出てくるかと思うんですけれども、そういう場合には、やみくもにいいですよというわけにはいかないと思うので、その選考とか、それから今後の考え方、当然たくさん増えることは確かにいいんですが、中身的なものもきちっとしたものでないと、子どもの命を預かるという施設ですので、そこは責任の所在も含めて考えると、中身をきちっとして増やしていくんだったら。","respondent":"小林保育課長","answer":"基本的な考え方は、先ほど若干着眼点のところでご説明させていただいたんですけれども、地域の資源を生かしてということで活動しておりますので、ちょっとビジネスベースにはなかなか乗りにくいと考えております。","voiceIndex":111,"id":"exchange-061"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この事業は、保育課と産業振興課の協働の事業だということで、私も以前、空き店舗対策で一般質問のときに、保育のこういった商店街のところで行われたらどうかなという質問を１回したことがあるので、ぜひ慎重にというか、本当に成功していただきたいなと。子どものためにも、あと商店街にとってもいい方向に進むといいなと考えています。","respondent":"小林保育課長","answer":"団体ということから言えば、事業主体となる商店街は、あくまでも商店街としての商業機能と同時に、地域への貢献という視点で事業に取り組むわけですが、ご説明しましたように、保育については経験がないという中で。","voiceIndex":113,"id":"exchange-062"},{"speaker":"飯沼副委員長","kind":"意見","question":"おばちゃんちの活動なんかを見せていただくと、すごく異年齢というか、経験の豊かな方から、若いお母さんたちの交流も深まっていて、すごく子育て支援の輪が広がっているなと思いますし、今後、多分こういうところが拠点になって、ボランティア、支えあいもできていくんだろうなと思いますので、ぜひ見守りながら、育てていただけたらいいなと思っていますし、もし成功しましたら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-063"},{"speaker":"三村委員","kind":"質問","question":"健康センターに乳幼児の利用、検診やなんかで、とても乳幼児を連れた方がいらっしゃる率が高いですけれども、そういった検診やなんかとのリンクだとか、検診の際に情報提供だとか、そういう複合的にいろいろ商店街のほうに新しいお母さんたちが流れていってもらえるような仕掛けまでいろいろ考えられているか、その辺のところをちょっとお伺いしたいと思います。","respondent":"小林保育課長","answer":"それから地元のポイントカードと連動はできないか。いろいろな点を今、検討していると承っておりますけれども、まだシステム的にまとまって、こういうふうにしてみたいというところのご提案まで、まだいただけていない現状です。","voiceIndex":116,"id":"exchange-064"},{"speaker":"木下委員","kind":"質問・要望","question":"すみません、ちょっとお聞かせ願いたいんですが、事業目的のところで、商店街とＮＰＯ法人が協働してということで、実施主体が特定非営利活動法人、東海道品川宿ということですけど、この特定非営利活動法人、東海道品川宿をつくっているのが、例えば商店街ということですから、品川商店街なんでしょうか。どこの商店街がやっていらっしゃるのか、教えていただきたい。","respondent":"小林保育課長","answer":"９時から５時という関係ですけれども、これにつきましては、まず内容で短時間の就労というのも視野に入れておりますが、主力はやはり常勤フルタイムではなくて、在宅で子育てをしている方の一時利用というのがむしろ大きな柱になっているという点からしますと。","voiceIndex":118,"id":"exchange-065"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"何点か基本的なことだけ確認をさせていただきたいです。ちょっとそこら辺が気になっているのと、もう一点、議員が２年になるだろうという話があったんですけど、例えば品川から入っていったときに、任期が２年なのか、２年でなく、例えば中途で１年で交代した、変わった、降りたなんていったときには、品川の中からそのまま補充ということではなく、新たな選挙になるということなんですか。","respondent":"冨岡高齢事業課長","answer":"私の説明がちょっと不足で申しわけないと思うんですが、この準備委員会に、まず検討委員会でこれだけの原案を渡したわけです。それを今、準備委員会でいろいろなご意見をいただきながらまとめている段階です。それがまとまりますと、規約案となります。","voiceIndex":124,"id":"exchange-066"},{"speaker":"鈴木（真）委員","kind":"質問","question":"まだ確かに固まっていないということで、大変難しいと思います。我々の中でも事務所の場所の問題は、いろいろ品川の中にも出ていたと思うんですけど、これは行政側としても同じように、飯田橋のほうに移る意向になっていたと思いますけど、最初は旧区政会館というお話があったんですけど、そこら辺は区の考えが伝わっていると判断していいんですか。","respondent":"冨岡高齢事業課長","answer":"ちょっと言い忘れましたけど、今回の区長会で、今、区政会館を借用できないかということで、協議会に話をいたしまして、それは大丈夫だということになったそうです。区といたしましては、区政会館を借用するという方向で話を進めたいと聞いています。","voiceIndex":126,"id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして準備委員会の構成が、特別区長会代表が６人ということになっていて、区がかかわれるところはここの６人と、事務局の構成員のところの１２人ということかなと思うんですけど、ここのところはどこがかかわっているのか、品川区は入っているのかどうなのかということをひとつお聞かせいただきたい。保険料がどういうふうに決まっていくのか、そこら辺の基本的なところを教えていただけないでしょうか。","respondent":"冨岡高齢事業課長","answer":"今まで出てまいりましたのは、議会説明用に３,１００円ずつで６,２００円、１年で７万４,０００円というのが出ておりますけれども、具体的なものはまだ示されておりませんので、それが４月に示されるということです。","voiceIndex":128,"id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこの中身についての区議会への報告ですとか、区議会の中での審議ですとか、区議会がチェックできるような場面というのはなくなってしまうんでしょうか。あるんでしょうか、そこら辺のところをちょっと教えていただきたい。","respondent":"冨岡高齢事業課長","answer":"徴収の部分につきましては、区のかかわりがあります。それから、特別会計をつくりますので、その部分では当然ご審議いただけると考えております。","voiceIndex":130,"id":"exchange-069"}]},{"id":"topic-03","title":"その他を先に議題に供します。 (1)所管質問につきまして","agenda":"その他を先に議題に供します。 (1)所管質問につきまして","exchanges":[{"speaker":"三村委員","kind":"質問・要望","question":"前回、質問させていただいたので、新たに質問とかというのではなくて、スケジュールをいただきたいということだったので、きょう、特に質問するということではなかったので、特段この場ではありません。スケジュール等を教えていただきたいということで、先日お話しした内容が質問のすべてです。","respondent":"須藤委員長、西島障害者福祉課長","answer":"わかりました。今、お手元に全体的な策定スケジュールをお配りいただきましたので、西島障害者福祉課長からご説明をお願いいたします。それで、第２回の策定委員会を１０月に予定してございまして、地域生活を支えるために必要な支援体制整備の検討を予定しています。","voiceIndex":134,"id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3158#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":74732,"voices":144}},{"id":"h18-20060926-8","meetingId":"h18-cm09","date":"2006年9月26日","dateIso":"2006-09-26","committee":"建設委員会","time":"午前１０時０３分～午前１１時５５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"最初に(1)の「公園の安全点検ボランティアの募集について」","agenda":"最初に(1)の「公園の安全点検ボランティアの募集について」","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"何点かお願いします。常時公園を利用しているのは保育園の子どもたちというところもあるので、その辺は一つ、仕組みとして考えていただきたいなということを要望して質疑を終わります。","respondent":"藤田道路公園課長","answer":"任期は１年更新かですけれども、基本的には、ボランティアは１年限りで終わりという形でやってはあまり効果がないと思っていますので、複数年続けられる方というのが中心なのかなと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"なぜかというと、埼玉でプールの事故が発生したり、また、公園の遊具での子どもたちのけがや事故も残念ながら起きる中で、安全に対する点検というのは、保護者の関心からしても二重にも三重にもという思いがありますので、公園の安全点検の責任はどこにあるのか伺いたいと思います。","respondent":"藤田道路公園課長","answer":"そういった中で、私どもの職員による点検、あるいは遊具の専門メーカーによる点検、あるいは今回のあるある点検隊による点検ということで、今、お話があったとおり、二重、三重の形で安全に関する点検を行っていきたいというのが私どもの考えです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"区が設置した公園ですから、責任は区にあるということですけれども、きょうの資料の概要にも、公園の遊具の腐食やねじの緩み、死角。利用者の意見を聞く上で、公園全体を見て意見を伺う、これは大切な視点だと思いますよ。だけど、点検ということは、直接維持管理にかかわることですから、これはどうしても、あるある点検隊の役割としてよくわからない部分があるんですね。","respondent":"藤田道路公園課長、福田まちづくり事業部長","answer":"先ほど、私の口頭での説明の中で申し上げましたけれども、現在、公園の点検のほうは、私どもの区による日常管理の中での点検、あるいは専門業者による年１回の点検、これは行ってあります。しかし、そのことは同時に手段です。この概要の一番最後の行にありますけれども、これらのことを通して、公園との結びつきを図りながら、その地域のコミュニティーを醸成していく、これがこの事業の最終的な目的です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"確認","question":"点検ということは、直接事故に結びつくことを未然に防ぐことですから、お話ししましたとおり、明確にする必要もあるのかなと。つまり、お答えにもございましたように、日常管理が現状どうなっているのかというところを伺いましたけれども、区内に公園はたくさんあるかと思いますけれども、日常行政として、今後、安全管理、どのぐらいの体制で、どのぐらいの頻度でやっていくのか。","respondent":"藤田道路公園課長","answer":"現在、区内の公園ですけれども、最低でも月に２回、公園の清掃等に回っています。その中で危険箇所の発見があれば、当然それにあわせて対応しています。","voiceIndex":12,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"最後に、あるある点検隊ということで、何人かのグループで動くんでしょうかね。点検隊員というのかわからないですけど、ボランティアの方たちが点検する際に、公園では職員の方がつくのか、業者の方がつくのか、どういう形で点検していくのか。点検の内容からして、どういうふうに行うか、仕組みを教えていただけますか。","respondent":"藤田道路公園課長","answer":"そういった形で点検したものを、私どもの区のほうに「こういった点検結果でしたよ」というご報告をいただき、それにあわせてすぐに対応すべきこと、あるいはもう少し時間がかかるもの、それらを区分けし。","voiceIndex":14,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"日常的な公園の維持・管理、安全点検を行政の責任として管理していただきたいということを申し上げて終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"これは当然、責任問題になりますので、ボランティアの方がうっかり直して、それが外れて子どもが事故に遭ったら大変ですから、その辺気をつけてください。それと、これは公園の安全点検ということですが、道路公園課では防災活動広場も管理していますけれども、防災活動広場はこれには入らないという解釈でいいですか。","respondent":"藤田道路公園課長","answer":"私どもが管理している公園・児童遊園、児童遊園の大くくりの中には防災活動広場も入ってありますので、すべてのそういった箇所が対象ということになります。","voiceIndex":19,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"それじゃ防災活動広場も入るということですね。そうすると、すべて防災活動広場、児童遊園、公園、大きな公園を含めて、何カ所ぐらいあるんですかね。大体の数で。","respondent":"藤田道路公園課長","answer":"約２２０カ所あります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"申し込みは個人でなく、団体で３人以上からということですけれども、これは責任の所在とかいろいろな問題があるんでしょうけれども、子どもたちの目線で見なくちゃいけないということがまず第１にあると思うんですが、どういう団体を想定しているんですか。あるいは何か、そういう協力団体にならなくちゃいけないんですか。そういう規約じゃないですけど、どんな団体を想定して、どう思っているんですか。","respondent":"藤田道路公園課長","answer":"私どもは、まず、公園の中で安全に遊んでもらうためということを、今回１番の手法として考えてありますので、そういった面では、子育て世代といった方々に積極的に参加していただければということで、ＰＴＡあるいは保育園・幼稚園。","voiceIndex":23,"id":"exchange-009"},{"speaker":"藤田委員","kind":"質問・要望","question":"次の人が入って、開けるときに金具が非常に危ない。けがはしなかったけど、これは危ないとおっしゃって出てきたんですね。ただ「点検だけしていただきます」「わかりました」というのではなくて、すばやい体制をとっていただきたいというのを要望しておきます。ぜひとも地域センターの職員の人にも、こういう説明がありましたらちゃんとお話ししてくださいよ」という体制でぜひお願いしたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ボランティアでということなんですけれども、そのレベルはどの辺を求めているのかなというのがあるんです。ボランティアで来てもらう人にはいろいろな方もいると思うので、どの辺まで要望するのかということと、あと、今、専門業者が年１回やっておるということで、ボランティアが入ることで通常の回数が減るのかということが、まず１点目です。","respondent":"藤田道路公園課長","answer":"今までと同じように管理をする中で、そういったボランティアの方々に違った目線で見ていただいて、「こういうこともあるんだ」というような視点で私どものほうに声を上げていただき、それにあわせて、安全・安心な公園づくりに努めていきたいと考えておるところです。","voiceIndex":26,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"例えば安全以外の点で要望が出される場合というのはありますよね。そういうものはどういうふうに答えるのかということと、頻繁に地域との関係というのができてくると思うんですけれども、そういう要望が出てきたときにどうするか、教えてください。","respondent":"藤田道路公園課長","answer":"いろいろなケースのお話があると思いますので、一概には言い切れませんけれども、声が上がってきたこと、それが公園の中で起きていることですので、それについてはお話をお聞きした中で、必要な、あるいは適切な対応をそのつどやっていかなければいけないと考えています。","voiceIndex":28,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問・要望","question":"先ほど、３名以上でということなんですけれども、これに一たん登録してやるわけですけど、その中で人が変わったりとかということになってくるんじゃないかと思うんですけど、それは登録というと、ある意味ではボランティアでやってやるという感じなんでしょうけれども、もう一方は派遣でしっかりフォローするというのがあるので、その辺をどこまで求めるのかというのが。","respondent":"藤田道路公園課長","answer":"だから、そういう話の中で、例えばメンバーが変わってきて、そういった中で、当初の視点が、例えば遊具中心だったものが、だんだん死角はどこにあるんだといった視点に変わってくることもあろうかと思いますけれども、それについては、私どもは特に「じゃあ。","voiceIndex":30,"id":"exchange-013"},{"speaker":"大西副委員長","kind":"質問","question":"私の家の前にも公園があって、関心を多くお持ちの方もおられると思うので、私もちょっとお尋ねしたいんですが、個人で、別に知り合いは特にいないけど公園をよくしようと。それについては自分もボランティアに参加したいなという人が、このかたちだと団体だということで加われないんだけどという場合はどうするのか。なぜ３名以上なのか。なぜ団体という形なのかということについて教えてください。","respondent":"藤田道路公園課長","answer":"ただ、個人からいただいた声、私どもはこれを別に聞かないということではございませんので、ボランティアというかたちではありませんけれども、お声を聞きながら公園をよくしていきたいと考えています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"大西副委員長","kind":"質問","question":"こういうボランティア活動に参加して、問題点を自分たちで見ていきたいんだという個人の参加を、これだと拒んでいる形にならないでしょうか。グループの人たちで「何日にこういうところを見に行きたいのでどうでしょうか」という形のものがあってもいいんじゃないか。個人での参加をどうしても妨げる合理的な理由が、今一歩薄いような気がするんですけれども、その辺はどんなもんでしょうか。","respondent":"藤田道路公園課長","answer":"一つの公園の安全点検のボランティアという手法ですけれども、これを通して地域コミュニティーをつくっていくんだですので、そういったイメージで、まずはグループでの参加を促しています。","voiceIndex":34,"id":"exchange-015"},{"speaker":"大西副委員長","kind":"質問・要望","question":"地域のコミュニティーは、僕は個の集まりだと思うんですよ。それは、今まではコミュニティーがなかったものが、一人一人の参加が５人になれば５人のコミュニティーになりますよね。別個に考えると、ちょっと特殊な、お１人の方で参加されるという部分を排除したいという何かがあるのかどうかわかりませんが、そういう１人の方の意見も一つ大切にしていただければという、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問","question":"公園の施設というんでしょうか、例えばこことかということじゃなくて、いろいろなところを見てもらうということですか。","respondent":"藤田道路公園課長","answer":"そういった形で、区のほうから「この公園を点検してください」ということではなく、地域の方々が点検したい場所、それを決めていくというような形で考えています。","voiceIndex":37,"id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"そのときに、今、公園が乳幼児だけの施設というふうに考えてしまうことが少し問題だなと思っているので、ここの参加対象者というところで、特に乳幼児というふうにこだわらなくて、高齢者の方々もほっとできる公園というのを、今は求めている。この表記だけはちょっと検討いただいたほうがいいかなというのを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-018"}]},{"id":"topic-02","title":"の「都市高速道路中央環状品川線工事説明会について」","agenda":"の「都市高速道路中央環状品川線工事説明会について」","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"今回は、こういった発進立坑の設置工事をやるので、その説明ということで、地元の八潮北小学校での説明だと思うんですけれども、今、東京都がメインだろうと思うんですが、説明会というのは、今回は発進立坑の説明会ですが、全体で何回やる予定になっていますか。","respondent":"阿部都市計画課長","answer":"今回の説明会も全体ですけれども、例えば今回は発進立坑ですけれども、八潮北につきましては、今後、シールド工事が当然入りますので、あと、各所に予定されておりますので、その工事ごとに説明会を行うという予定です。","voiceIndex":45,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"今回はその工事の直近が対象なのかなと、地元の方々に対してということなんでしょうけれども、説明会も、かなり大きな工事でもあるし、私はもっと区内全体に拡張した説明会でいいんじゃないかと思うんですけれども、今までので行くと、大体換気所設置だとか、そうということでの説明があったんですけれども、そのほかでの説明会の予定というのはないでしょうか。もうちょっとここから離れたところで。","respondent":"阿部都市計画課長","answer":"計画段階、あるいは先ほど申しました事業説明会の段取りは、当然全線の説明ですので、かなりの箇所で行いました。ただ、今回はあくまでも具体的な工事の説明会ですので、今ご指摘があったように、今回は大井北発進立坑ですので、その地域について説明会をする。","voiceIndex":47,"id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"工事そのものの説明はそれでいいんですけれども、区の説明でも、例えば換気所から拡散して来る排気ガスがかなり広範囲になるという説明なんですよね。広範囲に拡散するということになると、逆に、今回は工事説明会ですけれども、この品川線そのものの説明というのはもっと広範囲にやるべきじゃないかなと思うんです。そういうことは、行政のほうはどういうふうにお考えですか。","respondent":"阿部都市計画課長","answer":"この問題につきましては、工事説明会の中で、事業者が説明を求められれば随時説明をするということを申していますし、事業説明会の後も、私どもが事業者、具体的には幾つか事業者がありますけれども。","voiceIndex":49,"id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問・要望","question":"個別個別の対応を見たら、私はそういう範囲じゃないんじゃないかと思うんですね。さっきも言ったように、排気ガスが広範囲に拡散するということですから、そうなると、もっと広範囲に説明を、これは、求められればということではないと私は思うんですね。その中でガスが拡散するわけですから、それなりに住民の健康被害に配慮して、やはり全体でやるべきだと思います。","respondent":"阿部都市計画課長、福田まちづくり事業部長","answer":"説明会につきましては、先ほど申し上げた事業説明会、あるいは区の申し入れ、それに対しても現在説明を求められている、求められたということは１件もございませんので、そういう状況です。説明会といいますのは、３種類あります。一つは、今課長が申しましたアセスメントの説明会。これは都市計画決定の前に行われる。これは、東京都もかなり広い範囲でやったというふうに私は聞いています。","voiceIndex":51,"id":"exchange-022"},{"speaker":"宮崎委員","kind":"意見","question":"法的根拠がなければ、逆にもっと配慮した説明会をやってほしい。環境アセスが出たと。僕らはいろいろ異論はありますけれども、逆にそうであれば、それを周知徹底させようとか、そういういろいろな活動があってしかるべきかなと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"範囲は半径５００メートルで、方法は各戸にというお話ですけれども、もう一度、５００メートルにした理由をお伺いしたいのと、この５００メートル範囲は何世帯ぐらいになるんですか。","respondent":"阿部都市計画課長","answer":"先ほど申しましたけれども、今回の説明会については法的な根拠はございませんけれども、実際に工事が始まるわけですから、どういう工事になるんだろう、あるいは何をしているんだろうということを皆さん考えていらっしゃることを考慮して。","voiceIndex":57,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"今、５００メートルにした理由というんですか、周辺の方々もどんな工事が始まるんだろうと、そういう気持ちもあるでしょうから開くんだという話ですけれども、であるならば、この品川線の問題、いわゆる環境の影響の問題をとっても、あと、いわゆる税金の使い方をもって、関心が寄せられている。行政としては、住民の皆さんにできるだけ理解を得るために繰り返しやる姿勢でいるのか、そこだけ教えてください。","respondent":"阿部都市計画課長、福田まちづくり事業部長","answer":"どういうテンポでやるのかというような趣旨ですけれども、今回はあくまでも立坑の工事説明会ですので、東京都の意見としては今回１３日を１回予定しているです。何回やるかというのは、それは施工者、事業者が適切な判断をするだろうとは思っていますが、区はこの件に関して、先ほど申し上げたアセスの前後から。","voiceIndex":59,"id":"exchange-025"}]},{"id":"topic-03","title":"の「青空野球場の返還について」","agenda":"の「青空野球場の返還について」","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"そうなると、Ｂ面、Ｃ面、三つ東京都に返すということと、そのかわりに南埠頭公園を区に移管してもらってそこを野球場にするということと、大井ポートグランドを野球場にということで、大井ポートグランドというのは、私は承知していませんが、大体どの辺なのかということと、優先使用枠というのは何年使えるだとかというような、優先使用枠の中身とか、それと、この図のほうを見ると。","respondent":"松代管理工事課長","answer":"そうすることで、利用時間帯、利用枠数がかなり広がってまいりますので、ここで何とか青空野球場の８割ぐらいは利用可能な状態にしたいというような考えを持って、今、計画しています。","voiceIndex":66,"id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"南埠頭公園のほうは、人工芝とナイター設備をつくるということで、大体日中だけ使っていたのが夜も使えるということですが、東京都の職員が優先的に使っていたわけですか。東京都の職員ではなく、港湾ですか。今の説明では、使用枠といっても、優先というかあきのところ。今まではあきのところというのは何かほかに使っていたのか。","respondent":"松代管理工事課長","answer":"そういったところを使ったらどうですかというお話で、それにプラス、早朝枠を少し広げていただいて、青空野球場は早朝に使われる方、例えばタクシーの運転手さんとかが勤務明けで使えるとかそういったもので利用がありましたので、そういったところでもあきスペース。","voiceIndex":68,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"意見","question":"私も野球の細かいことはわからないんですけれども、結局、今のお話だと、３面返して、１面は確保するけれども、ポートグランドのほうはかなり肩身の狭い思いで使うのかなという感じがするんですけれども、今もかなり詰まっていますよね。そうすると、かなりとれなくなるかなという気がするんですけれども、実際問題、あとほかにどこか申し込みするようなところはないのかな。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"都の説明がそうだったんですが、このポートグランドも、あくまでも南埠頭公園の野球場としての整備後の引渡しまでの利用になります。こちらの野球場については、通常９時からの運用という形になっておりますけれども、できますれば、来年４月から早朝枠を設置したいということで考えておりまして、今、その準備も進めているところです。","voiceIndex":70,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問・要望","question":"野球も面数がないと利用率が低くなっちゃうということになるので、時間を広げるだとか、そういう努力はしていただきたいと思うんですけれども、東京都にも、例えば他の公園を何か利用できないかとか、交渉していかないと大変なような気がしますけれども、そこら辺のことはどのように考えていますか。","respondent":"岩田まちづくり事業部次長","answer":"ただ、そうは申しましても、突然のことでしたので、区としても、急に言われてすぐ返却するというのは、利用者も多いわけですから、そこら辺のところを少しよく検討してほしいということで、かなりぐずりました。","voiceIndex":73,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今のことを努力していただくということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-030"},{"speaker":"松澤委員","kind":"質問","question":"この大井南埠頭公園は、現状として、公園の利用実態というのはどんなものですか。","respondent":"松代管理工事課長","answer":"海上公園として面積は約６,０００m2あります。主な施設としましては、芝生広場がありまして、前に埠頭があって、非常にうっそうとした中に公園があるような、静かな公園です。利用実態ですけれども、私も五、六度行きましたが、ほとんど利用されておりません。","voiceIndex":76,"id":"exchange-031"},{"speaker":"松澤委員","kind":"意見","question":"公園をつぶして野球場にするとなると、品川区の場合は大騒ぎになって、今のお話の中で、隣地を買収してそこを公園に広げるということなので、公園としての機能はある程度ありますね。これはナイター設備も整えるということですけれども、大田区にある大田スタジアムのような、ああいうような形の、大きな１面の野球場にするとか、そういうような計画ではないんですね。","respondent":"松代管理工事課長","answer":"大田区のシステムにするには２ｈａぐらい必要ですし、バックヤードも当然必要になってまいりますし、設備投資も莫大な費用がかかります。大田区のグラウンドは、一般区民のみならず、プロ野球等の利用もしていますし、そういう意味での目的、利用実態等が違います。","voiceIndex":78,"id":"exchange-032"},{"speaker":"松澤委員","kind":"質問","question":"野球場で問題になるのは、いつでも駐車場の問題なんですね。これぐらいなら足りますよという形でつくりますけど、必ず足りない。どこでもそうなんですけど、つくればつくるほど車で来る。その辺の、駐車場の用地というのは十分に確保する計画になっているのか、その辺を伺います。","respondent":"松代管理工事課長","answer":"ただ、残念ながら、今回挙げられている公園が６,０００m2、そして新たに設けようとしていますのが、できるところで１,５００～１,６００m2といったところで、野球場の施設としては十分満足のいくものではありません。","voiceIndex":80,"id":"exchange-033"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、現状、うっそうとしたという形ですから、できる完成予想図はうっそうとした構造なのか、ちゃんとお願いします。","respondent":"松代管理工事課長","answer":"まだこういう事態ですし、我々は緑をぜひつくりたいという立場でもありますので、とにかく事前に港湾局と相談をしまして、今の植栽はできる限り移植を考えておりまして、港湾局の新たな公園を造成する場所に、ほぼ、すべて移植できるような形で、今、調整を進めているところです。","voiceIndex":82,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"８割がよくわからなかったので教えていただきたかったのが１点と、もう一つが、現状の青空野球場、先ほどの説明ですと、無料でやっているわけですけれども、現状どおりの利用方法で引き続き考えているのか、教えてください。","respondent":"松代管理工事課長","answer":"青空野球場の利用実態をそのままとするとそのぐらいになるんじゃないかというシミュレーションです。新たな野球場の形態にしますと、有料ということで、入場料等はきちんといただくつもりでおります。これは天王洲野球場等々と同様に考えていきたいと考えています。","voiceIndex":84,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、現状、無料で使っている施設ですから、時間帯の枠はどのように設定したのかわかりませんけれども、現状を維持するというのが、利用者にとっては必要なことではないのかなと思うんですけれども、そこを教えていただきたいのと、もう一つ、測量・設計を行うということですけれども、どういった形状になるのか、どういった利用料金設定になるのか、この辺の詳細を頻繁に報告していただきたいです。","respondent":"松代管理工事課長","answer":"その有料化にする単位は、天王洲野球場と同等の施設内容になろうかと思いますので、多分天王洲とほぼ同じような料金体系になろうかと考えています。ただ、その料金体系等のものについては、今後、建設委員会のほうにしかるべきときにご報告申し上げたいと考えています。","voiceIndex":86,"id":"exchange-036"}]},{"id":"topic-04","title":"品川周辺地域都市・居住環境整備基本計画について","agenda":"品川周辺地域都市・居住環境整備基本計画について","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"９ページの図のシミュレーションがどうにもわからないんですけれども、建物の配置を工夫したケースの図があるんですけれども、どう工夫したんでしょうか。","respondent":"青木都市開発課長","answer":"大変申しわけないですが、これ以上詳しい専門的なことになると、私もここではご説明できかねますけれども、そういったイメージで、風の流れを建物の配置等で誘導していくということをここで論じております。","voiceIndex":92,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"見た感じですけれども、例えば高輪プリンスと書いてあるところに高い建物が建つんですかね。その右上にも３棟建つんですかね。風の通りがよくなるというよりも、悪くなっていくように見えるんですよね。速くなっているというのは、これはビル風になるんですか。何かこう、これでよくなるという説明では、なかなかそうは思えないんですけど。","respondent":"青木都市開発課長","answer":"そういったもので、開発が見込まれる中でもどのような工夫をすればいいかということでシミュレーションしておりますので、図４というところで、同じ絵ですけれども、十分な隣棟間隔を確保して高層建築を建てるとか、つまり。","voiceIndex":94,"id":"exchange-038"},{"speaker":"中塚委員","kind":"確認","question":"僕もまだこれをしっかりデータを確認しているわけじゃないですけれども、これによってヒートアイランドを抑える涼しい風が入るんだといいますけれども、逆に、再開発が海からの涼しい風を邪魔して、ヒートアイランドを引き起こしているんじゃないのかなというふうにも見えるんじゃないかなと思うんですね。きょうはこれ以上やりませんけれども、どうも資料に説得力がない。","respondent":"岩田まちづくり事業部次長","answer":"この委員会には、私も委員としてずっと出ていたんですが、これだけ見ますと、こんなふうに開発がされるのかなと誤解をするんですが、実はこの間に１００種類ぐらいの同じようなシミュレーションをやっているんです。","voiceIndex":96,"id":"exchange-039"},{"speaker":"宮崎委員","kind":"質問","question":"地表面のところと、確かにビルの上のほうで、風が違うというのはわかるんですけれども、地表面ではどういうふうになるんですか。それから、このシミュレーションは全体の風速は、これは４メートルをシミュレーションしているんですか。風のないときは、全く風を通さないで壁になっている、大体そういう状況だと思います。","respondent":"岩田まちづくり事業部次長","answer":"当然、都市機構から専門的な、おそらく大学でやっていると思いますが、こういったシミュレーションをコンピューターにかけてやっているという説明を受けました。","voiceIndex":98,"id":"exchange-040"},{"speaker":"宮崎委員","kind":"意見","question":"今回は風の流れだけのようですけれども、さっき私も言ったように、ビルをつくることそれ自体がエネルギーを消費して熱を出している。そういう意味で、もしかしたらこういうビルの建て方をすれば、それが壁になってこっちに向いている風がこっちに行くんだという、こじつけの発想かななんていう感じはするんですけど、全体的な熱がどうなるのかというのは、これだけじゃさっぱりわからない。感想ですけど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-041"}]},{"id":"topic-05","title":"その他」を行います。 まず、(1)の「所管質問","agenda":"その他」を行います。 まず、(1)の「所管質問","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"１６３のほうは、大井１丁目南地区というところがそうなのかもしれないんですが、ここについて言うと、１６３号線の商店街の方たちがかかわりを持つように思うんですけれども、そういったところで、連携をした情報提供がされていないというようなことを地域の住民の方々から伺っておりましたので、その辺はどういうふうに進められようとしているところなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"みどりのモデル地区なんですけれども、私は、このみどりの条例の中で、みどりのモデル地区というところでは、ここに書いてあるように、緑被率という視点でいくと、現在ある木というような形で考えていたので、先ほどのお話だと、苗木だとか、そういったところで、「花とみどりのボランティア」なのかなというのが、今、わかったんですが、建設委員会の請願なんかでも。","respondent":"藤田道路公園課長","answer":"モデル地区につきましては、みどりを守っていこう、あるいはもっともっと増やしていこうという観点で、地域でできることをやっていこうというようなものですけれども、今の委員のお話からすると、みどりの条例の中でいうところでは。","voiceIndex":108,"id":"exchange-043"},{"speaker":"井上委員","kind":"意見","question":"じゃあ、ちなみにその協定というところでは、今の実績とか、どういうふうになっていますか。","respondent":"藤田道路公園課長","answer":"今のところございません。","voiceIndex":110,"id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"せっかくみどりを増やそうということで、屋上緑化とか、品川区がいろいろ取り組んでいる中で、この制度があって実績がないということで放っておかないで、何がデメリットなのか、また利用されないのかというところの評価・検証というところが必要かと思うんですけれども、その辺の検討の結果なんかはいかがですか。","respondent":"藤田道路公園課長","answer":"今回、みどりの条例を使った形でのみどりの協定というのはございませんけれども、地域の方々で、地域のみどりを守っていこうというような姿勢の中で、池田山等の地区につきましては、環境協定ということで、そういったみどりと太陽の道。","voiceIndex":112,"id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"地域の人たちの約束ごとというのは、そこに区が何らかの関与をするというものではないということですか。区との協定でしょうか、区民同士の協定でしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-046"},{"speaker":"井上委員","kind":"質問・要望","question":"この都市計画の方なんですけれども、このことについては、こういう仕組みの中で区がどういう、地域の方々が動き出さないと、再開発ということで指定をしていくものなのか、この辺の区の関与というかその辺がどういうふうに進められていくものなのか教えていただきたい。","respondent":"青木都市開発課長","answer":"先ほどご説明しまして、資料にもありますとおり、地元の方々は、再開発準備組合という名前で組織をして、まちづくりを進めていきたいということでお話をいただいておりまして、当然、想定されておりますのは、法定の再開発事業であろうと、私どもはそう伺っております。","voiceIndex":117,"id":"exchange-047"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今の、大井１丁目の南地区のことなんですけれども、地域の方が４９名でおいでになったということで、もうちょっと準備組合について教えてほしいんですけれども、今、地権者が何名ぐらいかとか、どういう方が中心になってやっているのか。今の時点でどんな交渉をしているのか、できるだけ説明いただきたいと思うんですけれども。","respondent":"青木都市開発課長","answer":"大井１丁目南地区の権利者等の関係ですけれども、設立時点でのご報告いただいているもので、土地所有者が６３名、借地権者が１４名、借家人等については正確な数字は把握できていないということでしたけれども、約１４０名に上るだろうということでご報告をいただいております。","voiceIndex":119,"id":"exchange-048"},{"speaker":"中塚委員","kind":"意見","question":"指定管理者制度の件についてなんですけれども、昨年度からいろいろな案件がでているので、審議に必要な資料を、ぜひみんなで意見を交流し合いながら、行政の審査以外の審査にふさわしい議論をしていきたいと思うので、そのことについての資料提供をお願いしたいです。","respondent":"伊藤委員長","answer":"どういう思い、アイデアでも結構ですので、全部が全部できるわけではありませんけれども、話がないことには私ども正副でも議論のしようがありませんので、今のような意見をどんどん出していただければと思います。","voiceIndex":129,"id":"exchange-049"},{"speaker":"井上委員","kind":"提案","question":"先ほど委員長もおっしゃっていたように、委員会を活性化するために委員同士が議論、今だと理事者に質問をしていく中で問題を明らかにしていくということで、その問題を委員会の中で、委員同士が発言できるような、それがどういうふうな仕組みでできてくのかわからないですけれども、その辺をもっと、委員同士がその問題に対して議論ができるような方向で何とかできないかなということを考えたいということと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3862#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":33267,"voices":132}}]);
